pub fn get(&self, provider_id: &str) -> AppResult<Option<String>> {
    match fs::read_to_string(self.path(provider_id)?) {
        Ok(text) => {
            let key = text.trim();
            Ok((!key.is_empty()).then(|| key.to_owned()))
        }
        Err(e) if e.kind() == ErrorKind::NotFound => Ok(None),
        Err(e) => Err(io_error(e)),
    }
}

