fn cited_sources(text: &str, listed: &[String], cited: &HashMap<String, Source>) -> Vec<Source> {
    let mut ids = cited_ids(text);
    for id in listed {
        if !ids.contains(id) {
            ids.push(id.clone());
        }
    }
    ids.iter().filter_map(|id| cited.get(id).cloned()).collect()
}

