) -> AppResult<()> {
    live(conn, id)?;
    let lo = after.map(|a| neighbour_key(conn, a)).transpose()?;
    let hi = before.map(|b| neighbour_key(conn, b)).transpose()?;
    let key = key_between(lo.as_deref(), hi.as_deref()).map_err(AiError::Validation)?;
    store::set_key(conn, id, &key, now)
}

