fn set<T: ToSql>(
    conn: &Connection,
    table: &str,
    id: &str,
    column: &str,
    value: T,
) -> AppResult<()> {
    conn.execute(
        &format!("UPDATE {table} SET {column} = ?2 WHERE id = ?1"),
