crates/core/src/db/backup.rs::backup_for.docstring:
/// A backup taken before this device merges with another one (pairing, or the first session
/// with a device it never met). Kept apart from the others: the newest [`KEEP_BACKUPS`] of each
/// kind stay.

crates/core/src/db/backup.rs::rotate.source_code:
pub fn rotate(dir: &Path, keep: usize) -> AppResult<usize> {
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(e.into()),
    };
    let mut backups: Vec<PathBuf> = entries
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|ext| ext == "db"))
        .collect();
    // Timestamp prefixes sort chronologically, newest last.
    backups.sort();
    let (pairing, other): (Vec<PathBuf>, Vec<PathBuf>) = backups.into_iter().partition(|p| {
        p.file_name()
            .is_some_and(|n| n.to_string_lossy().contains(PAIRING_MARK))
    });
    let mut removed = 0;
    for kind in [pairing, other] {
        let excess = kind.len().saturating_sub(keep);
        for old in &kind[..excess] {
            std::fs::remove_file(old)?;
        }
        removed += excess;
    }
    Ok(removed)
}

crates/core/src/db/migrate.rs::Migration.source_code:
pub struct MigrationReport {
    /// Backup taken before upgrading existing data, if any.
    pub backup: Option<PathBuf>,
    /// `(module id, from version, to version)` for each Module that moved.
    pub applied: Vec<(String, usize, usize)>,
}

crates/core/src/db/migrate.rs::run.source_code:
pub fn run(
    conn: &mut Connection,
    modules: &[&dyn Module],
    backup_dir: &Path,
) -> AppResult<MigrationReport> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS _module_migrations(
             module TEXT PRIMARY KEY NOT NULL,
             version INTEGER NOT NULL
         ) STRICT",
    )?;
    let had_data: bool =
        conn.query_row("SELECT EXISTS(SELECT 1 FROM _module_migrations)", [], |r| {
            r.get(0)
        })?;

    let pending = plan(conn, modules)?;
    if pending.is_empty() {
        return Ok(MigrationReport::default());
    }

    let mut report = MigrationReport::default();
    if had_data {
        // Version numbers in the file name are sums across Modules: coarse, but enough to tell
        // backups apart and see how far each upgrade moved.
        let from = from_total(conn, modules)?;
        let to = from + pending.iter().map(|p| p.to - p.from).sum::<usize>();
        report.backup = Some(backup::create_backup(conn, backup_dir, from, to, now_ms())?);
    }

    for step in pending {
        let result = apply(conn, &step);
        // Always hand user_version back, even when the module failed.
        conn.pragma_update(None, "user_version", 0)?;
        result?;
        report
            .applied
            .push((step.id.to_owned(), step.from, step.to));
    }
    Ok(report)
}

