crates/core/src/events.rs::EventBus.subs.source_code:
pub fn subscribe<E: Any>(&self, handler: impl Fn(&E) + Send + Sync + 'static) {
    let erased: Handler = Arc::new(move |any: &dyn Any| {
        if let Some(event) = any.downcast_ref::<E>() {
            handler(event);
        }
    });
    self.handlers
        .write()
        .unwrap_or_else(PoisonError::into_inner)
        .entry(TypeId::of::<E>())
        .or_default()
        .push(erased);
}

crates/core/src/events.rs::EventBus.publ.source_code:
pub fn publish<E: Any>(&self, event: &E) {
    // Clone the handler list so a handler may subscribe without deadlocking.
    let handlers: Vec<Handler> = self
        .handlers
        .read()
        .unwrap_or_else(PoisonError::into_inner)
        .get(&TypeId::of::<E>())
        .cloned()
        .unwrap_or_default();
    for handler in handlers {
        handler(event);
    }
}

