pub fn init(log_dir: &Path, level: &str) -> AppResult<LogHandle> {
    let mut installed = INSTALLED.lock().unwrap_or_else(PoisonError::into_inner);
    if let Some(filter) = installed.as_ref() {
        let (_writer, guard) = tracing_appender::non_blocking(std::io::sink());
        return Ok(LogHandle {
            _guard: guard,
            filter: filter.clone(),
        });
    }
    std::fs::create_dir_all(log_dir)?;
    if let Err(e) = prune_old_logs(log_dir, SystemTime::now(), RETENTION) {
        // Pruning is housekeeping; never block startup on it. eprintln because the subscriber
        // is only installed further down in this function.
        eprintln!("log pruning failed: {e}");
    }

    let appender = tracing_appender::rolling::Builder::new()
        .rotation(tracing_appender::rolling::Rotation::DAILY)
        .filename_prefix(LOG_PREFIX)
        .filename_suffix("log")
        .build(log_dir)
        .map_err(|e| AppError::new(ErrorCode::Io, "Could not open log file").with_details(e))?;
    let (writer, guard) = tracing_appender::non_blocking(appender);

    let level = normalize_level(level).unwrap_or_else(|_| "info".to_owned());
    let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new(level));
    let (filter, filter_handle) = reload::Layer::new(env_filter);

    // Human-readable: timestamp, level, target (module path), message.
    let file_layer = fmt::layer()
        .with_writer(writer)
        .with_ansi(false)
        .with_target(true);
    // On Android, stderr is already forwarded to logcat (tag RustStdoutStderr); a second logcat
    // layer would duplicate every line, and ANSI colours show up as garbage there.
    let console_layer = fmt::layer()
        .with_writer(std::io::stderr)
        .with_ansi(!cfg!(target_os = "android"))
        .with_target(true);

    let subscriber = tracing_subscriber::registry()
        .with(filter)
        .with(file_layer)
        .with(console_layer);

    subscriber.try_init().map_err(|e| {
        AppError::new(ErrorCode::Internal, "Logging was already initialised").with_details(e)
    })?;
    *installed = Some(filter_handle.clone());
    Ok(LogHandle {
        _guard: guard,
        filter: filter_handle,
    })
}

crates/core/src/logging.rs::init.docstring:
/// Prunes old files, then installs the global subscriber. `RUST_LOG` overrides `level`
/// for developers.
///
/// Safe to call more than once per process (the Todo widget can start the process before Tauri
/// does): later calls install nothing and return a handle on the same filter, so `set_level`
/// still works. Only the first handle owns the file writer, so it must stay alive.

crates/core/src/logging.rs::prune_old_lo.source_code:
pub fn prune_old_logs(dir: &Path, now: SystemTime, max_age: Duration) -> AppResult<usize> {
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(e.into()),
    };
    let mut removed = 0;
    for entry in entries.filter_map(Result::ok) {
        if !entry.file_name().to_string_lossy().starts_with(LOG_PREFIX) {
            continue;
        }
        let Ok(modified) = entry.metadata().and_then(|m| m.modified()) else {
            continue;
        };
        // A clock set backwards yields Err; keep the file rather than guess.
        if now.duration_since(modified).is_ok_and(|age| age > max_age)
            && std::fs::remove_file(entry.path()).is_ok()
        {
            removed += 1;
        }
    }
    Ok(removed)
}

crates/core/src/module.rs::Module.source_code:
pub trait Module: Send + Sync {
    /// Stable id, also the Settings key prefix and the migration namespace.
    fn id(&self) -> &'static str;

    /// Whether the Module is on until the user switches it off (true, the default) or off until
    /// they opt in (Sync). A default-off Module is enabled when listed in the
    /// `core.enabled_optional_modules` Preference; Sync's own switch is a Device setting instead.
    fn default_enabled(&self) -> bool {
        true
    }

    /// This Module's own, independently versioned schema migrations.
    fn migrations(&self) -> Migrations<'static>;

    /// Declares this Module's Settings keys, defaults and validators.
    fn register_settings(&self, reg: &mut SettingsRegistry);

    /// The entities this Module keeps in step between devices, with the class of every field.
    /// None by default: a Module that declares none never syncs. See [`crate::syncable`].
    fn sync_entities(&self) -> &'static [SyncEntity] {
        &[]
    }

    /// Applies field values received from another device to one of this Module's entities,
    /// through its own repository and validation (ADR 0001): creating the entity when it is
    /// new here. Only the values that won the merge are passed. The result is not a new local
    /// change: nothing is recorded in the change log (Sync records the received change itself)
    /// and nothing new is stamped, but the Module's usual caches and indexes are kept in step.
    /// Returns the entity's full state afterwards. Never log the values.
    fn apply_remote(&self, _conn: &Connection, _change: &RemoteChange<'_>) -> AppResult<Applied> {
        Err(AppError::new(
            ErrorCode::Internal,
            "This Module does not take part in Sync",
        ))
    }

    /// Runs right after a remote change was applied and stored, in the same transaction, for
    /// work that must follow the stored record: a rule that decides something by comparing the
    /// change with the rest of the data and records the outcome as ordinary local changes
    /// (Todo's List name clash). Anything recorded here is stamped later than the record it
    /// follows, so it wins over it on every device. Idempotent: running it again after nothing
    /// changed records nothing.
    fn settle_remote(&self, _conn: &Connection, _change: &RemoteChange<'_>) -> AppResult<Settled> {
        Ok(Settled::default())
    }

    /// What this Module holds that a person would count (Entries, Tasks, List names): shown in
    /// the preview before two devices that both have data merge for the first time. Deleted
    /// things are not counted. Nothing by default.
    fn holdings(&self, _conn: &Connection) -> AppResult<Holdings> {
        Ok(Holdings::default())
    }

    /// Read-only Tools this Module offers the AI, so it can answer from the Module's data. None by
    /// default; the AI Module offers them only while this Module is on (ADR 0002 amendment).
    fn tools(&self) -> Vec<Box<dyn Tool>> {
        Vec::new()
    }

    /// Adds to the change log whatever this Module holds that the log does not (fully) describe:
    /// rows from before the log recorded every entity and field, from an older version or from
    /// an import. Sync sends the log, so it calls this before it first reads it; it must be
    /// deterministic and idempotent (see `changelog::backfill`, which does that per row), and it
    /// changes no row. `settings` is every Module's registered Preferences. Never log content.
    fn backfill_log(&self, _conn: &Connection, _settings: &SettingsRegistry) -> AppResult<()> {
        Ok(())
    }

    /// Work to do once per app start, after every Module's migrations ran (housekeeping, or upgrade steps keyed on what `report` says this run applied). No
    /// polling: nothing calls this again. Never log user content.
    fn on_startup(
        &self,
        _conn: &mut Connection,
        _device: &DeviceStore,
        _report: &MigrationReport,
    ) -> AppResult<()> {
        Ok(())
    }
}

