/// Like [`register`](Self::register), for a Device setting: read from and written to
/// `device.toml`. Only the `core` keys in [`LOOK_KEYS`](crate::device::LOOK_KEYS) have a home
/// there.

crates/core/src/settings/schema.rs::Sett.source_code:
fn insert(
    &mut self,
    module: &str,
    key: &str,
    default: Value,
    validator: Validator,
    device: bool,
) {
    let full = format!("{module}.{key}");
    if self.defs.contains_key(&full) {
        tracing::error!(key = %full, "duplicate settings key ignored");
        return;
    }
    self.defs.insert(
        full,
        SettingDef {
            module: module.to_owned(),
            key: key.to_owned(),
            default,
            validator,
            device,
        },
    );
}

pub fn get(&self, full_key: &str) -> Option<&SettingDef> {
    self.defs.get(full_key)
}

pub fn iter(&self) -> impl Iterator<Item = (&String, &SettingDef)> {
    self.defs.iter()
}

pub fn schema(&self) -> Vec<SettingSchema> {
    self.defs
        .iter()
        .map(|(full, d)| SettingSchema {
            key: full.clone(),
            module: d.module.clone(),
            default: d.default.clone(),
        })
        .collect()
}

crates/core/src/settings/schema.rs::vali.source_code:
pub fn boolean() -> Validator {
    Box::new(|v| {
        v.is_boolean()
            .then_some(())
            .ok_or_else(|| "expected a boolean".to_owned())
    })
}

pub fn one_of(allowed: &'static [&'static str]) -> Validator {
    Box::new(move |v| match v.as_str() {
        Some(s) if allowed.contains(&s) => Ok(()),
        _ => Err(format!("expected one of {allowed:?}")),
    })
}

pub fn text(max_len: usize) -> Validator {
    Box::new(move |v| match v.as_str() {
        Some(s) if s.chars().count() <= max_len => Ok(()),
        Some(_) => Err(format!("at most {max_len} characters")),
        None => Err("expected a string".to_owned()),
    })
}

pub fn string_list(max_items: usize) -> Validator {
    Box::new(move |v| {
        let items = v.as_array().ok_or_else(|| "expected an array".to_owned())?;
        if items.len() > max_items {
            return Err(format!("at most {max_items} entries"));
        }
        if items.iter().all(Value::is_string) {
            Ok(())
        } else {
            Err("entries must be strings".to_owned())
        }
    })
}

crates/core/src/settings/sync.rs::backfi.source_code:
pub(crate) fn backfill(conn: &Connection, registry: &SettingsRegistry) -> AppResult<()> {
    let mut stmt =
        conn.prepare("SELECT module, key, value, updated_at FROM settings ORDER BY module, key")?;
    let rows = stmt
        .query_map([], |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, i64>(3)?,
            ))
        })?
        .collect::<Result<Vec<_>, _>>()?;
    drop(stmt);
    let mut unlogged = Vec::new();
    for (module, key, raw, at) in rows {
        let id = format!("{module}.{key}");
        if registry.get(&id).is_some_and(|d| d.device) {
            continue;
        }
        // A value that no longer parses reads as the default; there is nothing to send.
        let Ok(value) = serde_json::from_str::<Value>(&raw) else {
            continue;
        };
        unlogged.push(Unlogged {
            change: Change {
                module: module.clone(),
                entity: ENTITY.to_owned(),
                entity_id: id,
                op: ChangeOp::Update,
                session_id: None,
                snapshot: json!({"module": module, "key": key, "value": value, "updated_at": at}),
            },
            ms: at,
            after: Vec::new(),
            needs_create: false,
        });
    }
    changelog::backfill(conn, &ENTITIES[0], unlogged)?;
    Ok(())
}

crates/core/src/settings/sync.rs::backfi.docstring:
/// Logs every shared Preference that is saved but not (as saved) in the change log: ones set
/// before Preferences were logged, or around the log. Stamped with the time the row says it was
/// written, so a later real write on any device still wins. Device settings stay home.

crates/core/src/settings/sync.rs::apply.source_code:
pub(crate) fn apply(conn: &Connection, change: &RemoteChange<'_>) -> AppResult<Applied> {
    let nothing = |snapshot: Value| Applied {
        snapshot,
        changed: false,
        events: Vec::new(),
    };
    let Some((module, key)) = change.entity_id.split_once('.') else {
        return Ok(nothing(Value::Object(change.fields.clone())));
    };
    let held = super::stored(conn, module, key)?;
    let current = |value: Option<&Value>| {
        json!({
            "module": module, "key": key, "value": value.cloned().unwrap_or(Value::Null),
            "updated_at": now_ms(),
        })
    };
    let Some(def) = change.settings.get(change.entity_id).filter(|d| !d.device) else {
        // A key this build does not know, or one that is per device: kept for relay only.
        return Ok(nothing(current(held.as_ref())));
    };
    let Some(value) = change
        .fields
        .get("value")
        .filter(|v| (def.validator)(v).is_ok())
    else {
        return Ok(nothing(current(held.as_ref())));
    };
    if held.as_ref() == Some(value) {
        return Ok(nothing(current(held.as_ref())));
    }
    let at = now_ms();
    conn.execute(
        "INSERT INTO settings(module, key, value, updated_at) VALUES (?1, ?2, ?3, ?4)
         ON CONFLICT(module, key) DO UPDATE
         SET value = excluded.value, updated_at = excluded.updated_at",
        rusqlite::params![module, key, value.to_string(), at],
    )?;
    Ok(Applied {
        snapshot: json!({"module": module, "key": key, "value": value, "updated_at": at}),
        changed: true,
        events: vec![SyncEvent::SettingChanged {
            module: module.to_owned(),
            key: key.to_owned(),
        }],
    })
}

