crates/core/src/syncable.rs::SyncEvent.source_code:
pub enum SyncEvent {
    /// A Task was put in the Inbox because the List it was moved to is gone on this device.
    TaskToInbox {
        /// The Task.
        task_id: String,
        /// The List it was meant for.
        list_id: String,
    },
    /// A Task that was showing here was deleted on another device. `device` is filled in by
    /// the engine (the record's origin), never by the Module.
    TaskDeleted {
        /// The Task.
        task_id: String,
        /// Its title.
        title: String,
        /// The device that deleted it.
        device: Option<String>,
    },
    /// A Journal Entry that was showing here was deleted on another device. `device` is filled in
    /// by the engine, like `TaskDeleted`'s.
    EntryDeleted {
        /// The Entry.
        entry_id: String,
        /// The Page it is on (what names it: an Entry has no title).
        page_date: String,
        /// The device that deleted it.
        device: Option<String>,
    },
    /// Two Lists with the same name became one: `from` was soft-deleted and its Tasks joined
    /// the end of `into`.
    ListsMerged {
        /// The List that went away.
        from_id: String,
        /// Its name.
        from_name: String,
        /// The device that made it.
        from_device: Option<String>,
        /// The List that survives.
        into_id: String,
        /// Its name.
        into_name: String,
        /// The device that made it.
        into_device: Option<String>,
    },
    /// Two devices rewrote the same words of a text: a Conflict now waits in the Sync Module
    /// (raised by the engine itself when it merges text, never by a Module). The newest version
    /// is what shows.
    ConflictRaised {
        /// The Conflict's id.
        id: String,
        /// The kind of record it is about (its change-log entity).
        entity: String,
        /// Its id.
        entity_id: String,
        /// The text field.
        field: String,
    },
    /// A text clash on a record that is deleted was resolved without asking: nothing needs the
    /// person. The hook for Resolved automatically.
    ConflictAutoResolved {
        /// The Conflict's id.
        id: String,
        /// The kind of record it is about.
        entity: String,
        /// Its id.
        entity_id: String,
        /// The text field.
        field: String,
    },
    /// A Preference took another device's value.
    SettingChanged {
        /// Owning Module id.
        module: String,
        /// Key within the Module.
        key: String,
    },
    /// Another device renamed THIS device (Sync's `sync_device` record): the app changes the name
    /// in its device file.
    DeviceRenamed {
