crates/core/src/tool.rs::fit_rows.source_code:
pub fn fit_rows(rows: Vec<Value>) -> (Vec<Value>, bool) {
    let budget = RESULT_CAP - ENVELOPE_ALLOWANCE;
    let mut used = 2;
    let mut kept = Vec::new();
    for row in rows {
        let size = row.to_string().len() + 1;
        if used + size > budget {
            return (kept, true);
        }
        used += size;
        kept.push(row);
    }
    (kept, false)
}

crates/core/src/tool.rs::cut.source_code:
pub fn cut(text: &str, max_bytes: usize) -> &str {
    if text.len() <= max_bytes {
        return text;
    }
    let mut end = max_bytes;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    &text[..end]
}

