    let entries: u32 = conn.query_row(
        "SELECT COUNT(*) FROM journal_entries WHERE deleted_at IS NULL",
        [],
        |r| r.get(0),
    )?;
    Ok(Holdings {
        entries,
        ..Holdings::default()
    })
}

