fn edited_by(written_at: i64, at: i64, current: Option<i64>, op: ChangeOp) -> Option<i64> {
    if op == ChangeOp::Tick || at - written_at <= EDIT_GRACE_MS {
        return current;
    }
    Some(at)
}

