pub enum AddressError {
    /// Not a web address with a scheme and a host.
    Invalid,
    /// Only `http` and `https` are spoken.
    UnsupportedScheme,
    /// `http` to a host that is not this machine, the local network or Tailscale.
    PlainHttpNotAllowed,
}

crates/providers/src/address.rs::check.source_code:
pub fn check(raw: &str) -> Result<String, AddressError> {
    let trimmed = raw.trim().trim_end_matches('/');
    let uri: Uri = trimmed.parse().map_err(|_| AddressError::Invalid)?;
    let host = uri.host().ok_or(AddressError::Invalid)?;
    if uri.query().is_some() {
        return Err(AddressError::Invalid);
    }
    match uri.scheme_str() {
        Some("https") => Ok(trimmed.to_owned()),
        Some("http") if is_local(host) => Ok(trimmed.to_owned()),
        Some("http") => Err(AddressError::PlainHttpNotAllowed),
        Some(_) => Err(AddressError::UnsupportedScheme),
        None => Err(AddressError::Invalid),
    }
}

crates/providers/src/address.rs::is_loca.source_code:
fn is_local(host: &str) -> bool {
    let bare = host.trim_start_matches('[').trim_end_matches(']');
    if let Ok(ip) = bare.parse::<IpAddr>() {
        return match ip {
            IpAddr::V4(v4) => {
                let [a, b, ..] = v4.octets();
                v4.is_loopback()
                    || v4.is_private()
                    || v4.is_link_local()
                    // Tailscale's 100.64.0.0/10.
                    || (a == 100 && (b & 0xc0) == 64)
            }
            IpAddr::V6(v6) => {
                let first = v6.segments()[0];
                v6.is_loopback()
                    // Unique local (fc00::/7, which includes Tailscale's fd7a:115c:a1e0::/48).
                    || (first & 0xfe00) == 0xfc00
                    // Link-local (fe80::/10).
                    || (first & 0xffc0) == 0xfe80
            }
        };
    }
    let lower = bare.to_ascii_lowercase();
    let labels: Vec<&str> = lower.split('.').collect();
    lower == "localhost" || labels.last() == Some(&"local") || labels.ends_with(&["ts", "net"])
}

crates/providers/src/anthropic.rs::Anthr.source_code:
pub fn new(name: &str, model: &str, address: &str, key: &str) -> Self {
    Self::with_client(Client::new(), name, model, address, key)
}

pub fn with_client(client: Client, name: &str, model: &str, address: &str, key: &str) -> Self {
    Self {
        name: name.to_owned(),
        model: model.to_owned(),
        address: address.trim_end_matches('/').to_owned(),
        key: key.to_owned(),
        client,
    }
}

fn headers(&self) -> Vec<(&'static str, String)> {
    vec![
        ("x-api-key", self.key.clone()),
        ("anthropic-version", API_VERSION.to_owned()),
    ]
}

pub fn list_models(&self) -> Result<Vec<String>, Failure> {
    let response = self.client.get_with(
        &format!("{}/models?limit=1000", self.address),
        &self.headers(),
    )?;
    let status = response.status().as_u16();
    let body = read_body(response)?;
    if !(200..300).contains(&status) {
        return Err(openai::status_failure(status, &body, Endpoint::Models));
    }
    openai::parse_model_ids(&body)
}

pub fn body(&self, request: &Request) -> Value {
    let mut body = json!({
        "model": request.model,
        "max_tokens": MAX_OUTPUT_TOKENS,
        "messages": turns(&request.messages),
    });
    if !request.system.is_empty() {
        body["system"] = json!(request.system);
    }
    if !request.tools.is_empty() {
        body["tools"] = request
            .tools
            .iter()
            .map(|tool| {
                let schema: Value = serde_json::from_str(&tool.schema)
                    .unwrap_or_else(|_| json!({"type": "object"}));
                json!({ "name": tool.name, "description": tool.about, "input_schema": schema })
            })
            .collect();
    }
    body
}

fn step(&self, request: &Request, emit: &mut dyn FnMut(StreamEvent)) -> Result<(), Failure> {
    let response = self.client.post_with(
        &format!("{}/messages", self.address),
        &self.body(request),
        &self.headers(),
    )?;
    let status = response.status().as_u16();
    let text = read_body(response)?;
    if !(200..300).contains(&status) {
        return Err(openai::status_failure(status, &text, Endpoint::Chat));
    }
    let (answer, calls, stop) = parse_reply(&text)?;
    if !answer.is_empty() {
        emit(StreamEvent::TextDelta(answer));
    }
    for call in calls {
        emit(StreamEvent::Call(call));
    }
    emit(StreamEvent::Done(stop));
    Ok(())
}

crates/providers/src/anthropic.rs::turns.source_code:
pub fn turns(messages: &[Message]) -> Vec<Value> {
    let mut turns: Vec<(&str, Vec<Value>)> = Vec::new();
    for message in messages {
        let (role, blocks) = match message {
            Message::User(text) | Message::Correction(text) => {
                ("user", vec![json!({ "type": "text", "text": text })])
            }
            Message::Assistant { text, calls } => {
                let mut blocks = Vec::new();
                if !text.is_empty() {
                    blocks.push(json!({ "type": "text", "text": text }));
                }
                for call in calls {
                    blocks.push(json!({
                        "type": "tool_use",
                        "id": call.id,
                        "name": call.name,
                        "input": serde_json::from_str::<Value>(&call.arguments)
                            .unwrap_or_else(|_| json!({})),
                    }));
                }
                ("assistant", blocks)
            }
            Message::Tool {
                call_id,
                text,
                is_error,
                ..
            } => (
                "user",
                vec![json!({
                    "type": "tool_result",
                    "tool_use_id": call_id,
                    "content": text,
                    "is_error": is_error,
                })],
            ),
        };
        match turns.last_mut() {
            Some((last, joined)) if *last == role => joined.extend(blocks),
            _ => turns.push((role, blocks)),
        }
    }
    turns
        .into_iter()
        .map(|(role, content)| json!({ "role": role, "content": content }))
        .collect()
}

crates/providers/src/anthropic.rs::parse.source_code:
pub fn parse_reply(body: &str) -> Result<(String, Vec<Call>, StopReason), Failure> {
    let value: Value = serde_json::from_str(body).map_err(|_| Failure::BadResponse)?;
    let stop = match value.get("stop_reason").and_then(Value::as_str) {
        Some("end_turn" | "tool_use" | "stop_sequence") => StopReason::Stop,
        Some("max_tokens") => StopReason::Length,
        _ => return Err(Failure::BadResponse),
    };
    let blocks = value
        .get("content")
        .and_then(Value::as_array)
        .ok_or(Failure::BadResponse)?;
    let mut text = String::new();
    let mut calls = Vec::new();
    for block in blocks {
        match block.get("type").and_then(Value::as_str) {
            Some("text") => text.push_str(
                block
                    .get("text")
                    .and_then(Value::as_str)
                    .ok_or(Failure::BadResponse)?,
            ),
            Some("tool_use") => {
                let id = block
                    .get("id")
                    .and_then(Value::as_str)
                    .ok_or(Failure::BadResponse)?;
                let name = block
                    .get("name")
                    .and_then(Value::as_str)
                    .filter(|name| !name.is_empty())
                    .ok_or(Failure::BadResponse)?;
                let input = block.get("input").ok_or(Failure::BadResponse)?;
                calls.push(Call {
                    id: id.to_owned(),
                    name: name.to_owned(),
                    arguments: input.to_string(),
                    thought_signature: None,
                });
            }
            // Thinking and other blocks carry nothing Mnemora shows.
            _ => {}
        }
    }
    Ok((text, calls, stop))
}

