pub fn response_format(finish_only: bool) -> Value {
    let actions: Vec<&str> = if finish_only {
        vec!["finish"]
    } else {
        vec!["tools", "finish"]
    };
    json!({
        "type": "json_schema",
        "json_schema": {
            "name": "mnemora_step",
            "strict": true,
            "schema": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "action": { "type": "string", "enum": actions },
                    "calls": {
                        "type": "array",
                        "maxItems": if finish_only { 0 } else { MAX_CALLS },
                        "items": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                                "name": { "type": "string" },
                                "arguments": { "type": "string" }
                            },
                            "required": ["name", "arguments"]
                        }
                    },
                    "answer": { "type": "string" },
                    "sources": {
                        "type": "array",
                        "maxItems": MAX_SOURCES,
                        "items": { "type": "string" }
                    }
                },
                "required": ["action", "calls", "answer", "sources"]
            }
        }
    })
}

crates/providers/src/envelope.rs::instru.source_code:
pub fn instructions(tools: &[ToolDef]) -> String {
    if tools.is_empty() {
        return "This is your last reply. Reply with one JSON object: action \"finish\", calls \
            empty, the answer in answer, and in sources the ids of the Entries and Tasks the \
            answer rests on. Write nothing outside the JSON object."
            .to_owned();
    }
    let mut text = String::from(
        "Reply with one JSON object only, with the keys action, calls, answer and sources. To \
         look something up, use action \"tools\" with up to 8 calls; each call has the name of a \
         Tool below and arguments, a JSON object written as text. Leave answer and sources empty \
         then. To finish, use action \"finish\" with calls empty, the answer in answer, and in \
         sources the ids of the Entries and Tasks the answer rests on. Tools:",
    );
    for tool in tools {
        let _ = write!(
            text,
            "\n- {}: {} Arguments: {}",
            tool.name, tool.about, tool.schema
        );
    }
    text
}

crates/providers/src/envelope.rs::turns.source_code:
pub fn turns(messages: &[Message]) -> Vec<Value> {
    messages
        .iter()
        .map(|message| match message {
            Message::User(text) | Message::Correction(text) => {
                json!({ "role": "user", "content": text })
            }
            Message::Assistant { text, calls } if calls.is_empty() => {
                json!({ "role": "assistant", "content": text })
            }
            Message::Assistant { calls, .. } => {
                let calls: Vec<Value> = calls
                    .iter()
                    .map(|call| json!({ "name": call.name, "arguments": call.arguments }))
                    .collect();
                let envelope = json!({
                    "action": "tools",
                    "calls": calls,
                    "answer": "",
                    "sources": [],
                });
                json!({ "role": "assistant", "content": envelope.to_string() })
            }
            Message::Tool {
                name,
                text,
                is_error,
                ..
            } => {
                let note = if *is_error { " (refused)" } else { "" };
                json!({
                    "role": "user",
                    "content": format!("Result of {name}{note}:\n{text}"),
                })
            }
        })
        .collect()
}

crates/providers/src/envelope.rs::parse.source_code:
pub fn parse(content: &str, tools_offered: bool, mut next_id: impl FnMut() -> String) -> Parsed {
    let text = strip(content);
    let Ok(Value::Object(object)) = serde_json::from_str::<Value>(text) else {
        return Parsed::Correction(SHAPE);
    };
    let Some(fields) = fields(&object) else {
        return Parsed::Correction(SHAPE);
    };
    match fields.action {
        "tools" => {
            if !tools_offered {
                return Parsed::Correction(NO_TOOLS);
            }
            if !fields.answer.is_empty() || !fields.sources.is_empty() {
                return Parsed::Correction(TOOLS_WITH_ANSWER);
            }
            if fields.calls.is_empty() {
                return Parsed::Correction(NO_CALLS);
            }
            if fields.calls.len() > MAX_CALLS {
                return Parsed::Correction(TOO_MANY_CALLS);
            }
            let mut calls = Vec::with_capacity(fields.calls.len());
            for call in &fields.calls {
                match call_of(call, &mut next_id) {
                    Some(call) => calls.push(call),
                    None => return Parsed::Correction(BAD_ARGUMENTS),
                }
            }
            Parsed::Calls(calls)
        }
        "finish" => {
            if !fields.calls.is_empty() {
                return Parsed::Correction(FINISH_WITH_CALLS);
            }
            if fields.answer.trim().is_empty() {
                return Parsed::Correction(EMPTY_ANSWER);
            }
            if fields.sources.len() > MAX_SOURCES {
                return Parsed::Correction(TOO_MANY_SOURCES);
            }
            Parsed::Answer {
                text: fields.answer.to_owned(),
                sources: fields.sources,
            }
        }
        _ => Parsed::Correction(SHAPE),
    }
}

crates/providers/src/envelope.rs::Fields.source_code:
struct Fields<'a> {
    action: &'a str,
    calls: Vec<&'a Map<String, Value>>,
    answer: &'a str,
    sources: Vec<String>,
}

crates/providers/src/envelope.rs::fields.source_code:
fn fields(object: &Map<String, Value>) -> Option<Fields<'_>> {
    if object.len() != 4 {
        return None;
    }
    let action = object.get("action")?.as_str()?;
    let calls = object
        .get("calls")?
        .as_array()?
        .iter()
        .map(|call| {
            let call = call.as_object()?;
            if call.len() != 2
                || !call.get("name")?.is_string()
                || !call.get("arguments")?.is_string()
            {
                return None;
            }
            Some(call)
        })
        .collect::<Option<Vec<_>>>()?;
    let answer = object.get("answer")?.as_str()?;
    let sources = object
        .get("sources")?
        .as_array()?
        .iter()
        .map(|id| id.as_str().map(str::to_owned))
        .collect::<Option<Vec<_>>>()?;
    Some(Fields {
        action,
        calls,
        answer,
        sources,
    })
}

crates/providers/src/envelope.rs::call_o.source_code:
fn call_of(call: &Map<String, Value>, next_id: &mut impl FnMut() -> String) -> Option<Call> {
    let name = call.get("name")?.as_str()?.to_owned();
    let arguments = call.get("arguments")?.as_str()?;
    if arguments.len() > MAX_ARGUMENT_BYTES {
        return None;
    }
    let parsed: Value = serde_json::from_str(arguments).ok()?;
    if !parsed.is_object() {
        return None;
    }
    Some(Call {
        id: next_id(),
        name,
        arguments: arguments.to_owned(),
        thought_signature: None,
    })
}

crates/providers/src/envelope.rs::strip.source_code:
fn strip(content: &str) -> &str {
    let text = content.trim_start_matches('\u{feff}').trim();
    text.strip_prefix("```json")
        .or_else(|| text.strip_prefix("```"))
        .map(str::trim_start)
        .and_then(|rest| rest.strip_suffix("```"))
        .map_or(text, str::trim)
}

crates/providers/src/openai.rs::SseEvent.source_code:
pub enum SseEvent {
    /// A piece of the answer's text.
    Text(String),
    /// A piece of one Tool call: its index in the reply and whatever fields this chunk carries.
    ToolDelta {
        /// Which call in the reply this piece belongs to; `None` when the chunk names none
        /// (Gemini's parallel calls), so the caller decides by id.
        index: Option<usize>,
        /// The call's id, when this chunk carries it.
        id: Option<String>,
        /// The Tool's name, when this chunk carries it.
        name: Option<String>,
        /// A piece of the arguments' JSON text.
        arguments: Option<String>,
        /// Gemini's reasoning token for the call, when this chunk carries it.
        thought_signature: Option<String>,
    },
    /// The reply is finished and why.
    Finish(StopReason),
    /// The stream is over (`data: [DONE]`).
    Done,
}

crates/providers/src/openai.rs::chat_bod.source_code:
pub fn chat_body(request: &Request, stream: bool) -> Value {
    let mut messages = Vec::with_capacity(request.messages.len() + 1);
    if !request.system.is_empty() {
        messages.push(json!({ "role": "system", "content": request.system }));
    }
    for message in &request.messages {
        messages.push(match message {
            Message::User(text) | Message::Correction(text) => {
                json!({ "role": "user", "content": text })
            }
            Message::Assistant { text, calls } if calls.is_empty() => {
                json!({ "role": "assistant", "content": text })
            }
            Message::Assistant { text, calls } => {
                let calls: Vec<Value> = calls
                    .iter()
                    .map(|call| {
                        let mut wire = json!({
                            "id": call.id,
                            "type": "function",
                            "function": { "name": call.name, "arguments": call.arguments },
                        });
                        // Gemini rejects a later Step that drops its signature: send it back as it came.
                        if let Some(signature) = &call.thought_signature {
                            wire["extra_content"] =
                                json!({ "google": { "thought_signature": signature } });
                        }
                        wire
                    })
                    .collect();
                json!({
                    "role": "assistant",
                    "content": if text.is_empty() { Value::Null } else { json!(text) },
                    "tool_calls": calls,
                })
            }
            Message::Tool { call_id, text, .. } => {
                json!({ "role": "tool", "tool_call_id": call_id, "content": text })
            }
        });
    }
    let mut body = json!({
        "model": request.model,
        "messages": messages,
        "stream": stream,
    });
    if !request.tools.is_empty() {
        body["tools"] = request.tools.iter().map(function_tool).collect();
    }
    body
}

crates/providers/src/openai.rs::function.source_code:
fn function_tool(tool: &ToolDef) -> Value {
    let parameters: Value = serde_json::from_str(&tool.schema).unwrap_or_else(|_| json!({}));
    json!({
        "type": "function",
        "function": {
            "name": tool.name,
            "description": tool.about,
            "parameters": parameters,
        },
    })
}

crates/providers/src/openai.rs::parse_an.source_code:
pub fn parse_answer(body: &str) -> Result<(String, StopReason), Failure> {
    let value: Value = serde_json::from_str(body).map_err(|_| Failure::BadResponse)?;
    let choice = value
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .ok_or(Failure::BadResponse)?;
    let text = choice
        .pointer("/message/content")
        .and_then(Value::as_str)
        .filter(|text| !text.is_empty())
        .ok_or(Failure::BadResponse)?;
    let finish = choice.get("finish_reason").and_then(Value::as_str);
    // A whole answer the envelope reads must not be a reply that made native Tool calls.
    if matches!(finish, Some("tool_calls" | "function_call")) {
        return Err(Failure::BadResponse);
    }
    let stop = stop_reason(finish)?.ok_or(Failure::BadResponse)?;
    Ok((text.to_owned(), stop))
}

crates/providers/src/openai.rs::sse_even.source_code:
pub fn sse_events(line: &str) -> Result<Vec<SseEvent>, Failure> {
    let Some(data) = line.strip_prefix("data:") else {
        return Ok(Vec::new());
    };
    let data = data.trim();
    if data == "[DONE]" {
        return Ok(vec![SseEvent::Done]);
    }
    let value: Value = serde_json::from_str(data).map_err(|_| Failure::BadResponse)?;
    if value.get("error").is_some() {
        return Err(Failure::Unexpected);
    }
    let Some(choice) = value
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
    else {
        // The usage chunk has no choices.
        return Ok(Vec::new());
    };
    let mut events = Vec::new();
    if let Some(text) = choice
        .pointer("/delta/content")
        .and_then(Value::as_str)
        .filter(|text| !text.is_empty())
    {
        events.push(SseEvent::Text(text.to_owned()));
    }
    for piece in choice
        .pointer("/delta/tool_calls")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        events.push(SseEvent::ToolDelta {
            index: piece
                .get("index")
                .and_then(Value::as_u64)
                .and_then(|index| usize::try_from(index).ok()),
            id: piece.get("id").and_then(Value::as_str).map(str::to_owned),
            name: piece
                .pointer("/function/name")
                .and_then(Value::as_str)
                .map(str::to_owned),
            arguments: piece
                .pointer("/function/arguments")
                .and_then(Value::as_str)
                .map(str::to_owned),
            thought_signature: piece
                .pointer("/extra_content/google/thought_signature")
                .and_then(Value::as_str)
                .map(str::to_owned),
        });
    }
    if let Some(stop) = stop_reason(choice.get("finish_reason").and_then(Value::as_str))? {
        events.push(SseEvent::Finish(stop));
    }
    Ok(events)
}

