    local: Local<'_>,
    peer: &str,
    n_in: i64,
    n_out: i64,
    parts: Vec<Part>,
) -> Result<bool, SyncError> {
    if !leads(local.device, peer) || n_in + n_out == 0 {
        return Ok(false);
    }
    let mut row = with_peer(
        conn,
        blank(conn, new_id(), Kind::Session, local),
        peer,
        None,
    );
    row.n_in = n_in;
    row.n_out = n_out;
    row.detail = parts;
    log(conn, &row)
}

