pub(crate) fn log_conflict_raised(
    conn: &Connection,
    conflict: &str,
    entity: &str,
    field: &str,
    raised_at: i64,
    other_device: &str,
) -> Result<bool, SyncError> {
    let me = hlc::device_id(conn)?;
    let mut row = blank(
        conn,
        named_id(&["conflict_raised", conflict]),
        Kind::ConflictRaised,
        Local {
            device: &me,
            name: "",
        },
    );
    row.at = raised_at;
    if other_device != me {
        row = with_peer(conn, row, other_device, None);
    }
    row.extra = json!({ "entity": entity, "field": field, "conflict": conflict });
    log(conn, &row)
}

pub(crate) fn log_conflict_resolved(
    conn: &Connection,
    conflict: &str,
    entity: &str,
    field: &str,
    by: &str,
    at: i64,
) -> Result<bool, SyncError> {
    let mut row = blank(
        conn,
        named_id(&["conflict_resolved", conflict]),
        Kind::ConflictResolved,
        Local {
            device: by,
            name: "",
        },
    );
    row.at = at;
    row.extra = json!({ "entity": entity, "field": field });
    log(conn, &row)
}

pub(crate) fn log_conflict_deleted(
