    conflict: &str,
    entity: &str,
    field: &str,
) -> Result<bool, SyncError> {
    let me = hlc::device_id(conn)?;
    let mut row = blank(
        conn,
        named_id(&["conflict_resolved", conflict]),
        Kind::ConflictResolved,
        Local {
            device: &me,
            name: "",
        },
    );
    row.extra = json!({ "entity": entity, "field": field, "auto": true });
    log(conn, &row)
}

