pub(crate) fn note_events(conn: &Connection, events: &[SyncEvent]) -> Result<(), SyncError> {
    for event in events {
        if let SyncEvent::ListsMerged {
            from_id,
            from_name,
            from_device,
            into_id,
            into_name,
            into_device,
        } = event
        {
            let other = [into_device, from_device]
                .into_iter()
                .flatten()
                .map(String::as_str)
                .next();
            log_lists_merged(conn, (from_id, from_name), (into_id, into_name), other)?;
        }
    }
    Ok(())
}

