fn port_of(text: &str) -> Result<u16, AddressError> {
    match text.parse::<u16>() {
        Ok(port) if port > 0 && text.bytes().all(|b| b.is_ascii_digit()) => Ok(port),
        _ => Err(AddressError::Port),
    }
}

crates/sync/src/address.rs::name_of.source_code:
fn name_of(text: &str) -> Result<String, AddressError> {
    let name = text.strip_suffix('.').unwrap_or(text).to_ascii_lowercase();
    let label_ok = |l: &str| {
        !l.is_empty()
            && l.len() <= MAX_LABEL
            && !l.starts_with('-')
            && !l.ends_with('-')
            && l.bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
    };
    let numeric = name.bytes().all(|b| b.is_ascii_digit() || b == b'.');
    if name.is_empty() || name.len() > MAX_HOST || numeric || !name.split('.').all(label_ok) {
        return Err(AddressError::Host);
    }
    Ok(name)
}

crates/sync/src/addresses.rs::shareable.source_code:
pub fn shareable(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => v4.is_private() || is_tailscale_v4(v4),
        IpAddr::V6(v6) => is_tailscale_v6(v6),
    }
}

crates/sync/src/addresses.rs::is_tailsca.source_code:
fn is_tailscale_v4(ip: Ipv4Addr) -> bool {
    let [a, b, ..] = ip.octets();
    a == 100 && (64..=127).contains(&b)
}

fn is_tailscale_v6(ip: Ipv6Addr) -> bool {
    let s = ip.segments();
    s[0] == 0xfd7a && s[1] == 0x115c && s[2] == 0xa1e0
}

crates/sync/src/addresses.rs::identifies.source_code:
pub fn identifies(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => {
            !(v4.is_private()
                || v4.is_loopback()
                || v4.is_link_local()
                || v4.is_unspecified()
                || is_tailscale_v4(v4))
        }
        IpAddr::V6(v6) => v6.segments()[0] & 0xe000 == 0x2000,
    }
}

crates/sync/src/addresses.rs::is_tailsca.source_code:
pub fn is_tailscale(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => is_tailscale_v4(v4),
        IpAddr::V6(v6) => is_tailscale_v6(v6),
    }
}

crates/sync/src/addresses.rs::local.source_code:
pub fn local() -> Vec<IpAddr> {
    let mut found: Vec<IpAddr> = if_addrs::get_if_addrs()
        .map(|all| {
            all.into_iter()
                .map(|i| i.ip())
                .filter(|ip| shareable(*ip))
                .collect()
        })
        .unwrap_or_default();
    found.sort_by_key(|ip| (is_tailscale(*ip), ip.is_ipv6(), *ip));
    found.dedup();
    found
}

