crates/sync/src/check.rs::check_within.source_code:
async fn check_within(
    limits: Limits,
    config: &NetConfig,
    expect: &Expect<'_>,
    text: &str,
    name_of: impl Fn(&str) -> Option<String>,
) -> (CheckResult, Option<SocketAddr>) {
    let address = match Address::parse(text) {
        Ok(a) => a,
        Err(e) => return (CheckResult::failed(CheckKind::Invalid, e.message()), None),
    };
    let addrs = match address.resolve(limits.lookup).await {
        Ok(a) => a,
        Err(ResolveError::NotFound) => {
            return (
                CheckResult::failed(
                    CheckKind::NotFound,
                    "Could not find that name. Check the spelling and that Tailscale is connected.",
                ),
                None,
            );
        }
        Err(ResolveError::TimedOut) => {
            return (
                CheckResult::failed(CheckKind::TimedOut, "Looking up that name took too long."),
                None,
            );
        }
    };
    let started = Instant::now();
    let mut last = None;
    for addr in addrs {
        let left = limits.total.saturating_sub(started.elapsed());
        if left.is_zero() {
            last = Some(NetError::Timeout);
            break;
        }
        match tokio::time::timeout(limits.each.min(left), probe(config, addr)).await {
            Ok(Ok(found)) => {
                let ms = u32::try_from(started.elapsed().as_millis()).unwrap_or(u32::MAX);
                return (verdict(&found, expect, ms, &name_of), Some(addr));
            }
            Ok(Err(e)) => last = Some(e),
            Err(_) => last = Some(NetError::Timeout),
        }
    }
    let result = last.map_or_else(
        || CheckResult::failed(CheckKind::Unreachable, "Nothing answered there."),
        |e| failure(&e, expect),
    );
    (result, None)
}

crates/sync/src/check.rs::verdict.source_code:
fn verdict(
    found: &Probed,
    expect: &Expect<'_>,
    ms: u32,
    name_of: &impl Fn(&str) -> Option<String>,
) -> CheckResult {
    if found.handshake.device != expect.device {
        let who = name_of(&found.handshake.device);
        let message = match who {
            Some(who) => format!("That is {who}, not {}.", expect.name),
            None => format!("That is another device, not {}.", expect.name),
        };
        return CheckResult::failed(CheckKind::WrongDevice, message);
    }
    CheckResult {
        reached: true,
        kind: CheckKind::Reached,
        message: format!("Reached {} in {ms} ms", expect.name),
        ms: Some(ms),
    }
}

crates/sync/src/clocks.rs::fold.source_code:
pub fn fold(conn: &Connection, entity: &SyncEntity, me: &str) -> Result<(), SyncError> {
    let mark: i64 = conn
        .query_row(
            "SELECT seq FROM sync_clock_marks WHERE entity = ?1",
            [entity.name],
            |r| r.get(0),
        )
        .optional()?
        .unwrap_or(0);
    let mut stmt = conn.prepare(
        "SELECT entity_id, fields, snapshot, origin_device, hlc_ms, hlc_counter, seq
         FROM change_log WHERE entity = ?1 AND seq > ?2 ORDER BY seq",
    )?;
    let mut rows = stmt.query(params![entity.name, mark])?;
    let mut newest = mark;
    while let Some(row) = rows.next()? {
        let entity_id: String = row.get(0)?;
        let fields: Option<String> = row.get(1)?;
        let snapshot: String = row.get(2)?;
        let origin: String = row.get(3)?;
        let stamp = Stamp {
            ms: row.get(4)?,
            counter: row.get(5)?,
            device: origin.clone(),
        };
        newest = newest.max(row.get(6)?);
        let fields = fields
            .and_then(|f| serde_json::from_str::<Value>(&f).ok())
            .and_then(|v| match v {
                Value::Object(map) => Some(map),
                _ => None,
            });
        let snapshot: Value = serde_json::from_str(&snapshot).unwrap_or(Value::Null);
        let wire: Map<String, Value> = wire_fields(entity, fields, &snapshot, origin == me);
        for field in wire.keys() {
            raise(conn, entity.name, &entity_id, field, &stamp)?;
        }
    }
    if newest > mark {
        conn.execute(
            "INSERT INTO sync_clock_marks(entity, seq) VALUES (?1, ?2)
             ON CONFLICT(entity) DO UPDATE SET seq = excluded.seq",
            params![entity.name, newest],
        )?;
    }
    Ok(())
}

