crates/sync/src/conflict_view.rs::showin.docstring:
/// The text of the field a Conflict is about as the record holds it now. Edit merged is built
/// from it, not from the text the Conflict was raised with: the clashes are those of the other
/// version against what shows now (the older version is "ours", the showing text "theirs"), so
/// an edit made since stays, as agreed text or inside the showing side of a clash.

crates/sync/src/conflict_view.rs::view.source_code:
pub fn view(
    conn: &Connection,
    id: &str,
    me: &str,
    my_name: &str,
) -> AppResult<Option<ConflictView>> {
    conflicts::settle_all_deleted(conn)?;
    let Some(c) = conflicts::get(conn, id)? else {
        return Ok(None);
    };
    let showing = showing_now(conn, &c)?;
    let (showing_spans, other_spans) = textmerge::diff(&showing, &c.b_text);
    let pieces = textmerge::merge(&c.base, &c.b_text, &showing)
        .pieces
        .into_iter()
        .map(|p| match p {
            Piece::Agreed(text) => ClashPiece::Agreed { text },
            Piece::Clash(k) => ClashPiece::Clash {
                showing: k.theirs,
                other: k.ours,
                original: k.base,
            },
        })
        .collect();
    Ok(Some(ConflictView {
        row: row(conn, &c, me, my_name)?,
        open: c.open,
        resolution: c.resolution.clone(),
        showing: showing_spans,
        other: other_spans,
        original: c.base.clone(),
        pieces,
    }))
}

crates/sync/src/conflict_view.rs::draft.source_code:
pub fn draft(conn: &Connection, id: &str, choices: &[ClashChoice]) -> AppResult<String> {
    let Some(c) = conflicts::get(conn, id)? else {
        return Err(SyncError::Validation("That conflict is gone").into());
    };
    let showing = showing_now(conn, &c)?;
    let mut choices = choices.iter();
    let mut out = String::new();
    for piece in textmerge::merge(&c.base, &c.b_text, &showing).pieces {
        match piece {
            Piece::Agreed(text) => out.push_str(&text),
            Piece::Clash(k) => match choices.next().unwrap_or(&ClashChoice::Showing) {
                ClashChoice::Showing => out.push_str(&k.theirs),
                ClashChoice::Other => out.push_str(&k.ours),
                ClashChoice::Both => {
                    out.push_str(&k.theirs);
                    if !(k.theirs.is_empty()
                        || k.ours.is_empty()
                        || k.theirs.ends_with(char::is_whitespace)
                        || k.ours.starts_with(char::is_whitespace))
                    {
                        out.push(if k.theirs.contains('\n') || k.ours.contains('\n') {
                            '\n'
                        } else {
                            ' '
                        });
                    }
                    out.push_str(&k.ours);
                }
            },
        }
    }
    Ok(out)
}

