crates/sync/src/conflicts.rs::conflict_i.source_code:
pub fn conflict_id(
    entity: &str,
    entity_id: &str,
    field: &str,
    base: &str,
    a: &str,
    b: &str,
) -> String {
    let hash = |t: &str| {
        ring::digest::digest(&ring::digest::SHA256, t.as_bytes())
            .as_ref()
            .iter()
            .fold(String::new(), |mut acc, b| {
                use std::fmt::Write;
                let _ = write!(acc, "{b:02x}");
                acc
            })
    };
    let mut versions = [hash(a), hash(b)];
    versions.sort();
    let name = format!(
        "{entity}\0{entity_id}\0{field}\0{}\0{}\0{}",
        hash(base),
        versions[0],
        versions[1]
    );
    Uuid::new_v5(&NAMESPACE, name.as_bytes()).to_string()
}

