pub fn set_typed_address(
    conn: &Connection,
    device: &str,
    text: &str,
) -> Result<Option<String>, SyncError> {
    let stored = if text.trim().is_empty() {
        None
    } else {
        Some(
            Address::parse(text)
                .map_err(|e| SyncError::Validation(e.message()))?
                .normalized(),
        )
    };
    crate::rename::set_address(conn, device, stored.as_deref())?;
    Ok(stored)
}

