crates/sync/src/devices.rs::with_mobile_.source_code:
pub fn with_mobile_pause(mut rows: Vec<PeerRow>, paused: bool) -> Vec<PeerRow> {
    if paused {
        for row in &mut rows {
            if row.state == PeerState::NotNearby {
                row.state = PeerState::PausedOnMobileData;
            }
        }
    }
    rows
}

crates/sync/src/devices.rs::with_local_n.source_code:
pub fn with_local_network_block(mut rows: Vec<PeerRow>, blocked: bool) -> Vec<PeerRow> {
    if blocked {
        for row in &mut rows {
            if row.state == PeerState::NotNearby {
                row.state = PeerState::BlockedByLocalNetwork;
            }
        }
    }
    rows
}

