pub struct Schedule {
    /// The first waits, in order.
    pub steps: Vec<Duration>,
    /// The wait once the steps are used up, repeated for as long as the app is open.
    pub steady: Duration,
}

fn default() -> Self {
    Self {
        steps: [5, 15, 60].map(Duration::from_secs).to_vec(),
        steady: Duration::from_secs(300),
    }
}

