pub struct Backoff {
    schedule: Schedule,
    failures: usize,
}

pub fn new(schedule: Schedule) -> Self {
    Self {
        schedule,
        failures: 0,
    }
}

pub fn next_delay(&mut self) -> Duration {
    let wait = self
        .schedule
        .steps
        .get(self.failures)
        .copied()
        .unwrap_or(self.schedule.steady);
    self.failures = self.failures.saturating_add(1);
    wait
}

