async fn finish(&mut self, stats: SessionStats) -> Result<(), SyncError> {
    let peer = self.peer.clone();
    let (received, sent) = (stats.received, stats.sent);
    blocking(self.host(), move |conn| {
        Ok(peer_state::finished(conn, &peer, received, sent)?)
    })
    .await?;
    tracing::info!(target: "sync", received, sent, "session finished");
    self.shared.update(&self.peer, true, |l| {
        l.syncing = false;
        l.progress = None;
    });
    let _ = self.done.send(RoundDone {
        peer: self.peer.clone(),
        received: news(&stats),
    });
    Ok(())
}

crates/sync/src/live/conn.rs::run.source_code:
pub(super) async fn run(mut conn: Conn) -> Result<(), SyncError> {
    let mut round = Some(conn.start_round().await?);
    let mut again = false;
    // A farewell asked for: waiting for the next session to start, and the session it started.
    let mut farewell = None;
    let mut farewell_round: Option<tokio::sync::oneshot::Sender<()>> = None;
    loop {
        tokio::select! {
            message = conn.transport.recv() => {
                let message = message?;
                let session = match round.take() {
                    Some(session) => session,
                    // Idle and spoken to: answer with our own Hello, then deal with theirs.
                    None if matches!(message, Message::Hello { .. }) => conn.start_round().await?,
                    None => {
                        return Err(SyncError::Protocol("a message out of turn".into()));
                    }
                };
                round = conn.feed(session, message).await?;
            }
            cmd = conn.cmds.recv() => match cmd {
                Some(ConnCmd::Round) => again = true,
                Some(ConnCmd::Farewell(tx)) => {
                    again = true;
                    farewell = Some(tx);
                }
                Some(ConnCmd::Close) | None => return Ok(()),
            },
            () = tokio::time::sleep(SILENCE), if round.is_some() => {
                return Err(SyncError::Disconnected);
            }
        }
        if round.is_none() {
            if let Some(tx) = farewell_round.take() {
                let _ = tx.send(());
            }
            if !conn.keep_open && farewell.is_none() {
                return Ok(());
            }
            if again {
                again = false;
                // Only a session that starts now carries what was written before the farewell.
                round = Some(conn.start_round().await?);
                farewell_round = farewell.take();
            }
        }
    }
}

crates/sync/src/live/dial.rs::candidates.source_code:
pub(super) fn candidates(
    found: &[SocketAddr],
    remembered: &[SocketAddr],
    typed: &[SocketAddr],
) -> Vec<SocketAddr> {
    let mut out: Vec<SocketAddr> = Vec::new();
    for addr in found.iter().chain(remembered).chain(typed) {
        if !out.contains(addr) {
            out.push(*addr);
        }
    }
    // Stable: the order inside each group stays.
    out.sort_by_key(|addr| !addresses::is_tailscale(addr.ip()));
    out
}

crates/sync/src/live/dial.rs::race.source_code:
pub(super) async fn race(
    config: &NetConfig,
    addrs: Vec<SocketAddr>,
    each: Duration,
    local: &Arc<LocalNetwork>,
) -> Option<Established> {
    let mut attempts = JoinSet::new();
    for addr in addrs {
        let (config, local) = (config.clone(), Arc::clone(local));
        attempts.spawn(async move {
            let result = tokio::time::timeout(each, dial(&config, addr)).await;
            match &result {
                Ok(Ok(_)) => local.dial_worked(addr),
                Ok(Err(e)) => local.dial_failed(addr, e),
                Err(_) => {}
            }
            result
        });
    }
    while let Some(result) = attempts.join_next().await {
        match result {
            Ok(Ok(Ok(established))) => return Some(established),
            Ok(Ok(Err(e))) => tracing::debug!(target: "sync", error = %e, "dial failed"),
            Ok(Err(_)) => tracing::debug!(target: "sync", "dial timed out"),
            Err(_) => {}
        }
    }
    None
}

