pub fn replaces(me: &str, peer: &str, existing_by_me: bool, new_by_me: bool) -> bool {
    if existing_by_me == new_by_me {
        return true;
    }
    // The dialler of the new connection is lower than the dialler of the old one.
    let dialler = |by_me: bool| if by_me { me } else { peer };
    dialler(new_by_me) < dialler(existing_by_me)
}

crates/sync/src/live/tie.rs::replaces.docstring:
//! When two devices dial each other at the same moment they end up with two connections. Both
//! must keep the same one, so the rule uses only what both can see: the connection dialled by the
//! device with the lower id wins.
/// Whether a newly established connection should replace the one already held with the same
/// device. `existing_by_me` and `new_by_me` say whether this device dialled that connection.
///
/// A connection dialled by the same side as the held one replaces it: the old one is likely
/// half-dead (the other end restarted or the network changed), and the new one proves itself.

crates/sync/src/local_network.rs::Rhythm.source_code:
pub struct Rhythm {
    /// How long the failures must have gone on, so a first prompt the person has not answered yet
    /// (which can refuse the first operations at once) is not taken for a refusal.
    pub grace: Duration,
    /// The pause between probes while the last one failed and the grace has not run out.
    pub fast: Duration,
    /// The pause between probes while they fail after the grace.
    pub slow: Duration,
    /// The pause between probes while they work: a permission switched off later is noticed.
    pub steady: Duration,
}

fn default() -> Self {
    Self {
        grace: Duration::from_secs(30),
        fast: Duration::from_secs(3),
        slow: Duration::from_secs(10),
        steady: Duration::from_secs(60),
    }
}

crates/sync/src/local_network.rs::is_den.source_code:
pub fn is_denial(e: &io::Error) -> bool {
    e.kind() == io::ErrorKind::HostUnreachable
}

crates/sync/src/local_network.rs::is_lan.source_code:
pub fn is_lan(ip: IpAddr) -> bool {
    if addresses::is_tailscale(ip) {
        return false;
    }
    match ip {
        IpAddr::V4(v4) => v4.is_private() || v4.is_link_local(),
        IpAddr::V6(v6) => {
            let first = v6.segments()[0];
            // fe80::/10 link-local, fc00::/7 unique-local.
            first & 0xffc0 == 0xfe80 || first & 0xfe00 == 0xfc00
        }
    }
}

crates/sync/src/local_network.rs::Outcom.source_code:
pub enum Outcome {
    /// Refused the way the permission refuses.
    Blocked,
    /// Got through, or got an answer that only a working network gives (a refused connection).
    Worked,
    /// Says nothing either way (a timeout, a network that is down).
    Unknown,
}

crates/sync/src/local_network.rs::outcom.source_code:
pub fn outcome_of_failure(addr: SocketAddr, error: &NetError) -> Outcome {
    // A link-local IPv6 address needs its interface named to be dialled; without it the system
    // answers "No route to host" with the permission wide open.
    let scopeless = matches!(addr.ip(), IpAddr::V6(v6) if v6.segments()[0] & 0xffc0 == 0xfe80);
    if !is_lan(addr.ip()) || scopeless {
        return Outcome::Unknown;
    }
    match error {
        NetError::Io(io) if is_denial(io) => Outcome::Blocked,
        NetError::Io(io) if io.kind() == io::ErrorKind::ConnectionRefused => Outcome::Worked,
        // Something answered at the other end: TLS, the handshake, a closed line.
        NetError::Io(_) | NetError::Timeout | NetError::Local(_) | NetError::Key(_) => {
            Outcome::Unknown
        }
        _ => Outcome::Worked,
    }
}

crates/sync/src/local_network.rs::Source.source_code:
pub enum Source {
    /// A dial to a LAN address.
    Dial,
    /// The probe.
