pub fn validate_name(raw: &str) -> Result<String, SyncError> {
    let name = raw.trim();
    match name.chars().count() {
        0 => Err(SyncError::Validation("Give this device a name")),
        n if n > MAX_NAME_CHARS => Err(SyncError::Validation(
            "A device name is at most 40 characters",
        )),
        _ => Ok(name.to_owned()),
    }
}

crates/sync/src/name.rs::tidy.source_code:
fn tidy(raw: &str) -> String {
    let squeezed = raw.split_whitespace().collect::<Vec<_>>().join(" ");
    let cut: String = squeezed.chars().take(MAX_NAME_CHARS).collect();
    let cut = cut.trim_end().to_owned();
    if cut.is_empty() {
        FALLBACK_NAME.to_owned()
    } else {
        cut
    }
}

crates/sync/src/net/frame.rs::write_fram.source_code:
pub async fn write_frame<W, T>(writer: &mut W, message: &T) -> Result<(), NetError>
where
    W: AsyncWrite + Unpin,
    T: Serialize,
{
    let body = serde_json::to_vec(message).map_err(|e| NetError::Malformed(e.to_string()))?;
    if body.len() > MAX_FRAME {
        return Err(NetError::TooLarge(body.len()));
    }
    let len = u32::try_from(body.len()).map_err(|_| NetError::TooLarge(body.len()))?;
    writer.write_all(&len.to_be_bytes()).await?;
    writer.write_all(&body).await?;
    writer.flush().await?;
    Ok(())
}

crates/sync/src/net/frame.rs::read_frame.source_code:
pub async fn read_frame_max<R, T>(reader: &mut R, max: usize) -> Result<T, NetError>
where
    R: AsyncRead + Unpin,
    T: DeserializeOwned,
{
    let mut header = [0u8; 4];
    match reader.read_exact(&mut header).await {
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Err(NetError::Closed),
        Err(e) => return Err(e.into()),
    }
    let len = u32::from_be_bytes(header) as usize;
    if len > max.min(MAX_FRAME) {
        return Err(NetError::TooLarge(len));
    }
    let mut body = Vec::new();
    let got = reader.take(len as u64).read_to_end(&mut body).await?;
    if got < len {
        return Err(NetError::Io(std::io::ErrorKind::UnexpectedEof.into()));
    }
    serde_json::from_slice(&body).map_err(|e| NetError::Malformed(e.to_string()))
}

