crates/sync/src/net/handshake.rs::Refusa.source_code:
pub enum Refusal {
    /// The peer speaks another protocol version.
    Protocol {
        /// The peer's version.
        theirs: u32,
    },
    /// The peer runs in the other Environment.
    Environment,
    /// The peer's key is not pinned.
    Unpinned,
    /// The peer's key is pinned, but as another device than the one it claims to be.
    WrongDevice,
    /// The peer belongs to a different group.
    Group,
    /// The peer is this device.
    SelfDial,
}

fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    match self {
        Self::Protocol { theirs } => write!(f, "protocol version {theirs} is not supported"),
        Self::Environment => f.write_str("it runs in another Environment"),
        Self::Unpinned => f.write_str("its key is not pinned"),
        Self::WrongDevice => f.write_str("its key belongs to another device"),
        Self::Group => f.write_str("it belongs to another group"),
        Self::SelfDial => f.write_str("it is this device"),
    }
}

crates/sync/src/net/handshake.rs::check.source_code:
pub fn check(
    local: &Handshake,
    remote: &Handshake,
    key: &PublicKey,
    trust: &Trust,
) -> Result<Vec<String>, Refusal> {
    if remote.protocol != local.protocol {
        return Err(Refusal::Protocol {
            theirs: remote.protocol,
        });
    }
    if remote.environment != local.environment {
        return Err(Refusal::Environment);
    }
    if remote.device == local.device {
        return Err(Refusal::SelfDial);
    }
    match trust.device_of(key) {
        None => return Err(Refusal::Unpinned),
        Some(device) if device != remote.device => return Err(Refusal::WrongDevice),
        Some(_) => {}
    }
    if let (Some(ours), Some(theirs)) = (&local.group, &remote.group)
        && ours != theirs
    {
        return Err(Refusal::Group);
    }
    Ok(local.differing_modules(remote))
}

crates/sync/src/net/identity.rs::PublicK.source_code:
pub const fn from_bytes(bytes: [u8; 32]) -> Self {
    Self(bytes)
}

pub fn verify(&self, message: &[u8], signature: &[u8]) -> bool {
    ring::signature::UnparsedPublicKey::new(&ring::signature::ED25519, &self.0)
        .verify(message, signature)
        .is_ok()
}

pub fn to_hex(self) -> String {
    use std::fmt::Write;
    self.0.iter().fold(String::with_capacity(64), |mut s, b| {
        let _ = write!(s, "{b:02x}");
        s
    })
}

pub fn from_hex(text: &str) -> Option<Self> {
    if text.len() != 64 || !text.is_ascii() {
        return None;
    }
    let mut out = [0u8; 32];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&text[i * 2..i * 2 + 2], 16).ok()?;
    }
    Some(Self(out))
}

fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    f.write_str(&self.to_hex())
}

crates/sync/src/net/identity.rs::DeviceI.source_code:
pub struct DeviceIdentity {
    pkcs8: Vec<u8>,
    cert: CertificateDer<'static>,
    public: PublicKey,
}

pub fn load_or_create(dir: &Path) -> Result<Self, NetError> {
    let path = key_path(dir);
    match std::fs::read(&path) {
        Ok(der) => {
            tighten(&path)?;
            Self::from_pkcs8(der)
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            let pair = KeyPair::generate_for(&PKCS_ED25519).map_err(key_err)?;
            let der = pair.serialize_der();
            write_private(&path, &der)?;
            tracing::info!(target: "sync", "made this device's network key");
            Self::from_pkcs8(der)
        }
        Err(e) => Err(e.into()),
    }
}

pub fn from_pkcs8(der: Vec<u8>) -> Result<Self, NetError> {
    let pair = KeyPair::try_from(der.as_slice()).map_err(key_err)?;
    let public = <[u8; 32]>::try_from(pair.public_key_raw())
        .map_err(|_| NetError::Key("not an Ed25519 key".into()))?;
    let params = CertificateParams::new(vec!["mnemora.local".to_owned()]).map_err(key_err)?;
    let cert = params.self_signed(&pair).map_err(key_err)?;
    Ok(Self {
        pkcs8: der,
        cert: cert.der().clone(),
        public: PublicKey(public),
    })
}

pub fn generate() -> Result<Self, NetError> {
    let pair = KeyPair::generate_for(&PKCS_ED25519).map_err(key_err)?;
    Self::from_pkcs8(pair.serialize_der())
}

pub fn sign(&self, message: &[u8]) -> Result<Vec<u8>, NetError> {
    let pair = ring::signature::Ed25519KeyPair::from_pkcs8_maybe_unchecked(&self.pkcs8)
        .map_err(|_| NetError::Key("not an Ed25519 key".into()))?;
    Ok(pair.sign(message).as_ref().to_vec())
}

