crates/sync/src/pair/hub.rs::Pairing.spa.source_code:
fn spawn(&self, task: impl Future<Output = ()> + Send + 'static) -> AbortHandle {
    self.tasks.fetch_add(1, Ordering::SeqCst);
    let count = TaskCount(Arc::clone(&self.tasks));
    self.runtime
        .spawn(async move {
            let _count = count;
            task.await;
        })
        .abort_handle()
}

