pub enum Msg {
    /// Typer to shower: the typer's Environment and its SPAKE2 message.
    Start {
        /// The typer's Environment.
        environment: Environment,
        /// SPAKE2 message, hex.
        spake: String,
    },
    /// Shower to typer: its SPAKE2 message.
    Reply {
        /// SPAKE2 message, hex.
        spake: String,
    },
    /// Typer to shower: proof it knows the code and sees the same two keys.
    Confirm {
        /// HMAC tag, hex.
        tag: String,
    },
    /// Shower to typer: its own proof, and who it is.
    Confirmed {
        /// HMAC tag, hex.
        tag: String,
        /// The shower.
        who: Box<Who>,
    },
    /// Shower to typer: the proof did not match.
    Wrong {
        /// Tries left on the code.
        tries_left: u8,
        /// The shower's name, so the typer can say where to look.
        name: String,
    },
    /// Typer to shower: who it is.
    Identity {
        /// The typer.
        who: Box<Who>,
    },
    /// Shower to typer: allowed. `group` is the group both now belong to.
    Accepted {
        /// Group id.
        group: String,
    },
    /// Shower to typer: allowed, and what the shower holds (for the first-merge preview). The
    /// typer answers `Reviewing` (it shows the preview) or `Go` (nothing to preview).
    Allowed {
        /// The shower's Entries, Tasks and Lists.
        holdings: Holdings,
    },
    /// Typer to shower: the typer's person is looking at the merge preview.
    Reviewing,
    /// Typer to shower: merge. The typer's database is backed up; the shower backs up its own,
    /// records the pairing and says `Accepted`.
    Go,
    /// Typer to shower: stored on its side.
    Done,
    /// Either way: no.
    Refuse {
        /// Why.
        reason: Reason,
    },
}

crates/sync/src/pair/msg.rs::hex.source_code:
pub fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write;
    bytes
        .iter()
        .fold(String::with_capacity(bytes.len() * 2), |mut s, b| {
            let _ = write!(s, "{b:02x}");
            s
        })
}

crates/sync/src/pair/msg.rs::unhex.source_code:
pub fn unhex(text: &str) -> Option<Vec<u8>> {
    if !text.len().is_multiple_of(2) || !text.is_ascii() {
        return None;
    }
    (0..text.len() / 2)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).ok())
        .collect()
}

