async fn until(&self, what: &str, want: impl Fn(&PairingView) -> bool) -> PairingView {
    for _ in 0..600 {
        let view = self.state();
        if want(&view) {
            return view;
        }
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    panic!(
        "{}: never saw {what}; last view {:?}",
        self.host.name,
        self.state()
    );
}

