         ORDER BY last_ok_at IS NULL, last_ok_at DESC",
    )?;
    let rows = stmt.query_map([device], |r| r.get::<_, String>(0))?;
    Ok(rows
        .filter_map(Result::ok)
        .filter_map(|a| a.parse().ok())
        .collect())
}

