fn read(conn: &Connection, device: &str) -> rusqlite::Result<Option<Row>> {
    conn.query_row(
        "SELECT device, public_key, name, platform, state, at, by_device, signature
         FROM sync_revocations WHERE device = ?1",
        [device],
        |r| {
            Ok(Row {
                device: r.get(0)?,
                public_key: r.get(1)?,
                name: r.get(2)?,
                platform: r.get(3)?,
                state: r.get(4)?,
                at: r.get(5)?,
                by: r.get(6)?,
                signature: r.get(7)?,
            })
        },
    )
    .optional()
}

