fn record(conn: &Connection, row: &Row, existed: bool) -> AppResult<()> {
    changelog::record(
        conn,
        &Change {
            module: crate::MODULE_ID.to_owned(),
            entity: ENTITY.to_owned(),
            entity_id: row.device.clone(),
            op: if existed {
                ChangeOp::Update
            } else {
                ChangeOp::Create
            },
            session_id: None,
            snapshot: row.json(),
        },
    )
}

