fn announce_end(&mut self, conn: &Connection) {
    if self.is_done() && !self.announced {
        self.announced = true;
        self.log(conn);
        if !self.stats.changed.is_empty() {
            self.bus.publish(&RemoteSessionEnded {
                modules: self.stats.changed.iter().cloned().collect(),
            });
        }
    }
}

