fn announce(&self, conn: &Connection, events: Vec<SyncEvent>) {
    let mut settings: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut raised = 0_u32;
    for event in events {
        match event {
            SyncEvent::SettingChanged { module, key } => {
                settings.entry(module).or_default().push(key);
            }
            SyncEvent::ListsMerged {
                from_id,
                from_name,
                from_device,
                into_id,
                into_name,
                into_device,
            } => {
                // The device that is not this one: the survivor's, else the other List's.
                let other = [into_device, from_device]
                    .into_iter()
                    .flatten()
                    .find(|d| *d != self.me);
                let device = other.and_then(|d| peers::name_of(conn, &d).ok().flatten());
                tracing::debug!(target: "sync", "two Lists with the same name merged");
                self.bus.publish(&ListsMerged {
                    from_id,
                    from_name,
                    into_id,
                    into_name,
                    device,
                });
            }
            SyncEvent::ConflictRaised { .. } => {
                raised += 1;
                tracing::debug!(target: "sync", "a text clash was recorded");
            }
            SyncEvent::ConflictAutoResolved { .. } => {
                tracing::debug!(target: "sync", "a text clash was resolved on its own");
            }
            SyncEvent::TaskDeleted {
                task_id,
                title,
                device,
            } => {
                // The origin's id was put in `device` by the engine; a name if it is paired.
                let device = device
                    .filter(|d| *d != self.me)
                    .and_then(|d| peers::name_of(conn, &d).ok().flatten());
                tracing::debug!(target: "sync", "a Task was deleted on another device");
                self.bus.publish(&TaskDeletedRemotely {
                    task_id,
                    title,
                    device,
                });
            }
            SyncEvent::TaskToInbox { .. } => {
                tracing::debug!(target: "sync", "a Task went to the Inbox: its List is gone");
            }
            SyncEvent::EntryDeleted {
                entry_id,
                page_date,
                device,
            } => {
                let device = device
                    .filter(|d| *d != self.me)
                    .and_then(|d| peers::name_of(conn, &d).ok().flatten());
                tracing::debug!(target: "sync", "an Entry was deleted on another device");
                self.bus.publish(&EntryDeletedRemotely {
                    entry_id,
                    page_date,
                    device,
                });
            }
            SyncEvent::DeviceRenamed { name } => {
                tracing::debug!(target: "sync", "another device renamed this one");
                self.bus.publish(&DeviceRenamed { name });
            }
        }
    }
    for (module, keys) in settings {
        self.bus.publish(&SettingsChanged { module, keys });
    }
    if raised > 0 {
        let device = self
            .peer()
            .and_then(|p| peers::name_of(conn, p).ok().flatten());
        self.bus.publish(&ConflictsRaised {
            count: raised,
            device,
        });
    }
}

crates/sync/src/session.rs::Session.next.source_code:
fn next_outbound(&mut self, conn: &Connection) -> Result<Message, SyncError> {
    let Some((_, peer_vector)) = &self.peer else {
        return Err(SyncError::Protocol("no Hello yet".into()));
    };
    let (records, more) = next_batch(
        conn,
        &self.registry,
        &self.me,
        peer_vector,
        &mut self.cursor,
    )?;
    for record in &records {
        if record.entity != activity::ENTITY {
            self.stats.sent += 1;
            *self
                .moved
                .entry((record.module.clone(), record.entity.clone()))
                .or_default() += 1;
        }
    }
    self.in_flight = records.len();
    let first = !self.first_sent;
    self.first_sent = true;
    self.outbound = Outbound::AwaitingAck { last: !more };
    Ok(Message::Batch {
        records,
        last: !more,
        total: first.then_some(self.out_total),
    })
}

