fn take(tasks: &mut Vec<Task>, keep: &dyn Fn(&Task) -> bool) -> Vec<Task> {
    let (taken, rest): (Vec<_>, Vec<_>) = tasks.drain(..).partition(|t| keep(t));
    *tasks = rest;
    taken
}

