crates/todo/src/history.rs::edit_lines.source_code:
fn edit_lines(old: &Snap, cur: &Snap, record: &Record, base: &Baseline, out: &mut Lines) {
    if old.number("priority") != cur.number("priority") {
        out.push((
            "priority",
            format!(
                "Priority P{} → P{}",
                old.number("priority").unwrap_or(4),
                cur.number("priority").unwrap_or(4)
            ),
        ));
    }
    if record.session_id.is_none() {
        return;
    }
    if cur.text("title").unwrap_or_default() != base.title {
        out.push(("title", "Title edited".to_owned()));
    }
    if cur.text("notes").unwrap_or_default() != base.notes {
        out.push(("notes", "Notes edited".to_owned()));
    }
}

crates/todo/src/history.rs::edit_lines.docstring:
/// Priority, and the text edits. Only an editing session edits text, and a session's record can
/// be rewritten after other changes (it carries the latest snapshot), so the text is compared with
/// the `base` from before the session, never with the neighbouring record: one opening of the
/// sheet is one "Title edited" and one "Notes edited" line however much happened in between.

crates/todo/src/history.rs::record_lines.source_code:
fn record_lines(
    conn: &Connection,
    prev: Option<&Value>,
    cur: &Value,
    base: &Baseline,
    record: &Record,
) -> AppResult<Lines> {
    let cur = Snap(cur);
    let Some(prev) = prev else {
        return Ok(if record.op == "create" {
            vec![first_line(&cur)]
        } else {
            Vec::new()
        });
    };
    let old = Snap(prev);
    let (old_due, new_due) = (old.text("due_date"), cur.text("due_date"));
    let step = record.op == "tick"
        && old.text("state") == cur.text("state")
        && old_due.is_some()
        && new_due.is_some()
        && old_due != new_due;
    let skipped = step && cur.0.get("skipped").and_then(Value::as_bool) == Some(true);
    let mut out = Vec::new();
    state_lines(&old, &cur, step, skipped, &mut out);
    schedule_lines(conn, &old, &cur, step, &mut out)?;
    edit_lines(&old, &cur, record, base, &mut out);
    Ok(out)
}

crates/todo/src/history.rs::advance.source_code:
fn advance(state: &Value, record: &Record) -> (Value, Value) {
    let mut next = match &record.fields {
        Some(fields) => {
            let fields = if record.local {
                let mut whole = wire_fields(
                    &crate::sync::TASK,
                    Some(fields.clone()),
                    &record.snapshot,
                    true,
                );
                // `skipped` is a marker of the record, not a field Sync knows.
                if let Some(skipped) = fields.get("skipped") {
                    whole.insert("skipped".to_owned(), skipped.clone());
                }
                whole
            } else {
                fields.clone()
            };
            let mut next = if state.is_object() {
                state.clone()
            } else {
                Value::Object(Map::new())
            };
            if let Some(map) = next.as_object_mut() {
                for (key, value) in fields.iter().filter(|(k, _)| *k != "skipped") {
                    map.insert(key.clone(), value.clone());
                }
            }
            next
        }
        None => record.snapshot.clone(),
    };
    let marker = match &record.fields {
        Some(fields) => fields.get("skipped").cloned(),
        None => next.get("skipped").cloned(),
    };
    if let Some(map) = next.as_object_mut() {
        map.remove("skipped");
    }
    let mut seen = next.clone();
    if let (Some(map), Some(marker)) = (seen.as_object_mut(), marker) {
        map.insert("skipped".to_owned(), marker);
    }
    (next, seen)
}

crates/todo/src/history.rs::advance.docstring:
/// The Task as History saw it after `record`, and the same with the record's own `skipped`
/// marker. History is a function of the records alone, which every device holds identically: a
/// record changes the running state by its own `fields` (the author's values), never by the
/// snapshot, which on a received record is this device's merged state and differs between
/// devices after concurrent edits. A record without `fields` (from before Sync) is its snapshot.
/// An own record is completed the way it is sent (a change to the Due date carries the whole When),
/// so that its author reads the same History as the devices that received it.

crates/todo/src/history.rs::task_history.source_code:
pub fn task_history(conn: &Connection, id: &str) -> AppResult<Vec<HistoryLine>> {
    repo::get(conn, id)?.ok_or(TodoError::TaskNotFound)?;
    let records = changelog::read(conn, ENTITY, id)?;
    let mut batches: Vec<Vec<HistoryLine>> = Vec::with_capacity(records.len());
    let mut prev: Option<Value> = None;
    let mut base: Option<Baseline> = None;
    for record in &records {
        let (state, seen) = advance(prev.as_ref().unwrap_or(&Value::Null), record);
        let lines = record_lines(
            conn,
            prev.as_ref(),
            &seen,
            base.as_ref().unwrap_or(&Baseline::of(&Snap(&state))),
            record,
        )?
        .into_iter()
        .map(|(kind, text)| HistoryLine {
            at: record.at,
            kind: kind.to_owned(),
            text,
        })
        .collect();
        batches.push(lines);
        // A session settles the text; so do creating and a tick (a Checklist reset). Any other
        // record only carries the text of a session that is still being written.
        if base.is_none()
            || record.session_id.is_some()
            || matches!(record.op.as_str(), "create" | "tick")
        {
            base = Some(Baseline::of(&Snap(&state)));
        }
        prev = Some(state);
    }
    Ok(batches.into_iter().rev().flatten().collect())
}

