crates/todo/src/list_sync.rs::settle.source_code:
pub(crate) fn settle(conn: &Connection, change: &RemoteChange<'_>) -> AppResult<Settled> {
    let Some((list, Some(PARKED))) = list_repo::get_any(conn, change.entity_id)? else {
        return Ok(Settled::default());
    };
    let mut settled = Settled::default();
    match list_repo::live_twin(conn, &name_key(&list.name), &list.id)? {
        Some(other) if other.id < list.id => {
            // The parked List is the newer: it goes away.
            merge(conn, &list, &other, &mut settled)?;
        }
        Some(other) => {
            merge(conn, &other, &list, &mut settled)?;
            list_repo::unpark(conn, &list.id)?;
        }
        None => list_repo::unpark(conn, &list.id)?,
    }
    // Which List a gone List's Tasks belong in may have changed with the decision.
    rehome(conn, &list.id, &[name_key(&list.name)], true)?;
    Ok(settled)
}

crates/todo/src/list_sync.rs::rehome.source_code:
fn rehome(conn: &Connection, id: &str, keys: &[String], revived: bool) -> AppResult<()> {
    let mut affected = vec![id.to_owned()];
    let mut gone = revived;
    for key in keys {
        affected.extend(list_repo::with_name_key(conn, key)?);
    }
    affected.sort();
    affected.dedup();
    for list in &affected {
        gone |= list_repo::get(conn, list)?.is_none();
    }
    if !gone {
        return Ok(());
    }
    for list in &affected {
        for (task, column) in repo::chosen_list_is(conn, list)? {
            let place = list_repo::home(conn, list)?;
            if column != place {
                repo::update_columns(conn, &task, &[("list_id", &place)])?;
            }
        }
    }
    Ok(())
}

crates/todo/src/list_sync.rs::rehome.docstring:
/// Tasks sit where `list_repo::home` says their List's place is. That depends on the Lists, which
/// change after a Task was placed (a rename into the name of a deleted List, a deleted List
/// restored), so when a List changes its Tasks are placed again: every live Task whose newest
/// List choice (from the change log, the same on every device) names a List this change can
/// affect: the List itself and the deleted Lists with its old or new name. Only the column is
/// written, so nothing is recorded and every device ends with the same place for every Task,
/// whatever order the Lists and the Tasks arrived in. `revived`: the List was deleted and is
/// live again.

crates/todo/src/list_sync.rs::merge.source_code:
fn merge(
    conn: &Connection,
    from: &TodoList,
    into: &TodoList,
    settled: &mut Settled,
) -> AppResult<()> {
    let now = now_ms();
    // Keys only grow: a Task whose key is already past the end keeps it.
    let mut end = repo::in_list(conn, &into.id)?
        .last()
        .map(|t| t.sort_key.clone());
    for mut task in repo::in_list(conn, &from.id)? {
        task.list_id = Some(into.id.clone());
        if end
            .as_deref()
            .is_some_and(|end| task.sort_key.as_str() <= end)
        {
            task.sort_key = key_after(end.as_deref());
        }
        end = Some(task.sort_key.clone());
        task.updated_at = now;
        repo::update_list(conn, &task)?;
        repo::update_sort_key(conn, &task)?;
        record_at(conn, &task, ChangeOp::Move, None)?;
    }
    list_repo::set_deleted(conn, &from.id, Some(now), now)?;
    record_list(conn, from, ChangeOp::Delete, Some(now))?;
    settled.recorded = true;
    settled.events.push(merged_event(conn, from, into)?);
    Ok(())
}

crates/todo/src/migrations.rs::all.source_code:
pub fn all() -> Migrations<'static> {
    Migrations::new(vec![
        // Dates are `YYYY-MM-DD` and times `HH:MM`, both floating local. `sort_key` is text that
        // sorts bytewise (fractional-index keys); a Task's `list_id` of NULL is the Inbox.
        // `name_key` is the List name folded for case and accents, so names are unique among live
        // Lists. `understood` is JSON; `repeat_of` points an occurrence copy at its live Task.
        M::up(
            "CREATE TABLE todo_lists(
                 id TEXT PRIMARY KEY NOT NULL,
                 name TEXT NOT NULL,
                 name_key TEXT NOT NULL,
                 emoji TEXT,
                 sort_key TEXT NOT NULL,
                 task_sort TEXT NOT NULL DEFAULT 'manual',
                 group_by TEXT,
                 created_at INTEGER NOT NULL,
                 updated_at INTEGER NOT NULL,
                 deleted_at INTEGER
             ) STRICT;
             CREATE UNIQUE INDEX todo_lists_name
                 ON todo_lists(name_key) WHERE deleted_at IS NULL;
             CREATE INDEX todo_lists_order
                 ON todo_lists(sort_key) WHERE deleted_at IS NULL;

             CREATE TABLE todo_tasks(
                 id TEXT PRIMARY KEY NOT NULL,
                 list_id TEXT REFERENCES todo_lists(id),
                 title TEXT NOT NULL,
                 notes TEXT NOT NULL DEFAULT '',
                 due_date TEXT,
                 due_time TEXT,
                 repeat_freq TEXT,
                 repeat_every INTEGER,
                 repeat_days INTEGER,
                 repeat_mode TEXT,
                 priority INTEGER NOT NULL DEFAULT 4 CHECK (priority BETWEEN 1 AND 4),
                 state TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'done', 'wont')),
                 closed_at INTEGER,
                 repeat_of TEXT REFERENCES todo_tasks(id),
                 understood TEXT,
                 sort_key TEXT NOT NULL,
                 created_at INTEGER NOT NULL,
                 updated_at INTEGER NOT NULL,
                 deleted_at INTEGER
             ) STRICT;
             CREATE INDEX todo_tasks_open
                 ON todo_tasks(list_id, sort_key) WHERE state = 'open' AND deleted_at IS NULL;
             CREATE INDEX todo_tasks_due
                 ON todo_tasks(due_date) WHERE state = 'open' AND deleted_at IS NULL;
             CREATE INDEX todo_tasks_closed
                 ON todo_tasks(closed_at) WHERE state <> 'open' AND deleted_at IS NULL;
             CREATE INDEX todo_tasks_occurrences
                 ON todo_tasks(repeat_of) WHERE repeat_of IS NOT NULL;

             CREATE TABLE todo_comments(
                 id TEXT PRIMARY KEY NOT NULL,
                 task_id TEXT NOT NULL REFERENCES todo_tasks(id),
                 body TEXT NOT NULL,
                 created_at INTEGER NOT NULL,
                 updated_at INTEGER NOT NULL,
                 deleted_at INTEGER
             ) STRICT;
             CREATE INDEX todo_comments_task
                 ON todo_comments(task_id, created_at) WHERE deleted_at IS NULL;",
        ),
        // Search indexes: external content, kept in step by triggers, same tokenizer and prefix
        // settings as the Journal. Deleted rows stay indexed (Undo); queries filter on
        // `deleted_at`. They are keyed on the tables' implicit rowids, which VACUUM may renumber
        // (the tables have a TEXT primary key): never VACUUM without rebuilding both indexes.
        M::up(
            "CREATE VIRTUAL TABLE todo_tasks_fts USING fts5(
                 title, notes, content='todo_tasks', content_rowid='rowid',
                 tokenize='unicode61 remove_diacritics 2', prefix='2 3'
             );
             CREATE TRIGGER todo_tasks_fts_insert AFTER INSERT ON todo_tasks BEGIN
                 INSERT INTO todo_tasks_fts(rowid, title, notes)
                 VALUES (new.rowid, new.title, new.notes);
             END;
             CREATE TRIGGER todo_tasks_fts_delete AFTER DELETE ON todo_tasks BEGIN
                 INSERT INTO todo_tasks_fts(todo_tasks_fts, rowid, title, notes)
                 VALUES ('delete', old.rowid, old.title, old.notes);
             END;
             CREATE TRIGGER todo_tasks_fts_update AFTER UPDATE OF title, notes ON todo_tasks BEGIN
                 INSERT INTO todo_tasks_fts(todo_tasks_fts, rowid, title, notes)
                 VALUES ('delete', old.rowid, old.title, old.notes);
                 INSERT INTO todo_tasks_fts(rowid, title, notes)
                 VALUES (new.rowid, new.title, new.notes);
             END;

             CREATE VIRTUAL TABLE todo_comments_fts USING fts5(
                 body, content='todo_comments', content_rowid='rowid',
                 tokenize='unicode61 remove_diacritics 2', prefix='2 3'
             );
             CREATE TRIGGER todo_comments_fts_insert AFTER INSERT ON todo_comments BEGIN
                 INSERT INTO todo_comments_fts(rowid, body) VALUES (new.rowid, new.body);
             END;
             CREATE TRIGGER todo_comments_fts_delete AFTER DELETE ON todo_comments BEGIN
                 INSERT INTO todo_comments_fts(todo_comments_fts, rowid, body)
                 VALUES ('delete', old.rowid, old.body);
             END;
             CREATE TRIGGER todo_comments_fts_update AFTER UPDATE OF body ON todo_comments BEGIN
                 INSERT INTO todo_comments_fts(todo_comments_fts, rowid, body)
                 VALUES ('delete', old.rowid, old.body);
                 INSERT INTO todo_comments_fts(rowid, body) VALUES (new.rowid, new.body);
             END;",
        ),
        M::up(TRIM_KEY_ZEROS),
        M::up(SEARCH_VOCABULARY),
        M::up(COMMENT_EDITED_FLAG),
    ])
}

