struct Token {
    /// First and last (exclusive) char of the core, in chars.
    from: usize,
    to: usize,
    /// The core, lowercased.
    low: String,
    /// The core as typed.
    raw: String,
    /// A comma followed the core.
    comma: bool,
    /// Inside a quote or backticks.
    masked: bool,
}

crates/todo/src/parse.rs::mask_ranges.source_code:
fn mask_ranges(chars: &[char]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let close = match chars[i] {
            '"' => '"',
            '“' => '”',
            '`' => '`',
            _ => {
                i += 1;
                continue;
            }
        };
        match chars[i + 1..].iter().position(|&c| c == close) {
            Some(n) => {
                out.push((i, i + 1 + n + 1));
                i += n + 2;
            }
            None => i += 1,
        }
    }
    out
}

crates/todo/src/parse.rs::tokenize.source_code:
fn tokenize(chars: &[char]) -> Vec<Token> {
    let masks = mask_ranges(chars);
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].is_whitespace() {
            i += 1;
            continue;
        }
        let a = i;
        while i < chars.len() && !chars[i].is_whitespace() {
            i += 1;
        }
        let (mut from, mut to) = (a, i);
        while from < to && matches!(chars[from], '(' | '[' | '{') {
            from += 1;
        }
        let mut comma = false;
        while to > from
            && matches!(
                chars[to - 1],
                '.' | ',' | ';' | ':' | '!' | '?' | ')' | ']' | '}'
            )
        {
            comma |= chars[to - 1] == ',';
            to -= 1;
        }
        if from == to {
            continue;
        }
        let raw: String = chars[from..to].iter().collect();
        out.push(Token {
            from,
            to,
            low: raw.to_lowercase(),
            raw,
            comma,
            masked: masks.iter().any(|&(s, e)| a < e && i > s),
        });
    }
    out
}

crates/todo/src/parse.rs::weekday_name.source_code:
fn weekday_name(word: &str) -> Option<u32> {
    Some(match word {
        "sun" | "sunday" => 0,
        "mon" | "monday" => 1,
        "tue" | "tues" | "tuesday" => 2,
        "wed" | "wednesday" => 3,
        "thu" | "thur" | "thurs" | "thursday" => 4,
        "fri" | "friday" => 5,
        "sat" | "saturday" => 6,
        _ => return None,
    })
}

