fn understood_record(spans: &[ParseSpan], list_id: Option<&str>) -> Option<String> {
    let entries: Vec<Understood<'_>> = spans
        .iter()
        .filter_map(|s| {
            let value = if s.kind == "list" {
                list_id?.to_owned()
            } else {
                s.value.clone()
            };
            Some(Understood {
                word: &s.word,
                kind: &s.kind,
                value,
            })
        })
        .collect();
    if entries.is_empty() {
        None
    } else {
        serde_json::to_string(&entries).ok()
    }
}

