pub(crate) fn first_match(self, today: &str) -> Option<String> {
    if self.unit == Unit::Week && self.days != 0 {
        (0..7)
            .filter_map(|i| add_days(today, i))
            .find(|d| weekday(d).is_some_and(|w| self.days & (1 << w) != 0))
    } else {
        epoch_day(today).map(|_| today.to_owned())
    }
}

