pub(crate) fn step(self, date: &str) -> Option<String> {
    self.raw_step(date).filter(|d| d.len() == 10)
}

crates/todo/src/recurrence.rs::Rule.raw_.source_code:
fn raw_step(self, date: &str) -> Option<String> {
    let every = i64::from(self.every);
    match self.unit {
        Unit::Day => add_days(date, every),
        Unit::Week if self.days == 0 => add_days(date, 7 * every),
        Unit::Week => {
            // The week runs Monday (0) to Sunday (6); chosen days later in this week come
            // first, then the week `every` weeks on.
            let from = i64::from((weekday(date)? + 6) % 7);
            let hit = |offset: i64| self.days & (1 << ((offset + 1) % 7)) != 0;
            if let Some(offset) = (from + 1..7).find(|&o| hit(o)) {
                return add_days(date, offset - from);
            }
            let offset = (0..7).find(|&o| hit(o))?;
            add_days(date, 7 * every - from + offset)
        }
        Unit::Month => {
            let d = Ymd::parse(date)?;
            let months = i64::from(d.year) * 12 + i64::from(d.month) - 1 + every;
            let (year, month) = (months / 12, months % 12 + 1);
            Ymd::clamped(year, month, if self.days > 0 { self.days } else { d.day })
        }
        Unit::Year => {
            let d = Ymd::parse(date)?;
            let day = if self.days > 0 { self.days } else { d.day };
            Ymd::clamped(i64::from(d.year) + every, i64::from(d.month), day)
        }
    }
}

crates/todo/src/recurrence.rs::Rule.next.source_code:
pub(crate) fn next_due(self, due: &str, today: &str) -> Result<String, TodoError> {
    if self.after {
        return self.step(today).ok_or(TOO_FAR);
    }
    let mut date = self.step(due).ok_or(TOO_FAR)?;
    while date.as_str() <= today {
        date = self.step(&date).ok_or(TOO_FAR)?;
    }
    Ok(date)
}

crates/todo/src/recurrence.rs::Rule.next.docstring:
/// Where a Task due `due` goes when it is done on `today`: from the day it is done in "after"
/// mode; otherwise the first date on the schedule after today, which is one step after the
/// Due date when that is still ahead (done early) and skips the missed ones when late.

crates/todo/src/recurrence.rs::Rule.prev.source_code:
pub(crate) fn preview(self, from: &str, count: usize) -> Vec<String> {
    let mut out = Vec::with_capacity(count);
    let mut date = from.to_owned();
    while out.len() < count {
        let Some(next) = self.step(&date) else { break };
        out.push(next.clone());
        date = next;
    }
    out
}

crates/todo/src/recurrence.rs::Rule.prev.docstring:
/// The next `count` dates after `from` (the Due date, or for "after done" the day it is
/// done), each a step on the last: the "Next:" line of the picker. The picker draws it from the
/// TypeScript copy of this engine; this one pins the maths in tests.

crates/todo/src/recurrence.rs::Ymd.source_code:
struct Ymd {
    year: u32,
    month: u32,
    day: u32,
}

crates/todo/src/recurrence.rs::Ymd.parse.source_code:
fn parse(date: &str) -> Option<Self> {
    epoch_day(date)?;
    Some(Self {
        year: date[0..4].parse().ok()?,
        month: date[5..7].parse().ok()?,
        day: date[8..10].parse().ok()?,
    })
}

crates/todo/src/recurrence.rs::Ymd.clamp.source_code:
fn clamped(year: i64, month: i64, day: u32) -> Option<String> {
    if !(1..=MAX_YEAR).contains(&year) {
        return None;
    }
    let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    let last = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        _ => 28,
    };
    Some(format!("{year:04}-{month:02}-{:02}", day.min(last)))
}

crates/todo/src/reorder.rs::place_key.source_code:
pub(crate) fn place_key(
    before: Option<&str>,
    after: Option<&str>,
    key_before: impl Fn(&str) -> AppResult<Option<String>>,
    key_following: impl Fn(&str) -> AppResult<Option<String>>,
) -> AppResult<Option<String>> {
    let (lo, hi) = match (before, after) {
        (None, None) => return Ok(None),
        (Some(b), Some(a)) if b.trim_end_matches('0') < a.trim_end_matches('0') => {
            (Some(b.to_owned()), Some(a.to_owned()))
        }
        (Some(b), _) => (Some(b.to_owned()), key_following(b)?),
        (None, Some(a)) => (key_before(a)?, Some(a.to_owned())),
    };
    // Deleted rows keep their keys, so the neighbour may be the one that is moving: a key between
    // `lo` and it is still on the right side of everything else.
    Ok(Some(
        key_between(lo.as_deref(), hi.as_deref()).map_err(TodoError::Validation)?,
    ))
}

crates/todo/src/reorder.rs::place_key.docstring:
/// The sort key that puts something between its neighbours, or none to leave it where it is
/// (no neighbours). `before` and `after` are the neighbours' keys: the one directly above and the
/// one directly below the new place. The views can disagree with the manual order (a sort, or
/// Priority inside a time block), so the neighbours may be out of order or not adjacent: the new
/// key then goes just after `before`, or just before `after`, in the whole order.

crates/todo/src/reorder.rs::reorder_task.source_code:
pub fn reorder_task(
    conn: &mut Connection,
    id: &str,
    before: Option<&str>,
    after: Option<&str>,
    target: &[GroupKey],
    local: &LocalNow,
) -> AppResult<Task> {
    local.check()?;
    for key in target {
        if let GroupKey::Day { date } = key {
            validate_pickable(date, &local.today)?;
        }
        if let GroupKey::Priority { priority } = key {
            validate_priority(*priority)?;
        }
    }
    let tx = conn.transaction()?;
    let mut task = repo::get(&tx, id)?.ok_or(TodoError::TaskNotFound)?;
    if task.state != TaskState::Open {
        return Err(TodoError::Validation("That Task is already closed").into());
    }
    let neighbour = |n: Option<&str>| -> AppResult<Option<String>> {
        match n.filter(|n| *n != id) {
            None => Ok(None),
            Some(n) => Ok(Some(
                repo::get_any(&tx, n)?
                    .ok_or(TodoError::TaskNotFound)?
                    .sort_key,
            )),
        }
    };
    let (before_key, after_key) = (neighbour(before)?, neighbour(after)?);
    let (mut key_changed, mut when_changed, mut priority_changed, mut list_changed) =
        (false, false, false, false);
    if let Some(key) = place_key(
        before_key.as_deref(),
        after_key.as_deref(),
        |k| repo::key_before(&tx, k),
        |k| repo::key_following(&tx, k),
    )? && key != task.sort_key
    {
        task.sort_key = key;
        key_changed = true;
    }
    for key in target {
        match key {
            GroupKey::Day { date } if task.due_date.as_deref() != Some(date.as_str()) => {
                let (time, rule) = (task.due_time.clone(), rule_of(&task)?);
                when_changed |= assign_when(&mut task, Some(date.clone()), time, rule, false)?;
            }
            GroupKey::Priority { priority } if task.priority != *priority => {
                task.priority = *priority;
                priority_changed = true;
            }
            GroupKey::List { list_id } if task.list_id != *list_id => {
                if let Some(list_id) = list_id {
                    list_repo::get(&tx, list_id)?.ok_or(TodoError::ListNotFound)?;
                }
                task.list_id.clone_from(list_id);
                list_changed = true;
            }
            _ => {}
        }
    }
    if key_changed || when_changed || priority_changed || list_changed {
        task.updated_at = now_ms();
        if key_changed {
            repo::update_sort_key(&tx, &task)?;
        }
        if when_changed {
            repo::update_when(&tx, &task)?;
        }
        if priority_changed {
            repo::update_priority(&tx, &task)?;
        }
        if list_changed {
            repo::update_list(&tx, &task)?;
        }
        let op = if list_changed {
            ChangeOp::Move
        } else {
            ChangeOp::Update
        };
        record_at(&tx, &task, op, None)?;
    }
    tx.commit()?;
    Ok(task)
}

crates/todo/src/reorder.rs::reorder_task.docstring:
/// Moves an open Task between two neighbours, and into a group: `target` is what the group
/// adopts (see `TaskGroup::adopt`). A day sets the Due date (never a past one: that is refused,
/// and Overdue adopts nothing), a Priority sets the Priority, a List moves it there. One change
/// is recorded: `move` when the List changed, `update` otherwise; nothing when nothing changed.

crates/todo/src/reorder.rs::reorder_list.source_code:
pub fn reorder_list(
    conn: &mut Connection,
    id: &str,
    before: Option<&str>,
    after: Option<&str>,
) -> AppResult<TodoList> {
    let tx = conn.transaction()?;
    let mut list = list_repo::get(&tx, id)?.ok_or(TodoError::ListNotFound)?;
    let neighbour = |n: Option<&str>| -> AppResult<Option<String>> {
        match n.filter(|n| *n != id) {
            None => Ok(None),
            Some(n) => Ok(Some(
                list_repo::get(&tx, n)?
                    .ok_or(TodoError::ListNotFound)?
                    .sort_key,
            )),
        }
    };
    let (before_key, after_key) = (neighbour(before)?, neighbour(after)?);
    if let Some(key) = place_key(
        before_key.as_deref(),
        after_key.as_deref(),
        |k| list_repo::key_before(&tx, k),
        |k| list_repo::key_following(&tx, k),
    )? && key != list.sort_key
    {
        list.sort_key = key;
        list.updated_at = now_ms();
        list_repo::update_sort_key(&tx, &list)?;
        crate::list_service::record_list(&tx, &list, ChangeOp::Update, None)?;
    }
    tx.commit()?;
    Ok(list)
}

