pub fn upcoming(conn: &Connection, local: &LocalNow) -> AppResult<UpcomingView> {
    local.check()?;
    let prefs = ViewPrefs::read(conn)?;
    let mut overdue = Vec::new();
    let mut future = Vec::new();
    for task in repo::open_dated(conn)? {
        match task
            .due_date
            .as_deref()
            .map(|d| d.cmp(local.today.as_str()))
        {
            Some(Ordering::Less) => overdue.push(task),
            Some(Ordering::Greater) => future.push(task),
            _ => {}
        }
    }
    overdue.sort_by(by_date_then_day);
    let lists: Vec<_> = ordered_lists(conn, prefs.lists_sort)?
        .into_iter()
        .map(|e| e.list)
        .collect();
    let ctx = GroupContext {
        lists: &lists,
        today: &local.today,
    };
    let mut groups: Vec<TaskGroup> = overdue_group(overdue).into_iter().collect();
    groups.extend(group_tasks(
        future,
        prefs.group_upcoming,
        &ctx,
        &by_date_then_day,
    ));
    Ok(UpcomingView {
        group_by: prefs.group_upcoming,
        groups,
    })
}

crates/todo/src/schedule.rs::week_ahead.source_code:
pub(crate) fn week_ahead(
    conn: &Connection,
    local: &LocalNow,
    days: i64,
) -> AppResult<(Vec<Task>, Vec<TaskGroup>)> {
    local.check()?;
    let last = add_days(&local.today, days).ok_or(TodoError::Validation("Not a valid date"))?;
    let (mut overdue, mut coming) = (Vec::new(), Vec::new());
    for task in repo::open_dated(conn)? {
        let Some(due) = task.due_date.as_deref() else {
            continue;
        };
        if due < local.today.as_str() {
            overdue.push(task);
        } else if due > local.today.as_str() && due <= last.as_str() {
            coming.push(task);
        }
    }
    overdue.sort_by(by_date_then_day);
    let ctx = GroupContext {
        lists: &[],
        today: &local.today,
    };
    let groups = group_tasks(coming, GroupBy::Day, &ctx, &by_date_then_day);
    Ok((overdue, groups))
}

