crates/todo/src/search.rs::search.source_code:
pub fn search(conn: &Connection, query: &str) -> AppResult<TaskSearchResults> {
    let terms = query::parse(query);
    let mut results = TaskSearchResults {
        exact: Vec::new(),
        similar: Vec::new(),
        truncated: false,
        similar_truncated: false,
    };
    let Some(exact_match) = query::exact_match(&terms) else {
        return Ok(results);
    };

    let mut rows = search_repo::search(conn, &exact_match, None, MAX_EXACT + 1)?;
    results.truncated = rows.len() > MAX_EXACT;
    rows.truncate(MAX_EXACT);
    results.exact = hits(conn, rows, &Matcher::new(&terms, &[]))?;

    let near = near_for(conn, &terms)?;
    if near.iter().any(|n| !n.is_empty())
        && let Some(expanded) = query::expand_match(&terms, &near)
    {
        let mut rows = search_repo::search(conn, &expanded, Some(&exact_match), MAX_SIMILAR + 1)?;
        results.similar_truncated = rows.len() > MAX_SIMILAR;
        rows.truncate(MAX_SIMILAR);
        results.similar = hits(conn, rows, &Matcher::new(&terms, &near))?;
    }
    Ok(results)
}

crates/todo/src/search.rs::search.docstring:
/// Searches live Tasks. Every word is required and matches by prefix; quoted text is an exact
/// phrase. Nothing to search for returns nothing; deleted Tasks and Comments are never found.
/// A known v1 limit: the words must all match in the title and notes together or all in one
/// Comment, so words split between a Task and its Comments find nothing.

crates/todo/src/search.rs::near_for.source_code:
fn near_for(conn: &Connection, terms: &[Term]) -> AppResult<Vec<Vec<String>>> {
    let lengths: Vec<usize> = terms
        .iter()
        .filter_map(|t| match t {
            Term::Word(w) if tolerance(w.chars().count()) > 0 => Some(w.chars().count()),
            _ => None,
        })
        .collect();
    let (Some(min), Some(max)) = (lengths.iter().min(), lengths.iter().max()) else {
        return Ok(vec![Vec::new(); terms.len()]);
    };
    let vocab =
        search_repo::vocabulary(conn, min.saturating_sub(MAX_TOLERANCE), max + MAX_TOLERANCE)?;
    Ok(near_terms(terms, vocab.into_iter()))
}

crates/todo/src/search_repo.rs::search.source_code:
pub fn search(
    conn: &Connection,
    matching: &str,
    excluding: Option<&str>,
    limit: usize,
) -> AppResult<Vec<Task>> {
    const HIT: &str = "(rowid IN (SELECT rowid FROM todo_tasks_fts WHERE todo_tasks_fts MATCH {})
         OR id IN (SELECT c.task_id FROM todo_comments c
                    WHERE c.deleted_at IS NULL AND c.rowid IN
                      (SELECT rowid FROM todo_comments_fts WHERE todo_comments_fts MATCH {})))";
    let mut sql = format!(
        "SELECT {COLUMNS} FROM todo_tasks WHERE deleted_at IS NULL AND {}",
        HIT.replace("{}", "?1")
    );
    if excluding.is_some() {
        sql.push_str(" AND NOT ");
        sql.push_str(&HIT.replace("{}", "?2"));
    }
    sql.push_str(
        " ORDER BY (state <> 'open'), CASE WHEN state = 'open' THEN sort_key END,
                   closed_at DESC, id LIMIT ?3",
    );
    let mut stmt = conn.prepare(&sql)?;
    stmt.query_map(params![matching, excluding, sql_int(limit)], from_row)?
        .collect::<Result<_, _>>()
        .map_err(corrupt_or_db)
}

