crates/todo/src/service.rs::complete_tas.source_code:
pub fn complete_task(conn: &mut Connection, id: &str, local: &LocalNow) -> AppResult<Completion> {
    local.check()?;
    let tx = conn.transaction()?;
    let mut task = repo::get(&tx, id)?.ok_or(TodoError::TaskNotFound)?;
    if task.state != TaskState::Open {
        return Err(TodoError::Validation("That Task is already closed").into());
    }
    if let Some(rule) = repeat::rule_of(&task)? {
        let completion = repeat::complete(&tx, task, rule, local)?;
        tx.commit()?;
        return Ok(completion);
    }
    let now = now_ms();
    task.state = TaskState::Done;
    task.closed_at = Some(now);
    task.updated_at = now;
    repo::update_state(&tx, &task)?;
    record(&tx, &task, ChangeOp::Tick)?;
    tx.commit()?;
    Ok(Completion {
        task,
        occurrence: None,
    })
}

crates/todo/src/service.rs::reopen_task.source_code:
pub fn reopen_task(conn: &mut Connection, id: &str) -> AppResult<Task> {
    let tx = conn.transaction()?;
    let mut task = repo::get(&tx, id)?.ok_or(TodoError::TaskNotFound)?;
    if task.state == TaskState::Open {
        return Err(TodoError::Validation("That Task is already open").into());
    }
    if let (Some(parent), TaskState::Done) = (task.repeat_of.clone(), task.state) {
        let rewound = repeat::rewind(&tx, task, &parent)?;
        tx.commit()?;
        return Ok(rewound);
    }
    task.state = TaskState::Open;
    task.closed_at = None;
    task.updated_at = now_ms();
    repo::update_state(&tx, &task)?;
    record(&tx, &task, ChangeOp::Tick)?;
    tx.commit()?;
    Ok(task)
}

crates/todo/src/service.rs::move_task.source_code:
pub fn move_task(conn: &mut Connection, id: &str, list_id: Option<&str>) -> AppResult<Task> {
    let tx = conn.transaction()?;
    let mut task = repo::get(&tx, id)?.ok_or(TodoError::TaskNotFound)?;
    if let Some(list_id) = list_id {
        list_repo::get(&tx, list_id)?.ok_or(TodoError::ListNotFound)?;
    }
    if task.list_id.as_deref() == list_id {
        return Ok(task);
    }
    task.list_id = list_id.map(str::to_owned);
    task.updated_at = now_ms();
    repo::update_list(&tx, &task)?;
    record(&tx, &task, ChangeOp::Move)?;
    tx.commit()?;
    Ok(task)
}

crates/todo/src/steps.rs::checklist_line.source_code:
fn checklist_lines(notes: &str) -> impl Iterator<Item = (&str, Option<(usize, bool)>)> {
    let mut fence: Option<(char, usize)> = None;
    notes.split_inclusive('\n').map(move |line| {
        if let Some(open) = fence_of(line) {
            match fence {
                None => fence = Some(open),
                Some((mark, len)) if open.0 == mark && open.1 >= len && is_bare_fence(line) => {
                    fence = None;
                }
                Some(_) => {}
            }
            return (line, None);
        }
        if fence.is_some() {
            return (line, None);
        }
        (line, step_box(line))
    })
}

crates/todo/src/steps.rs::checklist_line.docstring:
//! Open steps and "Tick all and complete": Rust ports of `openSteps` and `tickAllSteps`
//! (`src/modules/todo/notes.ts`), so the Todo widget decides exactly as the app does.
//! `src/lib/ipc/fixtures/todo-steps.json` runs the same cases here and in Vitest. Task text must
//! never reach a log line.
/// The notes' lines, each with its line end kept, and whether it is a Checklist item that is not
/// ticked: `(line, index of the character between the brackets)`.

crates/todo/src/steps.rs::fence_of.source_code:
fn fence_of(line: &str) -> Option<(char, usize)> {
    let body = line.trim_start_matches(' ');
    if line.len() - body.len() > 3 {
        return None;
    }
    let mark = body.chars().next().filter(|c| matches!(c, '`' | '~'))?;
    let len = body.chars().take_while(|&c| c == mark).count();
    (len >= 3).then_some((mark, len))
}

crates/todo/src/steps.rs::is_bare_fence.source_code:
fn is_bare_fence(line: &str) -> bool {
    line.trim()
        .chars()
        .all(|c| c == '`' || c == '~' || c.is_whitespace())
}

crates/todo/src/steps.rs::step_box.source_code:
fn step_box(line: &str) -> Option<(usize, bool)> {
    let bytes = line.as_bytes();
    let mut i = 0;
    while matches!(bytes.get(i), Some(b' ' | b'\t' | b'>')) {
        i += 1;
    }
    match bytes.get(i)? {
        b'-' | b'*' | b'+' => i += 1,
        b'0'..=b'9' => {
            while bytes.get(i)?.is_ascii_digit() {
                i += 1;
            }
            if !matches!(bytes.get(i)?, b'.' | b')') {
                return None;
            }
            i += 1;
        }
        _ => return None,
    }
    let spaces = i;
    while matches!(bytes.get(i), Some(b' ' | b'\t')) {
        i += 1;
    }
    if i == spaces || bytes.get(i)? != &b'[' || bytes.get(i + 2)? != &b']' {
        return None;
    }
    // A bare box at the end of the line is not an item in the app.
    if !matches!(bytes.get(i + 3)?, b' ' | b'\t' | b'\r') {
        return None;
    }
    match bytes.get(i + 1)? {
        b' ' => Some((i + 1, false)),
        b'x' | b'X' => Some((i + 1, true)),
        _ => None,
    }
}

crates/todo/src/steps.rs::step_box.docstring:
/// Where the box of a Checklist item is: `(byte index of the character between [ and ], ticked)`.
/// A line is an item when, after quote marks and indent, it has a bullet (`-`, `*`, `+`) or a
/// number with `.` or `)`, some space, then `[ ]`, `[x]` or `[X]` followed by a space or tab.

crates/todo/src/steps.rs::checklist_item.source_code:
pub(crate) fn checklist_items(notes: &str) -> Vec<(String, bool)> {
    checklist_lines(notes)
        .filter_map(|(line, item)| item.map(|(_, ticked)| (line.trim().to_owned(), ticked)))
        .collect()
}

crates/todo/src/steps.rs::open_steps.source_code:
pub fn open_steps(notes: &str) -> usize {
    checklist_lines(notes)
        .filter(|(_, item)| matches!(item, Some((_, false))))
        .count()
}

crates/todo/src/steps.rs::tick_all_steps.source_code:
pub fn tick_all_steps(notes: &str) -> String {
    let mut out = String::with_capacity(notes.len());
    for (line, item) in checklist_lines(notes) {
        match item {
            Some((at, false)) => {
                out.push_str(line.get(..at).unwrap_or(line));
                out.push('x');
                out.push_str(line.get(at + 1..).unwrap_or(""));
            }
            _ => out.push_str(line),
        }
    }
    out
}

