crates/todo/src/task.rs::Task.source_code:
pub struct Task {
    /// `UUIDv7`.
    pub id: String,
    /// The List it belongs to; none means the Inbox.
    pub list_id: Option<String>,
    /// One line, up to 500 characters.
    pub title: String,
    /// Markdown notes.
    pub notes: String,
    /// Due date, `YYYY-MM-DD`.
    pub due_date: Option<String>,
