pub fn delete_task(conn: &mut Connection, id: &str) -> AppResult<()> {
    let tx = conn.transaction()?;
    let task = repo::get(&tx, id)?.ok_or(TodoError::TaskNotFound)?;
    let now = now_ms();
    repo::set_deleted(&tx, id, Some(now), now)?;
