crates/todo/src/tools.rs::Search.run.source_code:
fn run(&self, conn: &Connection, args: &Args, _calendar: &Calendar) -> Output {
    let query = args.text("query").unwrap_or_default();
    let state = args.text("state").unwrap_or("any");
    let list = match list_filter(conn, args.text("list")) {
        Ok(list) => list,
        Err(refusal) => return refusal,
    };
    let offset = count(args.int("offset"), 0);
    let limit = count(args.int("limit"), SEARCH_DEFAULT);
    let names = match list_names(conn) {
        Ok(names) => names,
        Err(refusal) => return refusal,
    };
    let Ok(results) = crate::search(conn, query) else {
        return Output::error("Search could not run. Check the words.");
    };
    let matching: Vec<&Task> = results
        .exact
        .iter()
        .chain(results.similar.iter())
        .map(|hit| &hit.task)
        .filter(|task| state == "any" || task.state.as_str() == state)
        .filter(|task| match &list {
            ListPick::Any => true,
            ListPick::Inbox => task.list_id.is_none(),
            ListPick::List(id) => task.list_id.as_deref() == Some(id.as_str()),
        })
        .collect();
    let total = matching.len();
    let page: Vec<&Task> = matching.into_iter().skip(offset).take(limit).collect();
    let rows: Vec<Value> = page
        .iter()
        .map(|t| row_json(t, &list_label(&names, t)))
        .collect();
    let items = page.iter().map(|t| item(t)).collect();
    let next = (offset + limit < total).then_some(offset + limit);
    Output::ok(
        json!({ "tasks": rows, "next_offset": next }),
        format!("Searched tasks, {total} found"),
        items,
    )
}

crates/todo/src/upgrade.rs::append_todo_.source_code:
pub fn append_todo_tab(
    conn: &Connection,
    device: &DeviceStore,
    report: &MigrationReport,
) -> AppResult<()> {
    let first_run_of = |id: &str| {
        report
            .applied
            .iter()
            .any(|(m, from, _)| m == id && *from == 0)
    };
    if !first_run_of(MODULE_ID) || first_run_of("core") {
        return Ok(());
    }
    let look = device.get().look;
    if look.phone_tabs_edited == Some(true) {
        return Ok(());
    }
    let off = stored(conn, "core", "disabled_modules")?
        .and_then(|v| v.as_array().map(|a| a.contains(&json!(MODULE_ID))))
        .unwrap_or(false);
    let Some(mut tabs) = look.phone_tabs else {
        return Ok(());
    };
    let home = || "home".to_owned();
    let pinned = tabs == [home()] || tabs == [home(), "journal".to_owned()];
    if off || !pinned || tabs.len() >= MAX_TABS {
        return Ok(());
    }
    tabs.push(MODULE_ID.to_owned());
    device.update(|d| d.look.phone_tabs = Some(tabs))
}

crates/todo/src/upgrade.rs::append_todo_.docstring:
/// An install that never edited its phone tabs gets Todo appended, once. "Never edited" is a
/// saved value (a Device setting) without the `core.phone_tabs_edited` marker (which saving the tabs from Settings
/// sets) that is exactly what an upgrade pins: nothing saved, so the new default already has Todo,
/// or `["home"]` (the Journal's upgrade) or `["home", "journal"]`, which gain Todo at the end. Any
/// other saved list counts as edited, marker or not, and stays as it is. It never runs again, so
/// removing the tab later sticks; it adds nothing to four tabs or past a switched-off Todo.

