	open: boolean,
	/**  How it ended, once it has. */
	resolution: string | null,
	/**  The text showing now, words the other version lacks marked. */
	showing: DiffSpan[],
	/**  The other version, words the showing text lacks marked. */
	other: DiffSpan[],
	/**  The text both devices started from. */
	original: string,
	/**  The text, cut at the clashes, for Edit merged. */
	pieces: ClashPiece[],
};

src/lib/ipc/bindings.ts::ConnectionTest.source_code:
type ConnectionTest = {
	/**  Whether the Provider answered. */
	connected: boolean,
	/**  How many Models it offers, when it answered. */
	models: number,
	/**  Why it did not answer, when it did not. */
	failure: Failure | null,
	/**  What to show the person. */
	message: string,
};

src/lib/ipc/bindings.ts::ConversationPag.source_code:
type ConversationPage = {
	/**  The Conversations on this page, newest first. */
	items: ConversationSummary[],
	/**  Whether another page follows this one. */
	more: boolean,
};

src/lib/ipc/bindings.ts::ConversationSum.source_code:
type ConversationSummary = {
	/**  The Conversation's id. */
	id: string,
	/**  Its title. */
	title: string,
	/**  When it was started, in milliseconds (a number for TypeScript, as for entries). */
	created_at: number | null,
	/**  When it last changed, in milliseconds; the history is newest first by this. */
	updated_at: number | null,
};

src/lib/ipc/bindings.ts::ConversationVie.source_code:
type ConversationView = {
	/**  The Conversation's id. */
	id: string,
	/**  Its title: the first question, trimmed. */
	title: string,
	/**  When it was started, in milliseconds (a number for TypeScript, as for entries). */
	created_at: number | null,
	/**  When it last changed, in milliseconds. */
	updated_at: number | null,
	/**  The Provider the Conversation last used, on this device. */
	provider_id: string | null,
	/**  The Provider the Conversation last used, by name, as text (other devices may not have it). */
	provider_name: string | null,
	/**  The Model the Conversation last used. */
	model: string | null,
	/**  Whether a Run is answering in it on this device right now. */
	running: boolean,
	/**  The notes waiting for that Run, in the order they will be sent. Empty when none is answering. */
	queued: QueuedNote[],
	/**  Every entry, oldest first. */
	entries: EntryView[],
};

src/lib/ipc/bindings.ts::Counts.source_code:
type Counts = {
	/**  Journal Entries. */
	entries: number,
	/**  Tasks. */
	tasks: number,
	/**  Lists. */
	lists: number,
};

src/lib/ipc/bindings.ts::DayCount.source_code:
type DayCount = {
	/**  `YYYY-MM-DD`. */
	date: string,
	/**  Open Tasks due that day. */
	count: number,
};

src/lib/ipc/bindings.ts::DeleteChoice.source_code:
type DeleteChoice = 
/**  Delete them with the List (the default). */
{ kind: "delete_tasks" } | 
/**  Move them to the Inbox. */
{ kind: "move_to_inbox" } | 
/**  Move them to another List. */
{ kind: "move_to_list"; 
/**  The receiving List. */
list_id: string };

src/lib/ipc/bindings.ts::DeviceDetail.source_code:
type DeviceDetail = {
	/**  Its device id. */
	id: string,
	/**  Its name here. */
	name: string,
	/**  Its kind. */
	platform: Platform,
	/**  Where it stands now. */
	state: PeerState,
	/**  When it was paired: UTC milliseconds. */
	paired_at: number,
	/**  The name of the device that paired it; this device's own name when this one did. */
	paired_by: string | null,
	/**  When it was last reached. */
	last_seen_at: number | null,
	/**  When a session with it last finished. */
	last_synced_at: number | null,
	/**  How it was reached the last time. */
	route: Route | null,
	/**  Addresses remembered for it, the one that worked most recently first. */
	addresses: KnownAddress[],
	/**  The Address typed for it, as stored. */
	typed_address: string | null,
	/**  Its app version, once it has been reached. */
	app_version: string | null,
	/**  Its Modules' data versions, once it has been reached. */
	data_versions: ModuleVersion[],
};

src/lib/ipc/bindings.ts::DeviceSettings.source_code:
type DeviceSettings = {
	/**
	 *  Random id of this install in this Environment (a `UUIDv7`), made on first run and then
	 *  stable. `None` until [`DeviceStore::device_id`] first needs it.
	 */
	device_id?: string | null,
	/**  Custom data folder; `None` means the platform default. */
	data_dir?: string | null,
	/**  Window geometry. */
	window?: WindowState,
	/**  Sidebar layout. */
	sidebar?: SidebarState,
	/**  `tracing` level: error, warn, info, debug or trace. */
	log_level?: string,
	/**  Spellcheck in every text editor. Per device: input methods and dictionaries differ. */
	spellcheck?: boolean,
	/**  Theme, density, text size, reduce motion and phone tabs. */
	look?: LookAndFeel,
	/**  The Sync Module's choices for this device. */
	sync?: SyncDevice,
};

src/lib/ipc/bindings.ts::DevicesView.source_code:
type DevicesView = {
	/**  This device. */
	this_device: ThisDevice,
	/**  The paired devices. */
	peers: PeerRow[],
};

src/lib/ipc/bindings.ts::DiffSpan.source_code:
type DiffSpan = {
	/**  The text, line breaks included. */
	text: string,
	/**  Words here are not in the other version. */
	changed: boolean,
};

src/lib/ipc/bindings.ts::DoneDay.source_code:
type DoneDay = {
	/**  The device's day, `YYYY-MM-DD`. */
	date: string,
	/**  Newest first. */
	tasks: Task[],
};

src/lib/ipc/bindings.ts::DoneInLists.source_code:
type DoneInLists = 
/**  Done today struck through at the bottom, older ones behind "Done earlier". */
"today_shown" | 
/**  All behind one fold. */
"folded" | 
/**  All shown, struck through. */
"shown" | 
/**  None. */
"hidden";

src/lib/ipc/bindings.ts::DoneView.source_code:
type DoneView = {
	/**  The days of this page. */
	days: DoneDay[],
	/**  Hand it back as the cursor for the next page; none when this was the last. */
	next_cursor: string | null,
};

src/lib/ipc/bindings.ts::DueBucket.source_code:
type DueBucket = 
/**  Before today. */
"overdue" | 
/**  Today. */
"today" | 
/**  Tomorrow. */
"tomorrow" | 
/**  The six days after tomorrow. */
"week" | 
/**  Further away. */
"later" | 
/**  No Due date. */
"no_date";

src/lib/ipc/bindings.ts::DueChange.source_code:
type DueChange = {
	/**  The Task. */
	id: string,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`. */
	due_time: string | null,
	/**  The Repeat, which goes with the date. */
	repeat: RepeatRule | null,
};

src/lib/ipc/bindings.ts::Entry.source_code:
type Entry = {
	/**  `UUIDv7`. */
	id: string,
	/**  The Page this Entry sits on, `YYYY-MM-DD`. */
	page_date: string,
	/**  Markdown text. */
	body: string,
	/**  When it was written: UTC milliseconds. Never changes. */
	written_at: number,
	/**  UTC offset in minutes where it was written. */
	written_offset_min: number,
	/**  IANA zone where it was written. */
	written_tz: string,
	/**  When it was last meaningfully edited: UTC milliseconds. */
	edited_at: number | null,
	/**  Words in the body, not counting Markdown symbols. */
	word_count: number,
	/**  Row creation time: UTC milliseconds. */
	created_at: number,
	/**  Row update time: UTC milliseconds. */
	updated_at: number,
};

src/lib/ipc/bindings.ts::EntryKind.source_code:
type EntryKind = 
/**  The person's question. */
"user" | 
/**  The Model's answer, or a Step that asked for Tools. */
"assistant" | 
/**  What a Tool returned for one call. */
"tool_result" | 
/**  A correction turn the Model was sent. */
"correction" | 
/**  The Provider and Model the following questions use. */
"model_change";

src/lib/ipc/bindings.ts::EntryPayload.source_code:
type EntryPayload = 
/**  The person's question. */
{ kind: "user"; 
/**  The question as typed. */
text: string } | 
/**
 *  The Model's reply in one Step: the answer when it asks for no Tools, or the Tools it asked
 *  for. The answer carries the Provider and Model as text, so another device can show them.
 */
{ kind: "assistant"; 
/**  The reply's Markdown. */
text: string; 
/**  How the reply ended. */
stop: StopReason; 
/**  The name of the Provider that answered. */
provider: string; 
/**  The Model id that answered. */
model: string; 
/**  The Tool calls this Step made, in order. */
calls: CallRecord[]; 
/**  The Entries and Tasks the answer cites, which a Tool returned in this Run. */
sources: Source[]; 
/**  Why the answer may be incomplete, when the Run ran out of steps. */
budget_note: string | null } | 
/**  What a Tool returned for one call. */
{ kind: "tool_result"; 
/**  The call it answers. */
call_id: string; 
/**  The Tool's name. */
name: string; 
/**  The arguments the Model sent (JSON text). */
arguments: string; 
/**  What the Model read back, labelled with its observation id. */
result: string; 
/**  Whether the call was refused. */
is_error: boolean; 
/**  The observation id this result is known by in the Run ("e1"). */
observation_id: string; 
/**  The plain line the activity shows for it. */
summary: string } | 
/**  A correction the Model was sent, such as a citation no Tool returned. */
{ kind: "correction"; 
/**  What the Model was told. */
text: string } | 
/**  The Conversation switched to another Provider and Model. Carries no text for the Model. */
{ kind: "model_change"; 
/**  The name of the Provider chosen. */
provider_name: string; 
/**  The Model id chosen. */
model: string };

src/lib/ipc/bindings.ts::EntryView.source_code:
type EntryView = {
	/**  The entry's id. */
	id: string,
	/**  The entry this one followed, or none for the first question. */
	parent_id: string | null,
	/**
	 *  When it was written, in milliseconds. Typed as a number for TypeScript (ids and instants
	 *  stay below 2^53); specta refuses `i64`.
	 */
	created_at: number | null,
	/**  What it holds. */
	payload: EntryPayload,
	/**
	 *  How many questions share this one's place (Try again and Edit add more). Always 1 for an
	 *  entry that is not a question, and for a question with no siblings.
	 */
	sibling_count: number,
	/**  This question's place among them, from 1, oldest first. */
	sibling_index: number,
};

src/lib/ipc/bindings.ts::Environment.source_code:
type Environment = 
/**  The user's real data. */
"production" | 
/**  Separate, disposable data. */
"sandbox";

src/lib/ipc/bindings.ts::ErrorCode.source_code:
type ErrorCode = 
/**  A value failed validation. */
"validation" | 
/**  A key is not registered. */
"unknown_key" | 
/**  The record asked for does not exist (or is deleted). */
"not_found" | 
/**  Filesystem failure. */
"io" | 
/**  Database failure. */
"database" | 
/**  Anything else; a bug or an unexpected state. */
"internal";

src/lib/ipc/bindings.ts::Failure.source_code:
type Failure = 
/**  No Provider is set up on this device. */
"no_provider" | 
/**  The address could not be reached. */
"unreachable" | 
/**  The service did not answer in time. */
"timeout" | 
/**  The service refused the key. */
"key_rejected" | 
/**  The service is busy or has a limit in force. */
"rate_limited" | 
/**  The chosen Model is not offered by this service. */
"model_unavailable" | 
/**  The chosen Model cannot make Tool calls. */
"model_cannot_use_tools" | 
/**  The reply was not in a shape Mnemora can read. */
"bad_response" | 
/**  The request is too large for the Model. */
"too_long" | 
/**  The Run was stopped by the app (Android background, an abort). */
"interrupted" | 
/**  The device has no connection. */
"offline" | 
/**  Anything else. */
"unexpected";

src/lib/ipc/bindings.ts::GroupBy.source_code:
type GroupBy = 
/**  One plain group. */
"none" | 
/**  One group per Priority. */
"priority" | 
/**  One group per List, the Inbox first. */
"list" | 
/**  One group per Due date (Upcoming). */
"day" | 
/**  Overdue, Today, Tomorrow, the next days, later, and no date. */
"due";

src/lib/ipc/bindings.ts::GroupKey.source_code:
type GroupKey = 
/**  The one group of an ungrouped view. */
{ kind: "plain" } | 
/**  Due before today, on top in Today and Upcoming. */
{ kind: "overdue" } | 
/**  One Priority, 1 to 4 (4 is "No priority"). */
{ kind: "priority"; 
/**  1 to 4. */
priority: number } | 
/**  One List; none is the Inbox. */
{ kind: "list"; 
/**  The List. */
list_id: string | null } | 
/**  One day. */
{ kind: "day"; 
/**  `YYYY-MM-DD`. */
date: string } | 
/**  A slice of time by Due date. */
{ kind: "due"; 
/**  Which. */
bucket: DueBucket } | 
/**  The Inbox's "No date, in a List". */
{ kind: "no_date_in_list" };

src/lib/ipc/bindings.ts::HistoryLine.source_code:
type HistoryLine = {
	/**  When it happened: UTC milliseconds. */
	at: number,
	/**
	 *  What kind of change: `create`, `done`, `skip`, `reopen`, `wont`, `delete`, `restore`,
	 *  `list`, `date`, `time`, `repeat`, `priority`, `title` or `notes`. The UI picks an icon from it.
	 */
	kind: string,
	/**  The readable line. */
	text: string,
};

src/lib/ipc/bindings.ts::Hit.source_code:
type Hit = {
	/**  The Entry's id. */
	id: string,
	/**  The Page it sits on, `YYYY-MM-DD`. */
	page_date: string,
	/**  When it was written: UTC milliseconds. */
	written_at: number,
	/**  UTC offset in minutes where it was written. */
	written_offset_min: number,
	/**  IANA zone where it was written. */
	written_tz: string,
	/**  A window of its text with the matches marked. */
	snippet: Span[],
};

src/lib/ipc/bindings.ts::InboxView.source_code:
type InboxView = {
	/**  How the Tasks with no List are grouped (a Preference). */
	group_by: GroupBy,
	/**  How they sort inside each group (a Preference). */
	sort: TaskSort,
	/**  Groups of Tasks with no List, then "No date, in a List" when there are such Tasks. */
	groups: TaskGroup[],
};

src/lib/ipc/bindings.ts::JournalEntryDel.source_code:
type JournalEntryDeletedEvent = {
	/**  The Entry. */
	entry_id: string,
	/**  The Page it was on (an Entry has no title). */
	page_date: string,
	/**  The device that deleted it, when it is a paired one. */
	device: string | null,
};

src/lib/ipc/bindings.ts::KeyState.source_code:
type KeyState = 
/**  The kind does not use a key. */
"not_needed" | 
/**  A key is saved on this device. */
"saved" | 
/**  The kind needs a key and none is saved. */
"missing";

src/lib/ipc/bindings.ts::KnownAddress.source_code:
type KnownAddress = {
	/**  `ip:port`. */
	address: string,
	/**  When connecting to it last worked: UTC milliseconds; `None` if only heard of. */
	last_ok_at: number | null,
};

src/lib/ipc/bindings.ts::LastSynced.source_code:
type LastSynced = {
	/**  The device it was with. */
	device: string,
	/**  When: UTC milliseconds. */
	at: number,
};

src/lib/ipc/bindings.ts::ListDeletion.source_code:
type ListDeletion = {
	/**  The deleted List. */
	list_id: string,
	/**  Tasks that were deleted with it. */
	deleted_task_ids: string[],
	/**  Tasks that were moved out of it. */
	moved_task_ids: string[],
};

src/lib/ipc/bindings.ts::ListDone.source_code:
type ListDone = {
	/**  The Preference in force. */
	mode: DoneInLists,
	/**  Struck through at the bottom: done today, or everything with "All shown". Newest first. */
	shown: Task[],
	/**  Behind a fold: "Done earlier · N", or "Done · N" with "All folded". Newest first. */
	folded: Task[],
};

src/lib/ipc/bindings.ts::ListEntry.source_code:
type ListEntry = {
	/**  The List. */
	list: TodoList,
	/**  Open Tasks in it. */
	open_count: number,
	/**  Every Task in it, done ones too: what deleting the List has to deal with. */
	task_count: number,
};

src/lib/ipc/bindings.ts::ListSort.source_code:
type ListSort = 
/**  The drag order. */
"manual" | 
/**  Name, A to Z. */
"name_asc" | 
/**  Name, Z to A. */
"name_desc" | 
/**  Most open Tasks first. */
"most_open" | 
/**  Oldest first. */
"created";

src/lib/ipc/bindings.ts::ListView.source_code:
type ListView = {
	/**  The List, whose `group_by` and `task_sort` the groups follow. */
	list: TodoList,
	/**  Open Tasks: grouped first, sorted inside each group. */
	groups: TaskGroup[],
	/**  Done and Won't do Tasks. */
	done: ListDone,
};

src/lib/ipc/bindings.ts::LocalContext.source_code:
type LocalContext = {
	/**  Today on the device, `YYYY-MM-DD`. */
	today: string,
	/**  Today's weekday in English, such as "Sunday". */
	weekday: string,
	/**  The device's IANA time zone, such as "Europe/London". */
	time_zone: string,
	/**  The first day of the week: `mon` or `sun`. */
	week_start: string,
};

src/lib/ipc/bindings.ts::LocalNow.source_code:
type LocalNow = {
	/**  Today's date, `YYYY-MM-DD`. "Today" ends at midnight, like the Journal's. */
	today: string,
	/**  The time of day, `HH:MM`. */
	now: string,
	/**
	 *  Minutes the device's clock is ahead of UTC. Only needed to tell which Tasks were closed
	 *  today, because closing times are stored in UTC.
	 */
	offset_min: number,
};

src/lib/ipc/bindings.ts::LookAndFeel.source_code:
type LookAndFeel = {
	/**  `system`, `light`, `dark` or `oled`. */
	theme?: string | null,
	/**  `comfortable` or `compact`. */
	density?: string | null,
	/**  `s`, `m` or `l`. */
	text_size?: string | null,
	/**  Turn animations off. */
	reduce_motion?: boolean | null,
	/**  Ids of the phone tab bar's tabs, in order. */
	phone_tabs?: string[] | null,
	/**  The tabs were saved from Settings (an upgrade only pins them). */
	phone_tabs_edited?: boolean | null,
};

src/lib/ipc/bindings.ts::ModelList.source_code:
type ModelList = {
	/**  The matching Model ids, in the Provider's order. */
	models: string[],
	/**
	 *  The ids among `models` that are paid routes (`OpenRouter` only). They can be chosen only
	 *  while the Provider's paid switch is on.
	 */
	paid_models: string[],
	/**  Why the Provider could not be asked, if it could not. */
	failure: Failure | null,
	/**  What to show the person when there is a failure. */
	message: string,
};

src/lib/ipc/bindings.ts::ModelUsage.source_code:
type ModelUsage = {
	/**  The latest uses, newest first. */
	recent: ModelUse[],
	/**  The most used Models, most uses first. */
	most_used: ModelUse[],
};

src/lib/ipc/bindings.ts::ModelUse.source_code:
type ModelUse = {
	/**  The Provider's id. */
	provider_id: string,
	/**  The Provider's name, as it is now. */
	provider_name: string,
	/**  The Model id. */
	model: string,
	/**  How many questions were asked with it on this device. */
	uses: number,
	/**  When it was last used, in milliseconds. */
	last_used_at: number | null,
};

src/lib/ipc/bindings.ts::ModuleVersion.source_code:
type ModuleVersion = {
	/**  The Module's id, e.g. `todo`. */
	module: string,
	/**  How many migrations its data has had. */
	version: number,
};

src/lib/ipc/bindings.ts::NewEntry.source_code:
type NewEntry = {
	/**  The Page to put it on, `YYYY-MM-DD`. Future dates are fine. */
	page_date: string,
	/**  Markdown text. */
	text: string,
	/**  IANA zone of the writer's device. */
	written_tz: string,
	/**  UTC offset in minutes of the writer's device. */
	written_offset_min: number,
	/**  The composer session writing this Entry; groups its autosaves in the change log. */
	session_id: string,
};

src/lib/ipc/bindings.ts::NewProvider.source_code:
type NewProvider = {
	/**  Its kind, chosen first. */
	kind: ProviderKind,
	/**  The name the person gave it. */
	name: string,
	/**  Its address. */
	address: string,
};

src/lib/ipc/bindings.ts::NewTaskDetails.source_code:
type NewTaskDetails = {
	/**  Markdown notes. */
	notes?: string,
	/**  1 to 4; none means 4. */
	priority: number | null,
	/**  A Repeat; it needs the clock of `when` to find its first day. */
	repeat: RepeatRule | null,
	/**  What the parser recognised, as JSON `[{word, kind, value}]`. */
	understood: string | null,
};

src/lib/ipc/bindings.ts::NewWhen.source_code:
type NewWhen = {
	/**  Due date, `YYYY-MM-DD`. */
	date: string | null,
	/**  Due time, `HH:MM`; with no date it means today if still ahead, otherwise tomorrow. */
	time: string | null,
	/**  The device's clock. */
	local: LocalNow,
};

src/lib/ipc/bindings.ts::Older.source_code:
type Older = 
/**  This device: it must be updated. */
"me" | 
/**  The other device: it must be updated. */
"them" | 
/**  Each is older in some Module. */
"both";

src/lib/ipc/bindings.ts::OverdueMove.source_code:
type OverdueMove = {
	/**  The date they were moved to. */
	to_date: string,
	/**  The Tasks moved, with the date and time each had. */
	previous: DueChange[],
};

src/lib/ipc/bindings.ts::Page.source_code:
type Page = {
	/**  `YYYY-MM-DD`. */
	date: string,
	/**  How many Entries the Page holds. */
	entry_count: number,
	/**  Words across all its Entries, for the header summary. */
	word_count: number,
	/**  Entries by written instant, oldest first. */
	entries: Entry[],
};

src/lib/ipc/bindings.ts::PageDirection.source_code:
type PageDirection = 
/**  Pages strictly before the cursor (older). No cursor: the newest Pages. */
"older" | 
/**  The cursor's own Page and older ones: the feed starting AT a date. No cursor: the newest. */
"from" | 
/**  The Pages just after the cursor (newer), nearest first picked; needs a cursor. */
"newer";

src/lib/ipc/bindings.ts::PairingError.source_code:
type PairingError = 
/**
 *  The code typed was wrong. `tries_left` 0 means the code is dead. `name` is the device
 *  showing it.
 */
{ kind: "wrong_code"; 
/**  Tries left on that code. */
tries_left: number; 
/**  The device showing the code. */
name: string } | 
/**  The code ran out of time. On the typing side `name` says where to get a new one. */
{ kind: "code_expired"; 
/**  The device that showed the code, when known. */
name: string | null } | 
/**  The code was typed wrong three times (shown on the device showing it). */
{ kind: "tries_used" } | 
/**  The person on the other device pressed Deny. */
{ kind: "declined"; 
/**  The device that said no. */
name: string } | 
/**  The other device cancelled. */
{ kind: "cancelled"; 
/**  The device that left, when known. */
name: string | null } | 
/**  The other device runs the other Environment (Sandbox with Production). */
{ kind: "different_environment"; 
/**  What the other device is. */
theirs: Environment } | 
/**  The two devices run different data versions. */
{ kind: "version_mismatch"; 
/**  The other device. */
name: string; 
/**  Which of the two must be updated. */
older: Older; 
/**  The Modules this device has older data for (Module ids), when known. */
older_here: string[]; 
/**  The Modules the other device has older data for (Module ids), when known. */
older_there: string[] } | 
/**  Both devices already belong to a group of devices, not the same one. */
{ kind: "different_groups" } | 
/**  No device showing a code was found on the network. */
{ kind: "nothing_nearby" } | 
/**  The other device went away or could not be reached. */
{ kind: "connection_lost" } | 
/**  The typed address is a name that does not resolve (Pair by address). */
{ kind: "address_not_found" } | 
/**  Nothing answered at the typed address in time, or it is not Mnemora (Pair by address). */
{ kind: "address_unreachable" } | 
/**
 *  A database could not be backed up first, so nothing was merged. `name` is the other
 *  device when it was the one that could not; `None` is this device.
 */
{ kind: "backup_failed"; 
/**  The device whose backup failed, when it is not this one. */
name: string | null } | 
/**  The other device is already pairing with someone. */
{ kind: "busy" } | 
/**  Sync is not ready (still starting, or off). */
{ kind: "not_ready" };

src/lib/ipc/bindings.ts::PairingView.source_code:
type PairingView = 
/**  Nothing is happening. */
{ state: "idle" } | 
/**  This device shows a code and waits for the other to type it. */
{ state: "showing"; 
/**  The 8 digits, `"4821 0937"`. */
code: string; 
/**  How long a code lives, in milliseconds (for the ring). */
life_ms: number; 
/**  How long this one has left. */
left_ms: number; 
/**  Wrong tries left before the code dies. */
tries_left: number; 
/**  Other devices can find this one (Visible on this network is on). */
discoverable: boolean; 
/**  The last attempt that failed for another reason than a wrong code. */
notice: PairingError | null } | 
/**  The right code was typed: Allow or Deny. */
{ state: "asking"; 
/**  The device that wants to pair. */
name: string; 
/**  Its kind. */
platform: Platform; 
/**  Length of the whole window, in milliseconds. */
life_ms: number; 
/**  What is left of it. */
left_ms: number } | 
/**  This device typed the code and is looking for the device that shows it. */
{ state: "searching" } | 
/**  The code was right; waiting for the person on the other device to Allow. */
{ state: "waiting"; 
/**  The device being waited for. */
name: string } | 
/**  Both devices have data: the typing device shows what will be combined and asks. */
{ state: "preview"; 
/**  The other device. */
name: string; 
/**  Its kind. */
platform: Platform; 
/**  What the other device holds. */
there: Counts; 
/**  What this device holds. */
here: Counts; 
/**  The Lists that will combine into one, by this device's spelling. */
combine: string[] } | 
/**  The showing device, while the typing device decides on the merge preview. */
{ state: "confirming"; 
/**  The device being waited for. */
name: string } | 
/**  Allowed here; recording the pairing and telling the other device. */
{ state: "finishing"; 
/**  The device being paired. */
name: string } | 
/**  Done. */
{ state: "paired"; 
/**  The other device's name here (may differ from its own if names clashed). */
name: string; 
/**  Its kind. */
platform: Platform; 
/**  The name was changed to keep names unique. */
renamed: boolean; 
/**  Devices of its group that came along. */
also_joined: string[] } | 
/**  It did not work. */
{ state: "failed"; 
/**  Why. */
error: PairingError };

src/lib/ipc/bindings.ts::ParseAlternativ.source_code:
type ParseAlternative = {
	/**  Why it lost: `conflict` (a later one of the same kind won). */
	reason: string,
} & ParseSpan;

src/lib/ipc/bindings.ts::ParseRequest.source_code:
type ParseRequest = {
	/**  The typed text. */
	text: string,
	/**  Keys of words the user keeps as text. */
	ignored?: string[],
	/**  Per kind, the key of the word the user picked over the last one ("use instead"). */
	prefer?: { [key in string]: string },
	/**  Stretches already read before (Quick edit's old title): candidates inside them are dropped. */
	frozen?: TextRange[],
	/**  Today, `YYYY-MM-DD`. */
	today: string,
	/**  The time of day, `HH:MM`. */
	now: string,
	/**  `mon` or `sun`: the first day of the week, which "next week" and "next fri" count from. */
	week_start: string,
};

src/lib/ipc/bindings.ts::ParseSpan.source_code:
type ParseSpan = {
	/**  Names the word across parses: `kind:word:n` for the nth such word in the text. */
	key: string,
	/**  `date`, `time`, `repeat`, `prio` or `list`. */
	kind: string,
	/**  Where it starts in the text. */
	start: number,
	/**  Where it ends. */
	end: number,
	/**  The words as typed. */
	word: string,
	/**
	 *  The meaning: a `YYYY-MM-DD` date, an `HH:MM` time, the Repeat as JSON, a Priority number
	 *  or a List's name.
	 */
	value: string,
	/**  A List that does not exist yet and is created when the Task is added. */
	new_list: boolean,
};

src/lib/ipc/bindings.ts::Parsed.source_code:
type Parsed = {
	/**  The words that won, first to last. */
	spans: ParseSpan[],
	/**  The words that lost. */
	alternatives: ParseAlternative[],
	/**  The words the user keeps as text, which would have been read. */
	ignored: ParseSpan[],
	/**  The Due date: a date word, or today/tomorrow for a time alone. */
	date: string | null,
	/**  The Due time. */
	time: string | null,
	/**  The Repeat. */
	repeat: RepeatRule | null,
	/**  1 to 4. */
	priority: number | null,
	/**  The List a `#Name` matched. */
	list_id: string | null,
	/**  A `#Name` that matched nothing: the List to create. */
	new_list: string | null,
};

src/lib/ipc/bindings.ts::Pause.source_code:
type Pause = 
/**  The Modules' data versions differ. A Module absent on one side counts as older there. */
{ kind: "update"; 
/**  Modules whose data is older on this device. */
older_here: string[]; 
/**  Modules whose data is older on the other device. */
older_there: string[] } | 
/**
 *  The clocks agree now, but records were stamped by a clock that was ahead (the other
 *  device's, or one it relays): they are refused until real time is within five minutes of
 *  them. Fixing the clock does not shorten it.
 */
{ kind: "stamped"; 
/**  How long until the newest of them is allowed, in milliseconds. */
resumes_in_ms: number } | 
/**  One clock is more than five minutes ahead of the other. */
{ kind: "clock"; 
/**  By how much, in milliseconds. */
ahead_ms: number; 
/**  Whether it is this device's clock that is ahead. */
here: boolean };

src/lib/ipc/bindings.ts::PeerRow.source_code:
type PeerRow = {
	/**  Its device id. */
	id: string,
	/**  Its name here. */
	name: string,
	/**  Its kind. */
	platform: Platform,
	/**  When it was paired: UTC milliseconds. */
	paired_at: number,
	/**  Where it stands now. */
	state: PeerState,
	/**  When it was last reached: UTC milliseconds. */
	last_seen_at: number | null,
	/**  When a session with it last finished. */
	last_synced_at: number | null,
	/**  Changes the last session that moved anything received from it. */
	last_in: number | null,
	/**  Changes that session sent to it. */
	last_out: number | null,
	/**  How it was reached the last time. */
	route: Route | null,
	/**  How far the running session has got. */
	progress: Progress | null,
	/**  Why sync with it is paused; set exactly while `state` is `Paused`. */
	pause: Pause | null,
};

src/lib/ipc/bindings.ts::PeerState.source_code:
type PeerState = 
/**  Connected and nothing left to exchange. */
"up_to_date" | 
/**  A session is running. */
"syncing" | 
/**  Not reachable right now. */
"not_nearby" | 
/**  Not reachable on purpose: this phone is on mobile data and "Allow over mobile data" is off. */
"paused_on_mobile_data" | 
/**
 *  Not reachable because the system keeps this device off the local network (macOS Local
 *  Network privacy, Android's local network permission).
 */
"blocked_by_local_network" | 
/**  Sync with it is paused (its data version or clock differs). */
"paused" | 
/**  It was forgotten group-wide (#69). */
"removed";

src/lib/ipc/bindings.ts::Piece.source_code:
type Piece = {
	/**  The words. */
	text: string,
	/**  Shown bold (a device or List name). */
	strong: boolean,
};

src/lib/ipc/bindings.ts::Platform.source_code:
type Platform = 
/**  A computer. */
"desktop" | 
/**  A phone. */
"phone";

src/lib/ipc/bindings.ts::Progress.source_code:
type Progress = {
	/**  Changes moved so far, in either direction. */
	done: number,
	/**  Changes the session will move. */
	total: number,
};

src/lib/ipc/bindings.ts::ProviderUpdate.source_code:
type ProviderUpdate = {
	/**  The new name. */
	name: string,
	/**  The new address. */
	address: string,
	/**  Whether paid Models may be chosen and sent (ignored unless the kind has paid Models). */
	allow_paid?: boolean,
};

src/lib/ipc/bindings.ts::ProviderView.source_code:
type ProviderView = {
	/**  The Provider's id. */
	id: string,
	/**  The name the person gave it. */
	name: string,
	/**  Its kind. */
	kind: ProviderKind,
	/**  Its address. */
	address: string,
	/**  Whether a key is needed and saved. */
	key_state: KeyState,
	/**  When it was added, in milliseconds. */
	created_at: number | null,
	/**  When it last changed, in milliseconds. */
	updated_at: number | null,
	/**  Whether paid Models may be chosen and sent. */
	allow_paid: boolean,
};

src/lib/ipc/bindings.ts::QueuedNote.source_code:
type QueuedNote = {
	/**  The note's id, for removing or sending it now. */
	id: string,
	/**  The note as typed. */
	text: string,
};

src/lib/ipc/bindings.ts::QuickEdit.source_code:
type QuickEdit = {
	/**  The title as typed. */
	title: string,
	/**  What the parser recognised in it, as JSON. */
	understood: string | null,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`. */
	due_time: string | null,
	/**  The Repeat after the edit. */
	repeat: RepeatRule | null,
	/**  1 to 4. */
	priority: number,
	/**  The List, or none for the Inbox. */
	list_id: string | null,
};

src/lib/ipc/bindings.ts::RepeatRule.source_code:
type RepeatRule = {
	/**  `day`, `week`, `month` or `year`. */
	freq: string,
	/**  The interval, 1 to 99. */
	every: number,
	/**
	 *  Weeks: a bitmask of the weekdays (Sunday is bit 0), none meaning the Due date's own
	 *  weekday. Months and years: the day of the month the Repeat keeps to (31 clamps to the
	 *  last day of a short month and comes back), set from the Due date.
	 */
	days: number | null,
	/**  `fixed` (from the Due date) or `after` (from the day it was done). */
	mode: string,
};

src/lib/ipc/bindings.ts::ResolvedIcon.source_code:
type ResolvedIcon = 
/**  Priority. */
"flag" | 
/**  A date or time. */
"calendar" | 
/**  A List. */
"list" | 
/**  A state. */
"check" | 
/**  Something deleted. */
"trash" | 
/**  A text. */
"text" | 
/**  Order and Preferences. */
"order" | 
/**  The Inbox. */
"inbox" | 
/**  Anything else. */
"other";

src/lib/ipc/bindings.ts::ResolvedKind.source_code:
type ResolvedKind = 
/**  A value two devices changed; the newest took. */
"value" | 
/**  A record deleted on one device and edited on another. */
"delete_edit" | 
/**  A Task put in the Inbox because its List is gone. */
"task_inbox" | 
/**  A text clash on a record that is deleted. */
"conflict_deleted" | 
/**  Order and Preference changes folded into one line. */
"order_prefs";

src/lib/ipc/bindings.ts::ResolvedRow.source_code:
type ResolvedRow = {
	/**  The row's id. */
	id: string,
	/**  What kind of decision it is. */
	kind: ResolvedKind,
	/**  The Module it belongs to for the row's tint: `journal`, `todo` or `sync`. */
	module: string,
	/**  Its icon. */
	icon: ResolvedIcon,
	/**  "‘Water plants’ · Priority". */
	title: string,
	/**  "P1 (Mac) kept · P2 (Pixel 8) replaced". */
	detail: string,
	/**  When it was decided: UTC milliseconds. Rows group by this day. */
	at: number,
	/**  This device learned of it since the person last looked. */
	fresh: boolean,
	/**  The button: "Use P2 instead". None when nothing can be changed back or it was done. */
	action: string | null,
	/**  After the button was used: "Changed to P2". */
	used: string | null,
	/**  For the folded line, what "Show" lists. */
	changes: string[],
};

src/lib/ipc/bindings.ts::RetryRequest.source_code:
type RetryRequest = {
	/**  The Conversation the question is in. */
	conversation_id: string,
	/**  The question to try again. */
	entry_id: string,
	/**  The Provider that answers. */
	provider_id: string,
	/**  The Model id it is asked for. */
	model: string,
	/**  The person's calendar, for the Model. */
	local: LocalContext,
};

src/lib/ipc/bindings.ts::Route.source_code:
type Route = 
/**  Over the local network. */
"wifi" | 
/**  Over Tailscale. */
"tailscale";

src/lib/ipc/bindings.ts::RunEvent.source_code:
type RunEvent = 
/**  The Run began. */
{ type: "runStarted" } | 
/**  An entry was written. */
{ type: "entrySaved"; 
/**  The entry's id. */
entry_id: string; 
/**  Who wrote it. */
kind: EntryKind } | 
/**  The Model is asked. */
{ type: "stepStarted" } | 
/**  A piece of the answer. */
{ type: "textDelta"; 
/**  The text, as streamed. */
text: string } | 
/**  A Tool call is running. */
{ type: "toolStarted"; 
/**  The call's id. */
call_id: string; 
/**  The Tool's name. */
name: string } | 
/**  A Tool call finished. */
{ type: "toolEnded"; 
/**  The call's id. */
call_id: string; 
/**  The Tool's name. */
name: string; 
/**  The plain line the activity shows. */
summary: string; 
/**  Whether the call was refused. */
is_error: boolean } | 
/**
 *  The notes waiting to be sent to the Model changed. The last one sent after a Run ends
 *  lists the notes that were never sent, so the person can still send them.
 */
{ type: "queueChanged"; 
/**  The notes waiting, in the order they will be sent. */
notes: QueuedNote[] } | 
/**  The Run is over. */
{ type: "runEnded"; 
/**  How it ended. */
outcome: RunOutcome };

src/lib/ipc/bindings.ts::RunOutcome.source_code:
type RunOutcome = 
/**  The answer was saved. */
{ type: "answered" } | 
/**  The person stopped the Run. What was written before is saved, marked as stopped. */
{ type: "stopped" } | 
/**  No answer was saved. `message` is one plain sentence; the raw Provider error is never kept. */
{ type: "failed"; 
/**  Why. */
kind: Failure; 
/**  What the person should read. */
message: string };

src/lib/ipc/bindings.ts::RunRequest.source_code:
type RunRequest = {
	/**  The Conversation to continue, or none to start one. */
	conversation_id: string | null,
	/**  The question as typed. */
	text: string,
	/**  The Provider that answers. */
	provider_id: string,
	/**  The Model id it is asked for. */
	model: string,
	/**  The person's calendar, for the Model. */
	local: LocalContext,
	/**
	 *  The question this one is a sibling of (Edit): it follows what that question followed. None
	 *  continues the Branch the Conversation shows. Needs a Conversation.
	 */
	branch_of: string | null,
};

src/lib/ipc/bindings.ts::RunStarted.source_code:
type RunStarted = {
	/**  The Run's id: every event of this Run carries it. */
	run_id: string,
	/**  The Conversation the question went into. */
	conversation_id: string,
};

src/lib/ipc/bindings.ts::SavedQuestion.source_code:
type SavedQuestion = {
	/**  The Saved question's id. */
	id: string,
	/**  The question as it is asked. */
	text: string,
};

src/lib/ipc/bindings.ts::SearchResults.source_code:
type SearchResults = {
	/**  Entries that match every word and phrase, newest first. */
	exact: Hit[],
	/**  Entries that match only when a word is allowed a typo; never also in `exact`. */
	similar: Hit[],
	/**  Whether `exact` was cut short at the limit. */
	truncated: boolean,
	/**  Whether `similar` was cut short at the limit. */
	similar_truncated: boolean,
};

src/lib/ipc/bindings.ts::SettingSchema.source_code:
type SettingSchema = {
	/**  Full key, `module.key`. */
	key: string,
	/**  Owning Module id. */
	module: string,
	/**  Default value. */
	default: JsonValue,
};

src/lib/ipc/bindings.ts::SettingsChange.source_code:
type SettingsChange = {
	/**  Full key, `module.key`. */
	key: string,
	/**  New value. */
	value: JsonValue,
};

src/lib/ipc/bindings.ts::SettingsChanged.source_code:
type SettingsChanged = {
	/**  Owning Module id, e.g. `core`. */
	module: string,
	/**  Keys within that Module (without the module prefix). */
	keys: string[],
};

src/lib/ipc/bindings.ts::SettingsSnapsho.source_code:
type SettingsSnapshot = {
	/**  Current value of every registered key (defaults filled in). */
	values: { [key in string]: JsonValue },
	/**  Registered keys with their defaults. */
	schema: SettingSchema[],
};

src/lib/ipc/bindings.ts::SidebarState.source_code:
type SidebarState = {
	/**  Expanded width in pixels (200 to 360). */
	width?: number,
	/**  Collapsed to the icon rail. */
	rail?: boolean,
	/**
	 *  The Todo views and Lists under "Todo" are unfolded. Entering and leaving Todo set it;
	 *  clicking the Todo row or its chevron flips it; it is restored as left. None: never chosen,
	 *  so the tree follows the page (unfolded when the app opens in Todo).
	 */
	todo_open?: boolean | null,
};

src/lib/ipc/bindings.ts::SidebarView.source_code:
type SidebarView = {
	/**  Open Tasks with no List. */
	inbox_count: number,
	/**  Open Tasks due today, plus every Overdue one: Today's count. */
	today_count: number,
	/**  Open Tasks due before today: the Today count turns red while this is above zero. */
	overdue_count: number,
	/**  Lists in the order the sort says; dragging them is off unless this is Manual. */
	lists: ListEntry[],
	/**  How the Lists are sorted (a Preference). */
	lists_sort: ListSort,
};

src/lib/ipc/bindings.ts::SnippetSource.source_code:
type SnippetSource = 
/**  A line of the Task's notes. */
"notes" | 
/**  A Comment. */
"comment";

src/lib/ipc/bindings.ts::Source.source_code:
type Source = {
	/**  The Entry's or Task's id. */
	id: string,
	/**  The Module it belongs to, `journal` or `todo`. */
	module: string,
	/**  A label the person recognises it by. */
	title: string,
	/**  Its date (a Page date or a due date), when it has one. */
	date: string | null,
};

src/lib/ipc/bindings.ts::Span.source_code:
type Span = {
	/**  The text, with whitespace collapsed to single spaces. */
	text: string,
	/**  Whether it matched the search. */
	matched: boolean,
};

src/lib/ipc/bindings.ts::StopReason.source_code:
type StopReason = 
/**  The Model finished its reply. */
"stop" | 
/**  The reply hit the Model's output limit. */
"length" | 
/**
 *  The Step was stopped (or its Tools skipped) before the reply finished. What came so far is
 *  kept, and no Tool call in it runs.
 */
"aborted";

src/lib/ipc/bindings.ts::SyncDevice.source_code:
type SyncDevice = {
	/**  Sync is on. Off (the default) means nothing runs: no listener, no discovery, no tasks. */
	enabled?: boolean,
	/**  What the other devices call this one; `None` until Sync is first turned on. */
	name?: string | null,
	/**  Sync when devices are around and after changes. Off: only "Sync now". */
	automatic?: boolean,
	/**  Phone only: reach devices over Tailscale away from Wi-Fi. */
	mobile_data?: boolean,
	/**  Advertise on the local network so paired devices find this one. */
	visible?: boolean,
	/**
	 *  "New conflicts: Show a toast" instead of Quietly (the default): per device, so the Mac can
	 *  say so at once while the phone stays calm.
	 */
	toast_conflicts?: boolean,
};

src/lib/ipc/bindings.ts::SyncNewConflict.source_code:
type SyncNewConflictsEvent = {
	/**  How many. */
	count: number,
	/**  The device they came from, when known. */
	device: string | null,
};

src/lib/ipc/bindings.ts::SyncOption.source_code:
type SyncOption = 
/**  Sync automatically. */
"automatic" | 
/**  Allow over mobile data. */
"mobile_data" | 
/**  Visible on this network. */
"visible" | 
/**  "New conflicts: Show a toast" (off is Quietly). */
"toast_conflicts";

src/lib/ipc/bindings.ts::SyncState.source_code:
type SyncState = {
	/**  Sync is on for this device. */
	enabled: boolean,
	/**  This device's name; before it is first chosen, the one that would be prefilled. */
	name: string,
	/**  Sync on discovery and after changes. */
	automatic: boolean,
	/**  Phone: allow reaching devices away from Wi-Fi. */
	mobile_data: boolean,
	/**  Advertise on the local network. */
	visible: boolean,
	/**  Show a toast when a new conflict arrives (the other choice is Quietly). */
	toast_conflicts: boolean,
	/**  Other devices this one is paired with. */
	paired_devices: number,
};

src/lib/ipc/bindings.ts::Task.source_code:
type Task = {
	/**  `UUIDv7`. */
	id: string,
	/**  The List it belongs to; none means the Inbox. */
	list_id: string | null,
	/**  One line, up to 500 characters. */
	title: string,
	/**  Markdown notes. */
	notes: string,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`, floating local. */
	due_time: string | null,
	/**  Repeat unit: `day`, `week`, `month` or `year`. */
	repeat_freq: string | null,
	/**  Repeat interval, 1 to 99. */
	repeat_every: number | null,
	/**  Weekday bitmask for weekly Repeats. */
	repeat_days: number | null,
	/**  `fixed` (from the Due date) or `after` (from the day it was done). */
	repeat_mode: string | null,
	/**  1 (highest) to 4 (none). */
	priority: number,
	/**  Open, done or Won't do. */
	state: TaskState,
	/**  When it was done or marked Won't do: UTC milliseconds. */
	closed_at: number | null,
	/**  For an occurrence copy, the Task it was made from. */
	repeat_of: string | null,
	/**  What the natural-language parser recognised, as JSON. */
	understood: string | null,
	/**  Text that sorts bytewise into the manual order, shared by every Task. */
	sort_key: string,
	/**  Row creation time: UTC milliseconds. */
	created_at: number,
	/**  Row update time: UTC milliseconds. */
	updated_at: number,
	/**
	 *  How many live Comments it has: counted when read, never stored (and left out of the
	 *  change-log snapshot).
	 */
	comment_count: number,
};

src/lib/ipc/bindings.ts::TaskGroup.source_code:
type TaskGroup = {
	/**  Which group. */
	key: GroupKey,
	/**
	 *  The properties a Task dropped here adopts, in `todo_task_reorder`'s terms: a day sets the
	 *  date, a Priority sets the Priority, a List moves it. Overdue adopts nothing: dragging
	 *  among Overdue Tasks only reorders.
	 */
	adopt: GroupKey[],
	/**  Its Tasks, sorted. */
	tasks: Task[],
};

src/lib/ipc/bindings.ts::TaskHit.source_code:
type TaskHit = {
	/**  The Task, as every list shows it. */
	task: Task,
	/**  Its title cut into plain and matched runs, for highlighting. */
	title: Span[],
	/**
	 *  The note or Comment line that matched, with the matches marked; empty when only the title
	 *  matched.
	 */
	snippet: Span[],
	/**  Where `snippet` came from. */
	snippet_source: SnippetSource | null,
};

src/lib/ipc/bindings.ts::TaskSearchResul.source_code:
type TaskSearchResults = {
	/**  Tasks that match every word and phrase. */
