function titleMatches(title: string, query: string): boolean {
  const fold = (text: string) =>
    text
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase();
  const needle = fold(query.trim());
  return needle === '' || fold(title).includes(needle);
}

