function validDate(date: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;
  const [y = 0, m = 1, d = 1] = date.split('-').map(Number);
  const probe = new Date(Date.UTC(y, m - 1, d));
  return (
    y >= 1 &&
    probe.getUTCFullYear() === y &&
    probe.getUTCMonth() === m - 1 &&
    probe.getUTCDate() === d
  );
}

