function stripLinePrefix(line: string): string {
  return line
    .trimStart()
    .replace(/^(>\s*)+/, '')
    .replace(/^#+\s*/, '')
    .replace(/^([-*+]|\d+[.)])\s+/, '')
    .replace(/^\[[ xX]\]\s+/, '');
}

src/lib/ipc/mock-journal.ts::wordCount.source_code:
function wordCount(text: string): number {
  return text
    .split('\n')
    .flatMap((line) =>
      stripLinePrefix(line)
        .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
        .replace(STYLE_MARKS, ' ')
        .split(/\s+/),
    )
    .filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
}

src/lib/ipc/mock-journal.ts::shorten.source_code:
function shorten(text: string): string {
  const chars = [...text];
  if (chars.length <= TODAY_SNIPPET_CHARS) return text;
  let end = TODAY_SNIPPET_CHARS;
  while (end > 0 && chars[end] !== ' ') end--;
  if (end === 0) end = TODAY_SNIPPET_CHARS;
  return `${chars.slice(0, end).join('').trimEnd()}…`;
}

