function createJournalMock(seed = false, flags: JournalMockFlags = { failUpdate: false }) {
  const all: Entry[] = seed ? seedJournalEntries(new Date(), mockId) : [];
  /** id -> when it was deleted. Deleted Entries stay in `all` so a restore keeps their place. */
  const deleted = new Map<string, number>();
  const live = () => all.filter((e) => !deleted.has(e.id));
  const find = (id: unknown) => live().find((e) => e.id === id);
  const missing = () => fail('not_found', 'That Entry no longer exists');
  /** Entries an editor holds (Rust: `editing_hold` with scope `*`), and the text waiting for them. */
  const held = new Set<string>();
  const waiting = new Map<string, string>();
  /** The text an Entry had when a change for it first had to wait: what the person went on typing from. */
  const bases = new Map<string, string>();
  const wait = (entry: Entry, text: string) => {
    if (!waiting.has(entry.id)) bases.set(entry.id, entry.body);
    waiting.set(entry.id, text);
  };

  const edit = (entry: Entry, text: string) => {
    const now = Date.now();
    entry.body = text;
    entry.word_count = wordCount(text);
    entry.updated_at = now;
    if (now - entry.written_at > EDIT_GRACE_MS) entry.edited_at = now;
  };

  return {
    /** Set by the IPC mock: tells the UI that Journal data changed behind its back. */
    onRemoteChange: undefined as (() => void) | undefined,
    /**
     * Set by the IPC mock: a held change and the person's own typing clashed when the editor let
     * go. The typing shows (it is the newer); the Conflict keeps the other text, as in Rust.
     */
    onHeldClash: undefined as
      | ((c: { entry: Entry; base: string; showing: string; other: string }) => void)
      | undefined,

    handles: (cmd: string) => cmd.startsWith('journal_') || cmd.startsWith('editing_'),

    /**
     * Another device editing an Entry (the Entry `id`, else the newest one on screen). An Entry
     * an editor holds keeps its text until the editor lets go, as in Rust. True when the Entry's
     * text changed now, so the caller refreshes the Journal's views.
     */
    simulateRemoteEdit(text: string, id?: string): boolean {
      const entry = id ? find(id) : live().sort((x, y) => y.written_at - x.written_at)[0];
      if (!entry) return false;
      if (held.has(entry.id)) {
        wait(entry, text);
        return false;
      }
      edit(entry, text);
      return true;
    },

    /** Sync's view of the Entries (mock-sync-merge.ts), deleted ones too. A browser-only seam. */
    exportDocs(): Doc[] {
      return all.map((e) => ({
        entity: 'entry' as const,
        id: e.id,
        values: {
          body: e.body,
          page_date: e.page_date,
          written_at: e.written_at,
          written_offset_min: e.written_offset_min,
          written_tz: e.written_tz,
          created_at: e.created_at,
          deleted_at: deleted.get(e.id) ?? null,
        },
      }));
    },

    /** Takes in what a sync merged; an Entry an editor holds waits for it to let go. True when anything changed now. */
    importDocs(docs: Doc[]): boolean {
      let changed = false;
      for (const d of docs.filter((x) => x.entity === 'entry')) {
        const v = d.values;
        let entry = all.find((e) => e.id === d.id);
        if (!entry) {
          const now = Date.now();
          entry = {
            id: d.id,
            page_date: String(v.page_date),
            body: '',
            written_at: Number(v.written_at),
            written_offset_min: Number(v.written_offset_min),
            written_tz: String(v.written_tz),
            edited_at: null,
            word_count: 0,
            created_at: Number(v.created_at),
            updated_at: now,
          };
          all.push(entry);
          edit(entry, String(v.body));
          entry.edited_at = null;
          changed = true;
        } else if (entry.body !== v.body) {
          if (held.has(entry.id)) wait(entry, String(v.body));
          else {
            edit(entry, String(v.body));
            changed = true;
          }
        }
        const gone = v.deleted_at ?? null;
        if (gone === null && deleted.delete(d.id)) changed = true;
        if (gone !== null && !deleted.has(d.id)) {
          deleted.set(d.id, Number(gone));
          changed = true;
        }
      }
      return changed;
    },

    handle(cmd: string, a: Record<string, unknown>): unknown {
      switch (cmd) {
        case 'editing_hold':
          if (a.entity === 'journal_entry') held.add(a.entityId as string);
          return null;
        case 'editing_release': {
          const id = a.entityId as string;
          held.delete(id);
          const text = waiting.get(id);
          const base = bases.get(id);
          waiting.delete(id);
          bases.delete(id);
          const entry = find(id);
          if (text !== undefined && entry) {
            // Rust (held.rs, texts.rs): the text is the three-way merge of what waited and what the
            // person typed since. They typed after it arrived, so on a clash their words show.
            const typed = entry.body;
            const merged =
              base === undefined || typed === base ? text : textOf(textMerge(base, text, typed));
            if (merged !== entry.body) {
              edit(entry, merged);
              this.onRemoteChange?.();
            }
            if (base !== undefined && typed !== base && merged !== text && typed !== text)
              if (textMerge(base, text, typed).some((p) => 'clash' in p))
                this.onHeldClash?.({ entry, base, showing: merged, other: text });
          }
          return null;
        }
        case 'journal_entry_create': {
          const n = a.entry as NewEntry;
          if (!n.text.trim()) throw fail('validation', "An Entry can't be blank");
          if (!validDate(n.page_date)) throw fail('validation', 'Not a valid date');
          if (!n.written_tz.trim() || [...n.written_tz].length > MAX_ZONE_CHARS) {
            throw fail('validation', 'Not a valid time zone');
          }
          if (Math.abs(n.written_offset_min) > MAX_OFFSET_MIN) {
            throw fail('validation', 'Not a valid time zone offset');
          }
          const now = Date.now();
          const entry: Entry = {
            id: mockId(),
            page_date: n.page_date,
            body: n.text,
            written_at: now,
            written_offset_min: n.written_offset_min,
            written_tz: n.written_tz,
            edited_at: null,
            word_count: wordCount(n.text),
            created_at: now,
            updated_at: now,
          };
          all.push(entry);
          return copy(entry);
        }
        case 'journal_entry_update': {
          if (flags.failUpdate) {
            throw {
              ...fail('database', 'Could not save the entry'),
              details: 'mock: simulated save failure',
            };
          }
          const text = a.text as string;
          if (!text.trim()) throw fail('validation', "An Entry can't be blank");
          const entry = find(a.id);
          if (!entry) throw missing();
          const now = Date.now();
          entry.body = text;
          entry.word_count = wordCount(text);
          entry.updated_at = now;
          // The last edit: moves on every update past 10 minutes after it was written.
          if (now - entry.written_at > EDIT_GRACE_MS) entry.edited_at = now;
          return copy(entry);
        }
        case 'journal_entry_toggle_task': {
          const entry = find(a.id);
          if (!entry) throw missing();
          const body = toggleTaskLine(entry.body, a.line as number);
          if (body === null) throw fail('validation', 'That line is not a checklist item');
          entry.body = body;
          entry.updated_at = Date.now();
          return copy(entry);
        }
        case 'journal_entry_move': {
          const pageDate = a.pageDate as string;
          if (!validDate(pageDate)) throw fail('validation', 'Not a valid date');
          const entry = find(a.id);
          if (!entry) throw missing();
          if (entry.page_date !== pageDate) {
            entry.page_date = pageDate;
            entry.updated_at = Date.now();
          }
          return copy(entry);
        }
        case 'journal_month_days': {
          const year = a.year as number;
          const month = a.month as number;
          if (!(year >= 1 && year <= 9999) || !(month >= 1 && month <= 12)) {
            throw fail('validation', 'Not a valid month');
          }
          const prefix = `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-`;
          return [
            ...new Set(
              live()
                .filter((e) => e.page_date.startsWith(prefix))
                .map((e) => e.page_date),
            ),
          ].sort();
        }
        case 'journal_entry_delete': {
          const entry = find(a.id);
          if (!entry) throw missing();
          const now = Date.now();
          entry.updated_at = now;
          deleted.set(entry.id, now);
          return null;
        }
        case 'journal_entry_restore': {
          const entry = all.find((e) => e.id === a.id && deleted.has(e.id));
          if (!entry) throw missing();
          deleted.delete(entry.id);
          entry.updated_at = Date.now();
          return copy(entry);
        }
        case 'journal_today': {
          const date = a.today as string;
          if (!validDate(date)) throw fail('validation', 'Not a valid date');
          const day = live().filter((e) => e.page_date === date);
          const last = day.reduce<Entry | null>(
            (best, e) => (best === null || e.written_at >= best.written_at ? e : best),
            null,
          );
          return copy({
            count: day.length,
            latest: last && {
              id: last.id,
              written_at: last.written_at,
              written_offset_min: last.written_offset_min,
              written_tz: last.written_tz,
              snippet: shorten(plainText(last.body)),
            },
          });
        }
        case 'journal_search':
          return copy(
            searchEntries(
              live(),
              a.query as string,
              a.from as string | null,
              a.to as string | null,
            ),
          );
        case 'journal_pages': {
          if (flags.failPages) {
            throw {
              ...fail('database', 'Could not read the Journal'),
              details: 'mock: simulated load failure',
            };
          }
          const cursor = a.cursor as string | null;
          if (cursor !== null && !validDate(cursor)) throw fail('validation', 'Not a valid date');
          const limit = Math.min(MAX_PAGES, Math.max(1, a.limit as number));
          const entries = live();
          const dates = pageDates(
            entries.map((e) => e.page_date),
            cursor,
            a.direction as PageDirection,
            limit,
          );
          if (dates === null) throw fail('validation', 'Newer Pages need a date to start from');
          const pages: Page[] = dates.map((date) => {
            const list = entries
              .filter((e) => e.page_date === date)
              .sort((x, y) => x.written_at - y.written_at);
            return {
              date,
              entry_count: list.length,
              word_count: list.reduce((n, e) => n + e.word_count, 0),
              entries: list,
            };
          });
          return copy(pages);
        }
        default:
          return undefined;
      }
    },
  };
}

src/lib/ipc/mock-occurrence.ts::sha1.source_code:
function sha1(bytes: Uint8Array): Uint8Array {
  const words = new Uint32Array((((bytes.length + 8) >> 6) + 1) * 16);
  for (let i = 0; i < bytes.length; i++)
    words[i >> 2] = (words[i >> 2] as number) | ((bytes[i] as number) << (24 - 8 * (i & 3)));
  words[bytes.length >> 2] =
    (words[bytes.length >> 2] as number) | (0x80 << (24 - 8 * (bytes.length & 3)));
  words[words.length - 1] = (bytes.length * 8) >>> 0;
  words[words.length - 2] = Math.floor((bytes.length * 8) / 2 ** 32);
  const h = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];
  const w = new Uint32Array(80);
  const rotl = (x: number, n: number) => ((x << n) | (x >>> (32 - n))) >>> 0;
  for (let block = 0; block < words.length; block += 16) {
    for (let i = 0; i < 16; i++) w[i] = words[block + i] as number;
    for (let i = 16; i < 80; i++)
      w[i] = rotl(
        (w[i - 3] as number) ^ (w[i - 8] as number) ^ (w[i - 14] as number) ^ (w[i - 16] as number),
        1,
      );
    let [a, b, c, d, e] = h as [number, number, number, number, number];
    for (let i = 0; i < 80; i++) {
      const [f, k] =
        i < 20
          ? [(b & c) | (~b & d), 0x5a827999]
          : i < 40
            ? [b ^ c ^ d, 0x6ed9eba1]
            : i < 60
              ? [(b & c) | (b & d) | (c & d), 0x8f1bbcdc]
              : [b ^ c ^ d, 0xca62c1d6];
      const next = (rotl(a, 5) + (f as number) + e + (k as number) + (w[i] as number)) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = next;
    }
    h[0] = ((h[0] as number) + a) >>> 0;
    h[1] = ((h[1] as number) + b) >>> 0;
    h[2] = ((h[2] as number) + c) >>> 0;
    h[3] = ((h[3] as number) + d) >>> 0;
    h[4] = ((h[4] as number) + e) >>> 0;
  }
  const out = new Uint8Array(20);
  h.forEach((x, i) => {
    out[i * 4] = x >>> 24;
    out[i * 4 + 1] = (x >>> 16) & 255;
    out[i * 4 + 2] = (x >>> 8) & 255;
    out[i * 4 + 3] = x & 255;
  });
  return out;
}

src/lib/ipc/mock-occurrence.ts::occurren.source_code:
function occurrenceId(taskId: string, due: string): string {
  const ns =
    NAMESPACE.replaceAll('-', '')
      .match(/../g)
      ?.map((h) => Number.parseInt(h, 16)) ?? [];
  const name = new TextEncoder().encode(`${taskId}|${due}`);
  const digest = sha1(Uint8Array.from([...ns, ...name])).slice(0, 16);
  digest[6] = ((digest[6] as number) & 0x0f) | 0x50;
  digest[8] = ((digest[8] as number) & 0x3f) | 0x80;
  const h = hex(digest);
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

