function syncReplicas(a: Replica, b: Replica) {
  const seen = new Set<string>();
  const union: Rec[] = [];
  for (const r of [...a.log, ...b.log]) {
    const key = `${r.stamp.device}/${r.seq}`;
    if (seen.has(key)) continue;
    seen.add(key);
    union.push(r);
  }
  const ms = Math.max(a.lastMs, b.lastMs);
  for (const r of [a, b]) {
    r.log = [...union];
    r.lastMs = ms;
  }
}

