function maskRanges(text: string): [number, number][] {
  const out: [number, number][] = [];
  let i = 0;
  while (i < text.length) {
    const open = text[i];
    const close = open === '"' ? '"' : open === '“' ? '”' : open === '`' ? '`' : null;
    if (close === null) {
      i++;
      continue;
    }
    const at = text.indexOf(close, i + 1);
    if (at < 0) {
      i++;
      continue;
    }
    out.push([i, at + 1]);
    i = at + 1;
  }
  return out;
}

