function makeRule(
  freq: RepeatRule['freq'],
  every: number,
  days: number,
  after: boolean,
): RepeatRule | null {
  if (!(every >= 1 && every <= 99)) return null;
  const week = freq === 'week';
  if (after && week && days !== 0) return null;
  return {
    freq,
    every,
    days: week && days !== 0 ? days : null,
    mode: after ? 'after' : 'fixed',
  };
}

