function splitPath(path: string): { pathname: RoutePath; search: string } {
  const at = path.indexOf('?');
  const pathname = (at === -1 ? path : path.slice(0, at)) as RoutePath;
  return { pathname, search: at === -1 ? '' : path.slice(at + 1) };
}

