function lockAxis(dx: number, dy: number, deadZone = AXIS_LOCK_PX): Axis | null {
  if (Math.hypot(dx, dy) < deadZone) return null;
  return Math.abs(dx) > Math.abs(dy) * 1.2 ? 'x' : 'y';
}

