function moveFocus(date: string, key: string, weekStart: WeekStart): string | null {
  switch (key) {
    case 'ArrowLeft':
      return addDays(date, -1);
    case 'ArrowRight':
      return addDays(date, 1);
    case 'ArrowUp':
      return addDays(date, -7);
    case 'ArrowDown':
      return addDays(date, 7);
    case 'Home':
      return addDays(date, -weekdayIndex(date, weekStart));
    case 'End':
      return addDays(date, 6 - weekdayIndex(date, weekStart));
    case 'PageUp':
      return shiftMonthKeepingDay(date, -1);
    case 'PageDown':
      return shiftMonthKeepingDay(date, 1);
    default:
      return null;
  }
}

