  const starts: number[] = [];
  let pos = lineBounds(doc, from).start;
  const last = to > from ? lineBounds(doc, to - 1).start : pos;
  while (pos <= last) {
    starts.push(pos);
    const end = lineBounds(doc, pos).end;
    if (end >= doc.length) break;
    pos = end + 1;
  }
  return starts;
}

