function blocks(nodes: Node[]): Block[] {
  const out: Block[] = [];
  let run: Node[] = [];
  const flush = () => {
    const text = inline(run)
      .replace(/[ \t]*\n[ \t]*/g, '\n')
      .trim();
    if (text !== '') out.push({ text, loose: false });
    run = [];
  };
  for (const n of nodes) {
    if (!isEl(n) || !isBlockTag(n.tag)) {
      run.push(n);
      continue;
    }
    flush();
    out.push(...blockOf(n));
  }
  flush();
  return out;
}

