function slashQuery(doc: string, slashPos: number, caret: number): string | null {
  if (doc[slashPos] !== '/' || caret <= slashPos) return null;
  const typed = doc.slice(slashPos + 1, caret);
  return /\s/.test(typed) ? null : typed;
}

