function toggleTaskLine(body: string, line: number): string | null {
  const lines = body.split('\n');
  const text = lines[line];
  const m = text === undefined ? null : TASK_LINE.exec(text);
  if (text === undefined || !m) return null;
  const head = m[1] ?? '';
