function anchoredScrollTop(
  anchor: ScrollAnchor | null,
  keys: (string | number | bigint)[],
  startOf: (index: number) => number | undefined,
): { top: number; index: number } | null {
  if (!anchor) return null;
  const index = keys.indexOf(anchor.key);
  if (index < 0 || index === anchor.index) return null;
  const start = startOf(index);
  return start === undefined ? null : { top: start + anchor.delta, index };
}

src/lib/ui/sheet-swipe.ts::sheetSwipe.source_code:
function sheetSwipe(
  panel: HTMLElement,
  onclose: () => void,
  reduceMotion: () => boolean,
): () => void {
  let startY = 0;
  let startAt = 0;
  let pulling = false;
  let decided = false;

  const offset = (px: number) => {
    panel.style.transform = px > 0 ? `translateY(${px}px)` : '';
  };
  const settle = (to: string, then?: () => void) => {
    const ms = reduceMotion() ? 0 : SETTLE_MS;
    panel.style.transition = `transform ${ms}ms ease-out`;
    panel.style.transform = to;
    const done = () => {
      panel.style.transition = '';
      then?.();
    };
    if (ms === 0) done();
    else setTimeout(done, ms);
  };

  function onstart(e: TouchEvent) {
    const t = e.touches[0];
    if (!t || e.touches.length !== 1) return;
    const target = e.target as Element;
    const top = panel.getBoundingClientRect().top;
    const inGrip = t.clientY - top <= GRIP_PX;
    startY = t.clientY;
    startAt = performance.now();
    decided = false;
    pulling = inGrip || (panel.scrollTop <= 0 && !target.closest(OWN_TOUCH));
  }

  function onmove(e: TouchEvent) {
    const t = e.touches[0];
    if (!t || !pulling) return;
    const dy = t.clientY - startY;
    if (!decided) {
      if (Math.abs(dy) < AXIS_LOCK_PX) return;
      decided = true;
      // Upwards, or the sheet scrolled meanwhile: the content scrolls as usual.
      if (dy < 0 || panel.scrollTop > 0) {
        pulling = false;
        return;
      }
    }
    if (e.cancelable) e.preventDefault();
    offset(Math.max(0, dy));
  }

  function onend(e: TouchEvent) {
    if (!pulling || !decided) {
      pulling = false;
      return;
    }
    pulling = false;
    const dy = (e.changedTouches[0]?.clientY ?? startY) - startY;
    if (sheetShouldClose(dy, performance.now() - startAt)) settle('translateY(100%)', onclose);
    else settle('');
  }

  panel.addEventListener('touchstart', onstart, { passive: true });
  panel.addEventListener('touchmove', onmove, { passive: false });
  panel.addEventListener('touchend', onend, { passive: true });
  panel.addEventListener('touchcancel', onend, { passive: true });
  return () => {
    panel.removeEventListener('touchstart', onstart);
    panel.removeEventListener('touchmove', onmove);
    panel.removeEventListener('touchend', onend);
    panel.removeEventListener('touchcancel', onend);
  };
}

