function nextDue(rule: RepeatRule, due: string, today: string): string | null {
  if (rule.mode === 'after') return stepDate({ ...rule, days: null }, today);
  let date = stepDate(rule, due);
  while (date !== null && date <= today) date = stepDate(rule, date);
  return date;
}

