  const out: string[] = [];
  let date: string | null = from;
  for (let i = 0; i < 4000 && date !== null; i++) {
    date = stepDate(rule, date);
    if (date === null || date > to) break;
    if (date >= start) out.push(date);
  }
  return out;
}

