function moveNeighbours(
  ids: readonly string[],
  id: string,
  direction: MoveDirection,
): Neighbours | null {
  const i = ids.indexOf(id);
  if (i < 0) return null;
  if (direction === 'up') {
    if (i === 0) return null;
    return { afterId: ids[i - 2] ?? null, beforeId: ids[i - 1] ?? null };
  }
  if (i === ids.length - 1) return null;
  return { afterId: ids[i + 1] ?? null, beforeId: ids[i + 2] ?? null };
}

