function firstLines(body: string): string {
  const kept = body
    .split('\n')
    .map((line) => line.trimEnd())
    .filter((line) => line.trim() !== '')
    .slice(0, LINES)
    .join('\n');
  return kept.length > CHARACTERS ? `${kept.slice(0, CHARACTERS).trimEnd()}…` : kept;
}

