    });
  }

flashPageFor(date: string): void {
    clearTimeout(this.#pageTimer);
    this.flashPage = null;
    queueMicrotask(() => {
      this.flashPage = date;
      this.#pageTimer = setTimeout(() => (this.flashPage = null), FLASH_MS);
    });
  }

