function routeOfAddress(stored: string): 'wifi' | 'tailscale' {
  const text = stored.trim().toLowerCase();
  if (text.startsWith('[')) {
    const inner = text.slice(1, text.indexOf(']'));
    return /^fd7a:115c:a1e0(:|$)/.test(inner) ? 'tailscale' : 'wifi';
  }
  const host = text.split(':')[0] ?? '';
  const v4 = /^100\.(\d{1,3})\.\d{1,3}\.\d{1,3}$/.exec(host);
  if (v4) return Number(v4[1]) >= 64 && Number(v4[1]) <= 127 ? 'tailscale' : 'wifi';
  return host.endsWith('.ts.net') ? 'tailscale' : 'wifi';
}

src/modules/sync/address.ts::usesTailsca.source_code:
function usesTailscale(raw: string): boolean {
  const parsed = parseAddress(raw);
  if (!parsed.ok) return false;
  const host = parsed.stored.startsWith('[')
    ? parsed.stored.slice(1, parsed.stored.indexOf(']'))
    : (parsed.stored.split(':')[0] ?? '');
  if (parsed.stored.startsWith('[')) return host.startsWith('fd7a:115c:a1e0:');
  if (isIpv4(host)) {
    const [a = 0, b = 0] = host.split('.').map(Number);
    return a === 100 && b >= 64 && b <= 127;
  }
  return host.endsWith('.ts.net') || !host.includes('.');
}

