function fakeTimers() {
  let now = 0;
  const pending = new Set<{ at: number; fn: () => void }>();
  return {
    setTimer: (fn: () => void, ms: number) => {
      const entry = { at: now + ms, fn };
      pending.add(entry);
      return () => pending.delete(entry);
    },
    advance(ms: number) {
      now += ms;
      for (const entry of [...pending]) {
        if (entry.at <= now) {
          pending.delete(entry);
          entry.fn();
        }
      }
    },
  };
}

