function syncedText(
  peer: Pick<PeerRow, 'last_synced_at' | 'state'>,
  now: Date = new Date(),
): string {
  if (peer.last_synced_at === null) return 'not synced yet';
  const when = relativeTime(new Date(peer.last_synced_at), now);
  return `${
    peer.state === 'paused' ||
    peer.state === 'paused_on_mobile_data' ||
    peer.state === 'blocked_by_local_network'
      ? 'last synced'
      : 'synced'
  } ${when}`;
}

