function pasteParts(pasted: string): { title: string; notes: string } | null {
  const lines = pasted.replace(/\r\n?/g, '\n').replace(/\n+$/, '').split('\n');
  if (lines.length < 2) return null;
  const first = lines.findIndex((l) => l.trim() !== '');
  if (first < 0) return null;
  const head = (lines[first] as string).trim();
  const title = [...head].slice(0, MAX_TITLE).join('');
  const spill = [...head].slice(MAX_TITLE).join('');
  const rest = lines.slice(first + 1).join('\n');
  return { title, notes: [spill, rest].filter(Boolean).join('\n').trim() };
}

src/modules/todo/capture.ts::pasteIntoTi.source_code:
function pasteIntoTitle(
  text: string,
  start: number,
  end: number,
  pasted: string,
): { text: string; caret: number } | null {
  const lines = pasted
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
  if (lines.length < 2) return null;
  const room = Math.max(
    0,
    MAX_TITLE - [...text.slice(0, start)].length - [...text.slice(end)].length,
  );
  const insert = [...lines.join(' ')].slice(0, room).join('');
  return {
    text: `${text.slice(0, start)}${insert}${text.slice(end)}`,
    caret: start + insert.length,
  };
}

