function autoScrollSpeed(
  y: number,
  top: number,
  bottom: number,
  edge = 56,
  max = 16,
): number {
  if (y < top + edge) return -Math.round(max * Math.min(1, (top + edge - y) / edge));
  if (y > bottom - edge) return Math.round(max * Math.min(1, (y - (bottom - edge)) / edge));
  return 0;
}

