function setup(initial = { title: 'Pay rent', notes: '' }) {
  const calls: string[] = [];
  const timers: { fn: () => void; ms: number; live: boolean }[] = [];
  const saved: unknown[] = [];
  const errors: unknown[] = [];
  let fail: unknown = null;
  const editing = new TaskEditing<string>(
    {
      update: async (id, title, notes, session) => {
        calls.push(`${id}|${title}|${notes}|${session}`);
        if (fail) throw fail;
        return title;
      },
      setTimer: (fn, ms) => {
        const t = { fn, ms, live: true };
        timers.push(t);
        return () => {
          t.live = false;
        };
      },
      onSaved: (t) => saved.push(t),
      onError: (e) => errors.push(e),
    },
    't1',
    initial,
    's1',
  );
  const fire = () => {
    for (const t of timers.filter((t) => t.live)) {
      t.live = false;
      t.fn();
    }
  };
  return {
    editing,
    calls,
    saved,
    errors,
    timers,
    fire,
    failWith: (e: unknown) => {
      fail = e;
    },
  };
}

