function parseUnderstood(json: string | null): Understood[] {
  if (!json) return [];
  try {
    const list: unknown = JSON.parse(json);
    if (!Array.isArray(list)) return [];
    return list.filter(
      (e): e is Understood =>
        typeof e === 'object' &&
        e !== null &&
        typeof e.word === 'string' &&
        typeof e.value === 'string' &&
        KINDS.includes(e.kind),
    );
  } catch {
    return [];
  }
}

