function sameRepeat(a: RepeatRule | null, b: RepeatRule | null): boolean {
  if (a === null || b === null) return a === b;
  return (
    a.freq === b.freq &&
    a.every === b.every &&
    a.mode === b.mode &&
    (a.freq !== 'week' || (a.days ?? 0) === (b.days ?? 0))
  );
}

