    case 'time':
      return fields.due_time === u.value;
    case 'prio':
      return String(fields.priority) === u.value;
    case 'list':
      return fields.list_id === u.value;
    case 'repeat':
      return sameRepeat(parseRepeat(u.value), taskRepeat(fields as Task));
  }
}

