function visibleOn(
  view: TodoView,
  task: { due_date: string | null; list_id: string | null },
  today: string,
): boolean {
  if (view.kind === 'list') return task.list_id === view.id;
  switch (view.id) {
    case 'today':
      return task.due_date !== null && task.due_date <= today;
    case 'upcoming':
      return task.due_date !== null && task.due_date > today;
    case 'inbox':
      return task.list_id === null || task.due_date === null;
    case 'all':
      return true;
    case 'done':
      return false;
  }
}

