function moveTab(tabs: string[], id: string, delta: -1 | 1): string[] {
  const from = tabs.indexOf(id);
  const to = from + delta;
  if (from < 0 || to < 0 || to >= tabs.length) return tabs;
  const next = [...tabs];
  next.splice(from, 1);
  next.splice(to, 0, id);
  return next;
}

