object SyncLink {
    const val OFFLINE = 0
    /** Wi-Fi, Ethernet or anything else that is not mobile data. */
    const val WIFI = 1
    const val MOBILE = 2

    /** One non-VPN network that has internet. */
    data class Net(val wifi: Boolean, val ethernet: Boolean, val cellular: Boolean)

    /** Wi-Fi or Ethernet anywhere wins over mobile data; mobile data counts only when it is all there is. */
    fun of(nets: Collection<Net>): Int = when {
        nets.isEmpty() -> OFFLINE
        nets.any { it.wifi || it.ethernet || !it.cellular } -> WIFI
        else -> MOBILE
    }
}

fun of(nets: Collection<Net>): Int = when {
    nets.isEmpty() -> OFFLINE
    nets.any { it.wifi || it.ethernet || !it.cellular } -> WIFI
    else -> MOBILE
}

object HeaderDate {
    /** The short date the locale spells best ("Thu 22", "22 Thu" ...). */
    const val SKELETON = "EEEd"

    /**
     * Only the Today view carries the date, and only where the layout has the room ([wideEnough]).
     * Not tied to the font scale: nothing redraws the Todo widget when it changes, so the rule would go stale.
     * At large text the name ellipsizes first, as the header rules say.
     */
    fun shows(view: String, wideEnough: Boolean): Boolean = view == "today" && wideEnough

    /** A TextClock pattern for [datePattern] with the "·" separator ahead of it, quoted as a literal. */
    fun pattern(datePattern: String): String = "'·' $datePattern"

    /** Name first, then count, then date: with the date shown the date is the flexible part, otherwise (long List names) the name is. */
    fun nameIsFlexible(dateShown: Boolean): Boolean = !dateShown
}

object Midnight {
    /** A few seconds past midnight, so the clock has certainly crossed it. */
    private const val SLACK_MS = 5_000L

    /** The next local midnight after [nowMs] in [zone] (daylight-saving aware), plus a little slack. */
    fun nextAfter(nowMs: Long, zone: ZoneId): Long {
        val today = Instant.ofEpochMilli(nowMs).atZone(zone).toLocalDate()
        return today.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli() + SLACK_MS
    }

    /** How long from [nowMs] until [nextAfter]: the minimum latency of the midnight job. */
    fun delayFrom(nowMs: Long, zone: ZoneId): Long = nextAfter(nowMs, zone) - nowMs
}

fun nextAfter(nowMs: Long, zone: ZoneId): Long {
    val today = Instant.ofEpochMilli(nowMs).atZone(zone).toLocalDate()
    return today.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli() + SLACK_MS
}

