enum class SizeMode {
    /** The card with the Task list, without the header date. */
    LIST,

    /** The same card with the date in the Today header: wide enough for it (4x2 and up). */
    LIST_DATE,

    /** The "Add a task..." pill. */
    PILL,

    /** A plain + at the smallest sizes. */
    PLUS,
    ;

    /** The smallest size, in dp, that a layout for this mode is meant for. */
    data class Breakpoint(val mode: SizeMode, val widthDp: Float, val heightDp: Float)

    companion object {
        const val LIST_MIN_WIDTH_DP = 180f
        const val LIST_MIN_HEIGHT_DP = 110f
        const val PILL_MIN_WIDTH_DP = 100f

        /** From here the Today header has room for the date next to the name and count (4x2 is about 276 dp, 3x2 about 203 dp). */
        const val DATE_MIN_WIDTH_DP = 240f

        /**
         * The layouts a size-responsive RemoteViews carries, smallest first. Android shows the
         * largest one that fits the widget (and the smallest when none does), so these sizes are the
         * thresholds: the PLUS and PILL heights are only above zero so the system ranks them.
         */
        val BREAKPOINTS: List<Breakpoint> = listOf(
            Breakpoint(PLUS, 0f, 0f),
            Breakpoint(PILL, PILL_MIN_WIDTH_DP, 1f),
            Breakpoint(LIST, LIST_MIN_WIDTH_DP, LIST_MIN_HEIGHT_DP),
            Breakpoint(LIST_DATE, DATE_MIN_WIDTH_DP, LIST_MIN_HEIGHT_DP),
        )

        /** The mode for a widget [widthDp] wide and [heightDp] high. */
        fun of(widthDp: Float, heightDp: Float): SizeMode = when {
            widthDp >= DATE_MIN_WIDTH_DP && heightDp >= LIST_MIN_HEIGHT_DP -> LIST_DATE
            widthDp >= LIST_MIN_WIDTH_DP && heightDp >= LIST_MIN_HEIGHT_DP -> LIST
            widthDp >= PILL_MIN_WIDTH_DP -> PILL
            else -> PLUS
        }
    }
}

fun of(widthDp: Float, heightDp: Float): SizeMode = when {
    widthDp >= DATE_MIN_WIDTH_DP && heightDp >= LIST_MIN_HEIGHT_DP -> LIST_DATE
    widthDp >= LIST_MIN_WIDTH_DP && heightDp >= LIST_MIN_HEIGHT_DP -> LIST
    widthDp >= PILL_MIN_WIDTH_DP -> PILL
    else -> PLUS
}

sealed interface Reply {
    data class Ok(val snapshot: Snapshot) : Reply

    /** The app has never run here: there is no database. */
    data object NotSetUp : Reply

    /** The app was updated and its migrations have not run yet. */
    data object NeedsUpdate : Reply

    /** The widget shows a List that was deleted. */
    data object ListMissing : Reply

    /** Anything else: a bridge error, an unreadable reply, no library. */
    data object Failed : Reply
}

sealed interface TickReply {
    /** The Task is done (or moved on). [message] is the Undo bar's text, [token] undoes it. */
    data class Completed(
        val message: String,
        /** The bar's title part, which may be cut short to fit. */
        val lead: String,
        /** "· next Thu 29 Oct" for a repeating Task, which is never cut; none otherwise. */
        val suffix: String?,
        val token: String,
    ) : TickReply

    /** The Task has unticked steps: ask before doing anything. */
    data class OpenSteps(val taskId: String, val title: String, val count: Int) : TickReply

    /** Anything else: the Task is gone or closed, the app needs an update, no library. */
    data object Failed : TickReply
}

data class Completed(
    val message: String,
    /** The bar's title part, which may be cut short to fit. */
    val lead: String,
    /** "· next Thu 29 Oct" for a repeating Task, which is never cut; none otherwise. */
    val suffix: String?,
    val token: String,
) : TickReply

object ReplyParser {
    fun parse(json: String?): Reply {
        if (json == null) return Reply.Failed
        return try {
            val root = JSONObject(json)
            when {
                root.has("ok") -> Reply.Ok(snapshot(root.getJSONObject("ok")))
                root.optString("status") == "not_set_up" -> Reply.NotSetUp
                root.optString("status") == "needs_update" -> Reply.NeedsUpdate
                root.optJSONObject("err")?.optString("code") == "not_found" -> Reply.ListMissing
                else -> Reply.Failed
            }
        } catch (e: Exception) {
            Reply.Failed
        }
    }

    /** Reads the reply to a tick. Never throws. */
    fun parseTick(json: String?): TickReply {
        if (json == null) return TickReply.Failed
        return try {
            val ok = JSONObject(json).optJSONObject("ok") ?: return TickReply.Failed
            when (ok.optString("kind")) {
                "completed" -> TickReply.Completed(
                    ok.getString("message"),
                    ok.getString("lead"),
                    if (ok.isNull("suffix")) null else ok.getString("suffix"),
                    ok.getString("token"),
                )
                "open_steps" -> TickReply.OpenSteps(ok.getString("task_id"), ok.getString("title"), ok.getInt("count"))
                else -> TickReply.Failed
            }
        } catch (e: Exception) {
            TickReply.Failed
        }
    }

    /** Whether an Undo worked. */
    fun parseUndo(json: String?): Boolean {
        if (json == null) return false
        return try {
            JSONObject(json).optJSONObject("ok")?.optBoolean("undone") == true
        } catch (e: Exception) {
            false
        }
    }

    /** Reads the `lists` reply; null when there are no Lists to show (not set up, an error). */
    fun parseLists(json: String?): ListChoices? {
        if (json == null) return null
        return try {
            val ok = JSONObject(json).optJSONObject("ok") ?: return null
            ListChoices(
                appTheme = text(ok, "app_theme")?.ifEmpty { null },
                lists = list(ok.getJSONArray("lists")) {
                    ListChoice(
                        id = it.getString("id"),
                        name = it.getString("name"),
                        emoji = text(it, "emoji"),
                        label = it.getString("label"),
                    )
                },
            )
        } catch (e: Exception) {
            null
        }
    }

    private fun snapshot(o: JSONObject) = Snapshot(
        view = o.getString("view"),
        title = o.getString("title"),
        count = o.optJSONObject("count")?.let {
            HeaderCount(it.getString("text"), tone(it.getString("tone")))
        },
        groups = list(o.getJSONArray("groups")) { group(it) },
        empty = o.optJSONObject("empty")?.let {
            EmptyState(it.getString("title"), it.getString("line"))
        },
        appTheme = text(o, "app_theme")?.ifEmpty { null },
    )

    private fun group(o: JSONObject) = Group(
        // Inbox and Lists have a group with no heading: JSON null, which optString would read as "null".
        heading = text(o, "heading")?.ifEmpty { null },
        tone = tone(o.getString("tone")),
        rows = list(o.getJSONArray("rows")) { row(it) },
    )

    private fun row(o: JSONObject) = TaskRow(
        id = o.getString("id"),
        title = o.getString("title"),
        ring = o.getString("ring"),
        overdue = o.getBoolean("overdue"),
        time = text(o, "time"),
        day = text(o, "day"),
        list = text(o, "list"),
    )

    /** A string field that may be null in the JSON. */
    private fun text(o: JSONObject, key: String): String? =
        if (o.isNull(key)) null else o.getString(key)

    private fun tone(name: String) = if (name == "overdue") Tone.OVERDUE else Tone.NORMAL

    private fun <T> list(array: JSONArray, read: (JSONObject) -> T): List<T> =
        (0 until array.length()).map { read(array.getJSONObject(it)) }
}

