enum class ThemeChoice(val key: String) {
    /** Follows Settings ▸ Theme in the app. */
    APP("app"),
    LIGHT("light"),
    DARK("dark"),
    TRUE_BLACK("oled"),
    ;

    companion object {
        /**
         * Reads a stored key; anything unknown is [APP]. That includes the retired Material You keys
         * ("you", "you_dark"), so a widget saved with them follows the app's theme.
         */
        fun fromKey(key: String?): ThemeChoice = values().firstOrNull { it.key == key } ?: APP
    }
}

enum class Background(val key: String, val alpha: Float) {
    /** The theme's opaque surface. */
    SOLID("solid", 1f),

    /** The surface at about 70%: Android cannot blur behind a widget. */
    SEE_THROUGH("see_through", 0.72f),

    /** No surface: text straight on the wallpaper. */
    NONE("none", 0f),
    ;

    companion object {
        /** Reads a stored key; anything unknown is [SOLID]. */
        fun fromKey(key: String?): Background = values().firstOrNull { it.key == key } ?: SOLID
    }
}

object WidgetTheme {
    /**
     * The look for a [choice]. "Same as app" follows the app's Settings ▸ Theme ([appTheme]:
     * `light`, `dark`, `oled` or `system`); on `system`, or when the app's theme is not known
     * (the app has not run yet), the phone's night mode decides.
     */
    fun resolve(choice: ThemeChoice, appTheme: String?, phoneNight: Boolean): Look = when (choice) {
        ThemeChoice.LIGHT -> Look.LIGHT
        ThemeChoice.DARK -> Look.DARK
        ThemeChoice.TRUE_BLACK -> Look.TRUE_BLACK
        ThemeChoice.APP -> when (appTheme) {
            "light" -> Look.LIGHT
            "dark" -> Look.DARK
            "oled" -> Look.TRUE_BLACK
            else -> if (phoneNight) Look.DARK else Look.LIGHT
        }
    }

    /**
     * Whether the look follows the phone's night mode: "Same as app" while the app's own theme is
     * System (or unknown). Such a widget is drawn in both looks, and the launcher picks one itself
     * when night mode flips, with no redraw.
     */
    fun followsPhone(choice: ThemeChoice, appTheme: String?): Boolean =
        choice == ThemeChoice.APP && appTheme !in setOf("light", "dark", "oled")

    /** Whether a look is a dark one (its Priority colours are the lighter set). */
    fun isDark(look: Look): Boolean = look != Look.LIGHT
}

fun resolve(choice: ThemeChoice, appTheme: String?, phoneNight: Boolean): Look = when (choice) {
    ThemeChoice.LIGHT -> Look.LIGHT
    ThemeChoice.DARK -> Look.DARK
    ThemeChoice.TRUE_BLACK -> Look.TRUE_BLACK
    ThemeChoice.APP -> when (appTheme) {
        "light" -> Look.LIGHT
        "dark" -> Look.DARK
        "oled" -> Look.TRUE_BLACK
        else -> if (phoneNight) Look.DARK else Look.LIGHT
    }
}

object WidgetUpdater {
    private const val TAG = "TodoWidget"
    private const val ACTION_TODO_CHANGED = "com.hemang.mnemora.widget.TODO_CHANGED"

    private val executor = Executors.newSingleThreadExecutor()
    private val queued = AtomicBoolean(false)

    /** When this process last drew, or 0: lets a resize skip a redraw that would show the same. */
    @Volatile
    private var lastDrawAt = 0L

    /** True for the broadcasts that mean "redraw all widgets". */
    fun isRedrawAction(action: String?) = when (action) {
        ACTION_TODO_CHANGED,
        // The clock or zone moved, so Today and Overdue may have changed. (DATE_CHANGED is never
        // delivered to a manifest receiver; the midnight job covers the day change.)
        Intent.ACTION_TIME_CHANGED, Intent.ACTION_TIMEZONE_CHANGED -> true
        else -> false
    }

    /** Todo data changed in the app: ask the provider to redraw all widgets. Safe on any thread. */
    fun signalChanged(context: Context) {
        context.sendBroadcast(
            Intent(context, TodoWidgetProvider::class.java).setAction(ACTION_TODO_CHANGED),
        )
    }

    /**
     * Redraws all widgets soon. A request that arrives while another is still waiting to start is
     * folded into it, since that one will read the newest data anyway. [pending] is finished when done.
     */
    fun redrawAsync(context: Context, pending: BroadcastReceiver.PendingResult?) {
        redrawAsync(context) { pending?.finish() }
    }

    /** Like [redrawAsync] with a PendingResult; [done] runs when the redraw (or the one it folded into) is under way or finished. */
    fun redrawAsync(context: Context, done: () -> Unit) {
        val app = context.applicationContext
        if (!queued.compareAndSet(false, true)) {
            done()
            return
        }
        executor.execute {
            queued.set(false)
            try {
                redraw(app)
            } catch (e: Throwable) {
                Log.w(TAG, "redraw failed", e)
            } finally {
                done()
            }
        }
    }

    /**
     * The launcher reports a new widget size. The responsive RemoteViews already pick the layout
     * for it, so this only redraws when the process has not drawn lately (see [ResizeRedraw]).
     */
    fun redrawOnResize(context: Context, pending: BroadcastReceiver.PendingResult?) {
        if (ResizeRedraw.due(lastDrawAt, System.currentTimeMillis())) redrawAsync(context, pending) else pending?.finish()
    }

    /** Redraws all widgets now, on the calling thread (which must not be the main one). Never throws. */
    fun redrawNow(context: Context) {
        try {
            redraw(context.applicationContext)
        } catch (e: Throwable) {
            Log.w(TAG, "redraw failed", e)
        }
    }

    /**
     * Makes sure the Undo bar comes down when its time is up, even though the vivo freezer freezes
     * this process seconds after it goes idle (a frozen process runs no timer and loses its
     * alarms): a job (see [WidgetJobs]) keeps it running until then and redraws. The draw itself
     * checks the clock, so all the job has to do is cause a draw.
     */
    fun hideUndoAt(context: Context) {
        WidgetJobs.armUndoExpiry(context)
    }

    @Synchronized
    private fun redraw(context: Context) {
        val manager = AppWidgetManager.getInstance(context)
        val ids = manager.getAppWidgetIds(ComponentName(context, TodoWidgetProvider::class.java))
        WidgetConfigStore.retainOnly(context, ids)
        // A bar that is over goes, with the Undo token (which may hold the Task's notes) it carries.
        UndoBar.settle(context, System.currentTimeMillis())
        if (ids.isEmpty()) {
            WidgetJobs.cancelMidnight(context)
            return
        }
        if (Build.VERSION.SDK_INT < 31) return
        val zone = ZoneId.systemDefault()
        // Arm before drawing: if a read or a render throws below, the next-midnight job must still
        // exist, or the Todo widget keeps yesterday's Today. (Re-arming replaces the pending job, so
        // every redraw may do it. No pure seam to unit test: it needs JobScheduler.)
        WidgetJobs.armMidnight(context, zone)
        val now = System.currentTimeMillis()
        // Widgets showing the same view share one read.
        val replies = HashMap<String, Reply>()
        for (id in ids) {
            val config = WidgetConfigStore.get(context, id)
            val reply = replies.getOrPut(config.view) {
                ReplyParser.parse(WidgetBridge.call(context, WidgetRequests.snapshot(config.view, now, zone)))
            }
            (reply as? Reply.Ok)?.let { WidgetConfigStore.rememberAppTheme(context, it.snapshot.appTheme) }
            manager.updateAppWidget(id, WidgetRenderer.responsive(context, reply, config, id))
        }
        lastDrawAt = System.currentTimeMillis()
    }

    /** Called when the last widget is removed. */
    fun cancelMidnight(context: Context) {
        WidgetJobs.cancelMidnight(context)
        WidgetJobs.cancelUndoExpiry(context)
    }
}

fun isRedrawAction(action: String?) = when (action) {
    ACTION_TODO_CHANGED,
    // The clock or zone moved, so Today and Overdue may have changed. (DATE_CHANGED is never
    // delivered to a manifest receiver; the midnight job covers the day change.)
    Intent.ACTION_TIME_CHANGED, Intent.ACTION_TIMEZONE_CHANGED -> true
    else -> false
}

fun signalChanged(context: Context) {
    context.sendBroadcast(
        Intent(context, TodoWidgetProvider::class.java).setAction(ACTION_TODO_CHANGED),
    )
}

fun redrawAsync(context: Context, done: () -> Unit) {
    val app = context.applicationContext
    if (!queued.compareAndSet(false, true)) {
        done()
        return
    }
    executor.execute {
        queued.set(false)
        try {
            redraw(app)
        } catch (e: Throwable) {
            Log.w(TAG, "redraw failed", e)
        } finally {
            done()
        }
    }
}

fun redrawOnResize(context: Context, pending: BroadcastReceiver.PendingResult?) {
    if (ResizeRedraw.due(lastDrawAt, System.currentTimeMillis())) redrawAsync(context, pending) else pending?.finish()
}

fun redrawNow(context: Context) {
    try {
        redraw(context.applicationContext)
    } catch (e: Throwable) {
        Log.w(TAG, "redraw failed", e)
    }
}

