fn until_label(events: &Receiver<AiRunEvent>, wanted: &str) -> Vec<AiRunEvent> {
    let mut seen = Vec::new();
    loop {
        let event = events
            .recv_timeout(Duration::from_secs(5))
            .expect("the event arrives");
        let hit = label(&event) == wanted;
        seen.push(event);
        if hit {
            return seen;
        }
    }
}

