pub(crate) fn ended_outcome(run: &[AiRunEvent]) -> RunOutcome {
    match &run.last().expect("a Run has events").event {
        RunEvent::RunEnded { outcome } => outcome.clone(),
        other => panic!("the last event was not the end: {other:?}"),
    }
}

