    assert_eq!(saved.last().unwrap()["sources"][0]["id"], id);

    let seen = server.requests();
    let first_body: Value = serde_json::from_str(&seen[0].body).unwrap();
    assert_eq!(first_body["tools"][0]["type"], "function");
    assert!(
        first_body["tools"]
