fn an_anthropic_provider_has_its_fixed_address_and_a_required_key() {
    let app = TestApp::new();
    let created: Value = app
        .invoke(
            "ai_provider_create",
            json!({ "request": { "kind": "anthropic", "name": "Claude", "address": "https://api.anthropic.com/v1/" } }),
