fn open_first<E>(urls: &[&str], mut open: impl FnMut(&str) -> Result<(), E>) -> Result<(), E> {
    let mut last = None;
    for url in urls {
        match open(url) {
            Ok(()) => return Ok(()),
            Err(e) => last = Some(e),
        }
    }
    last.map_or(Ok(()), Err)
}

