        .invoke("todo_task", json!({ "id": report["id"] }))
        .unwrap();
    assert_eq!(got["title"], "Report v2");
    assert_eq!(got["priority"], 1);
    assert_eq!(got["list_id"], work["id"]);
    assert_eq!(every_row(&c[0]), every_row(&c[1]));
}

