    .unwrap();
    c.sync(0, 1);
    for device in 0..2 {
        let t = task(&c[device], &id).unwrap();
        assert_eq!(t["title"], "Call mum tomorrow!");
        assert_eq!(t["understood"], json!(words));
    }
}

