fn next(&mut self) -> u64 {
    self.0 ^= self.0 << 13;
    self.0 ^= self.0 >> 7;
    self.0 ^= self.0 << 17;
    self.0
}

fn below(&mut self, n: usize) -> usize {
    usize::try_from(self.next() % u64::try_from(n).unwrap()).unwrap()
}

