fn converge(seed: u64) {
    // Paired and named, so that the Address typed for a device has someone to be typed for.
    let c = crate::sync_address_tests::group(3);
    // Each device also holds rows its change log never heard of (DV1): the first merge must
    // combine them like any other, and the run must still end identical.
    crate::sync_backfill_tests::seed_unlogged(&c, 3);
    let mut rng = Rng(seed);
    let mut ids: Vec<Value> = Vec::new();
    let mut list_ids: Vec<Value> = Vec::new();
    let mut journal = Journal::default();
    let mut ai = AiIds::default();
    for d in 0..3 {
        crate::ai_sync_tests::answering(&c[d]);
    }
    for step in 0..160 {
        let d = rng.below(3);
        c[d].clock()
            .advance(1 + i64::try_from(rng.below(40)).unwrap());
        // About one step in six is an AI action (a Conversation or a Saved question); the rest are
        // the Todo, Journal and Sync mix.
        if rng.below(6) == 0 {
            random_ai_action(&c, &mut rng, d, step, &mut ai);
        } else {
            random_action(&c, &mut rng, d, step, &mut ids, &mut list_ids, &mut journal);
        }
        // Now and then a member types, changes or clears the Address of another device.
        if rng.below(12) == 0 {
            let target = (d + 1 + rng.below(2)) % 3;
            let address = match rng.below(4) {
                0 => String::new(),
                n => format!("10.0.{n}.{}", rng.below(5) + 1),
            };
            let _ = c[d].invoke::<Value>(
                "sync_device_address",
                json!({ "id": c[target].device_id(), "address": address }),
            );
        }
        // Now and then the person settles a Conflict that waits on this device.
        if rng.below(10) == 0 {
            let waiting = crate::sync_conflicts_tests::ids(&c[d]);
            if let Some(conflict) = waiting.get(rng.below(waiting.len().max(1))) {
                let choice = match rng.below(3) {
                    0 => json!({ "kind": "keep_this" }),
                    1 => json!({ "kind": "keep_other" }),
                    _ => json!({ "kind": "merged", "text": "settled by hand" }),
                };
                let _ = c[d].invoke::<()>(
                    "sync_conflict_resolve",
                    json!({ "id": conflict, "choice": choice }),
                );
            }
        }
        if rng.below(4) == 0 {
            let (a, b) = (rng.below(3), rng.below(3));
            if a != b {
                // Some exchanges drop part way: the next one must pick up exactly.
                let cut = (rng.below(3) == 0).then(|| 2 + rng.below(4));
                let _ = c.try_sync(a, b, cut);
            }
        }
    }
    // Every editor closes in the end; what waited is merged, and the devices must agree.
    for (d, id) in journal.holds.drain(..) {
        release_entry(&c[d], &id);
    }
    c.sync_all();
    // A session that moves only Activity logs no line, so the chain of lines ends by itself; it
    // may take a few rounds for the last line to reach the device farthest from its author.
    for _ in 0..6 {
        let first = activity_ids(&c[0]);
        if (1..3).all(|d| activity_ids(&c[d]) == first) {
            break;
        }
        c.sync_all();
    }
    assert_devices_agree(&c, seed, &ids);
}

