fn assert_addresses_agree(c: &Cluster, seed: u64) {
    for target in 0..3 {
        let id = c[target].device_id();
        let typed = |d: usize| -> Value {
            c[d].invoke::<Value>("sync_device", json!({ "id": id }))
                .map_or(Value::Null, |s| s["typed_address"].clone())
        };
        let others: Vec<usize> = (0..3).filter(|d| *d != target).collect();
        assert_eq!(
            typed(others[0]),
            typed(others[1]),
            "seed {seed}: devices differ on the Address typed for device {target}"
        );
    }
    for target in 0..3 {
        let id = c[target].device_id();
        let about = |d: usize| -> Vec<String> {
            let mut lines: Vec<String> = address_lines(&c[d])
                .into_iter()
                .filter(|(device, _)| *device == id)
                .map(|(_, line)| line)
                .collect();
            lines.sort();
            lines
        };
        assert!(
            about(target).is_empty(),
            "seed {seed}: device {target} logged a clash over its own Address"
        );
        let others: Vec<usize> = (0..3).filter(|d| *d != target).collect();
        assert_eq!(
            about(others[0]),
            about(others[1]),
            "seed {seed}: the Address lines for device {target} differ"
        );
    }
}

fn assert_devices_agree(c: &Cluster, seed: u64, ids: &[Value]) {
    let lists_first = crate::sync_lists_tests::world(&c[0]);
    for d in 1..3 {
        let other = crate::sync_lists_tests::world(&c[d]);
        if other != lists_first {
            for section in [
                "lists",
                "tasks",
                "comments",
                "settings",
                "entries",
                "conversations",
                "ai_entries",
                "saved",
            ] {
                let (a, b) = (
                    lists_first[section].as_array().unwrap(),
                    other[section].as_array().unwrap(),
                );
                for row in a.iter().filter(|r| !b.contains(r)) {
                    eprintln!("DIFF seed {seed} {section} only on 0: {row}");
                }
                for row in b.iter().filter(|r| !a.contains(r)) {
                    eprintln!("DIFF seed {seed} {section} only on {d}: {row}");
                }
            }
        }
        assert!(
            other == lists_first,
            "seed {seed}: device {d} differs in Lists, Comments or Preferences"
        );
    }
    // The same Conflicts wait on every device.
    let waiting = crate::sync_conflicts_tests::ids(&c[0]);
    let total: i64 = c[0].with_db(|db| {
        db.query_row("SELECT COUNT(*) FROM sync_conflicts", [], |r| r.get(0))
            .unwrap()
    });
    eprintln!(
        "seed {seed}: {} waiting, {total} conflicts in all",
        waiting.len()
    );
    for d in 1..3 {
        assert_eq!(
            crate::sync_conflicts_tests::ids(&c[d]),
            waiting,
            "seed {seed}: device {d} has other Conflicts waiting"
        );
    }
    // Look and feel is per device: the theme is whatever each device last set itself.
    for id in ids {
        let first = seen(&c[0], id);
        let first_history = history_seen(&c[0], id);
        for d in 1..3 {
            assert_eq!(
                seen(&c[d], id),
                first,
                "seed {seed}: device {d} differs on {id}"
            );
            // History is a function of the records, so it reads the same everywhere.
            assert_eq!(
                history_seen(&c[d], id),
                first_history,
                "seed {seed}: device {d} reads {id}'s History differently"
            );
        }
    }
    assert_addresses_agree(c, seed);
    // Resolved automatically (what was decided, and what was changed back) and Activity (every
    // line of the log) are the same on every device.
    let (resolved_first, activity_first) = (resolutions_of(&c[0]), activity_ids(&c[0]));
    for d in 1..3 {
        assert_eq!(
            resolutions_of(&c[d]),
            resolved_first,
            "seed {seed}: device {d} has other Resolved automatically lines"
        );
        assert_eq!(
            activity_ids(&c[d]),
            activity_first,
            "seed {seed}: device {d} has other Activity lines"
        );
    }
}

