fn activity_ids(app: &TestApp) -> Vec<String> {
    let mut ids = Vec::new();
    let mut cursor = Value::Null;
    loop {
        let page: Value = app
            .invoke(
                "sync_activity",
                json!({ "filter": { "kind": "all" }, "cursor": cursor, "limit": 100 }),
            )
            .unwrap();
        ids.extend(
            page["rows"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| r["id"].as_str().unwrap().to_owned()),
        );
        if page["next"].is_null() {
            break;
        }
        cursor = page["next"].clone();
    }
    ids.sort();
    ids
}

