fn clash_on_creation() -> (Cluster, Value, Value) {
    let c = Cluster::new(2);
    let older = create_list(&c[0], "Groceries");
    c[0].invoke::<Value>(
        "todo_list_set_emoji",
        json!({ "id": older["id"], "emoji": "🛒" }),
