fn the_merge_is_the_same_whichever_list_a_third_device_hears_of_first() {
    for first in [0, 1] {
        let (c, older, _) = {
            let c = Cluster::new(3);
            let older = create_list(&c[0], "Groceries");
            task_in(&c[0], "Milk", Some(&older["id"]));
