    let late = task_in(&c[1], "Late", Some(&trip["id"]));
    c[0].clock().advance(1_000);
    c[0].invoke::<Value>(
        "todo_list_delete",
        json!({ "id": trip["id"], "choice": { "kind": "move_to_inbox" } }),
    )
    .unwrap();
    c.sync(0, 1);
    c.sync(0, 1);
    for d in 0..2 {
        assert_eq!(
            task(&c[d], &late["id"])["list_id"],
            Value::Null,
            "device {d}"
        );
    }
    let (to_b, to_a) = c.sync(0, 1);
    assert_eq!(
        (to_b.sent, to_a.sent),
        (0, 0),
        "nothing was recorded to tell the others"
    );
    same_world(&c, 2);
}

