fn a_new_conflict_is_announced_only_on_a_device_set_to_a_toast() {
    let c = Cluster::new(2);
    name_each_other(&c);
    // The Pixel 8 wants toasts, the Mac stays quiet (the default).
    c[1].invoke::<()>(
        "sync_set_option",
        json!({ "option": "toast_conflicts", "enabled": true }),
    )
    .unwrap();
    let heard: Arc<Mutex<Vec<(usize, Value)>>> = Arc::default();
    for d in 0..2 {
        let sink = Arc::clone(&heard);
        tauri_specta::Event::listen(
            &c[d].handle(),
            move |e: tauri_specta::TypedEvent<crate::SyncNewConflictsEvent>| {
                sink.lock()
                    .unwrap()
                    .push((d, serde_json::to_value(&e.payload).unwrap()));
            },
        );
    }
    let id = c[0]
        .invoke::<Value>(
            "journal_entry_create",
            json!({ "entry": {
                "page_date": "2026-10-21", "text": "Went for a run.\n", "written_tz": "UTC",
                "written_offset_min": 0, "session_id": "create",
            }}),
        )
        .unwrap()["id"]
        .clone();
    c.sync(0, 1);
    for (d, text, ms) in [
        (0, "Went for a swim.\n", 1_000),
        (1, "Went for a cycle.\n", 2_000),
    ] {
        c[d].clock().advance(ms);
        c[d].invoke::<Value>(
            "journal_entry_update",
            json!({ "id": id, "text": text, "sessionId": format!("s{d}") }),
        )
        .unwrap();
    }
    c.sync(0, 1);
    c.sync(0, 1);
    let heard = heard.lock().unwrap().clone();
    assert_eq!(heard.len(), 1, "{heard:?}");
    assert_eq!(heard[0].0, 1, "only the device set to a toast");
    assert_eq!(heard[0].1["count"], 1);
    assert_eq!(heard[0].1["device"], "Mac");
}

src-tauri/src/test_support.rs::TestClock.source_code:
pub struct TestClock {
    /// Milliseconds added to the system clock.
    skew_ms: AtomicI64,
    /// When non-zero, the clock stands still at this instant.
    frozen_at: AtomicI64,
}

src-tauri/src/test_support.rs::TestClock.docstring:
/// The wall clock a [`TestApp`] stamps its change-log records with: the system clock plus a
/// skew, or frozen at a chosen instant. Lets a test (and later a cluster of `TestApp`s) make one
/// device's clock run ahead, stand still or lag behind another's.

src-tauri/src/test_support.rs::TestClock.source_code:
fn now(&self) -> i64 {
    match self.frozen_at.load(Ordering::SeqCst) {
        0 => now_ms() + self.skew_ms.load(Ordering::SeqCst),
        frozen => frozen,
    }
}

pub fn freeze(&self, ms: i64) {
    self.frozen_at.store(ms, Ordering::SeqCst);
}

pub fn advance(&self, ms: i64) {
    if self.frozen_at.load(Ordering::SeqCst) == 0 {
        self.skew_ms.fetch_add(ms, Ordering::SeqCst);
    } else {
        self.frozen_at.fetch_add(ms, Ordering::SeqCst);
    }
}

pub fn skew(&self, ms: i64) {
    self.frozen_at.store(0, Ordering::SeqCst);
    self.skew_ms.store(ms, Ordering::SeqCst);
}

