pub fn sync(&self, a: usize, b: usize) -> (SessionStats, SessionStats) {
    self.try_sync(a, b, None).unwrap()
}

pub fn sync_all(&self) {
    for _ in 0..2 {
        for a in 0..self.devices.len() {
            for b in (a + 1)..self.devices.len() {
                self.sync(a, b);
            }
        }
    }
}

