    let todo_tables: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM sqlite_master WHERE name = 'todo_tasks'",
            [],
            |r| r.get(0),
        )
        .unwrap();
    assert_eq!(todo_tables, 0, "the widget never migrates");
}

